-- =========================
-- posts 테이블 1
-- =========================
create table if not exists public.posts (
  id bigint generated always as identity primary key,
  title text not null check (char_length(trim(title)) >= 1),
  excerpt text not null default '',
  body text not null default '',
  category text not null check (category in ('study', 'work', 'event', 'career')),
  tags text[] not null default '{}',
  pinned boolean not null default false,
  views integer not null default 0,
  author_id uuid not null references auth.users(id) on delete cascade,
  author_nickname text not null default '익명',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists posts_author_id_idx on public.posts(author_id);
create index if not exists posts_category_idx on public.posts(category);
create index if not exists posts_created_at_idx on public.posts(created_at desc);
create index if not exists posts_pinned_idx on public.posts(pinned);

-- updated_at 자동 갱신
create or replace function public.handle_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists trg_posts_updated_at on public.posts;
create trigger trg_posts_updated_at
before update on public.posts
for each row
execute function public.handle_updated_at();

-- =========================
-- RLS
-- =========================
alter table public.posts enable row level security;

-- 모두 읽기 가능
drop policy if exists "posts_select_all" on public.posts;
create policy "posts_select_all"
on public.posts
for select
to anon, authenticated
using (true);

-- 로그인 사용자만 자기 글 작성 가능
drop policy if exists "posts_insert_own" on public.posts;
create policy "posts_insert_own"
on public.posts
for insert
to authenticated
with check ((select auth.uid()) = author_id);

-- 로그인 사용자는 자기 글만 수정 가능
drop policy if exists "posts_update_own" on public.posts;
create policy "posts_update_own"
on public.posts
for update
to authenticated
using ((select auth.uid()) = author_id)
with check ((select auth.uid()) = author_id);

-- 로그인 사용자는 자기 글만 삭제 가능
drop policy if exists "posts_delete_own" on public.posts;
create policy "posts_delete_own"
on public.posts
for delete
to authenticated
using ((select auth.uid()) = author_id);

create or replace function public.increment_post_views(p_post_id bigint)
returns bigint
language plpgsql
security definer
set search_path = public
as $$
declare
  new_views bigint;
begin
  update public.posts
  set views = coalesce(views, 0) + 1
  where id = p_post_id
  returning views into new_views;

  return coalesce(new_views, 0);
end;
$$;

grant execute on function public.increment_post_views(bigint) to anon, authenticated;

create table if not exists public.post_comments (
  id bigint generated by default as identity primary key,
  post_id bigint not null references public.posts(id) on delete cascade,
  body text not null,
  author_id uuid not null,
  author_nickname text not null default '익명',
  created_at timestamptz not null default now()
);

create index if not exists idx_post_comments_post_id
  on public.post_comments(post_id);

alter table public.post_comments enable row level security;

create policy "댓글 조회는 모두 가능"
on public.post_comments
for select
to anon, authenticated
using (true);

create policy "로그인 사용자는 댓글 작성 가능"
on public.post_comments
for insert
to authenticated
with check (auth.uid() = author_id);

alter table public.post_comments enable row level security;

drop policy if exists "댓글 수정은 작성자만 가능" on public.post_comments;
create policy "댓글 수정은 작성자만 가능"
on public.post_comments
for update
to authenticated
using (auth.uid() = author_id)
with check (auth.uid() = author_id);

drop policy if exists "댓글 삭제는 작성자만 가능" on public.post_comments;
create policy "댓글 삭제는 작성자만 가능"
on public.post_comments
for delete
to authenticated
using (auth.uid() = author_id);

-- =========================================
-- profiles 테이블
-- auth.users의 이메일 / 닉네임을 public 쪽에 동기화
-- =========================================

create table if not exists public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  email text not null,
  nickname text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- lower 기준 유니크 (대소문자 무시)
create unique index if not exists profiles_email_unique_idx
  on public.profiles (lower(email));

create unique index if not exists profiles_nickname_unique_idx
  on public.profiles (lower(nickname));

drop trigger if exists trg_profiles_updated_at on public.profiles;
create trigger trg_profiles_updated_at
before update on public.profiles
for each row
execute function public.handle_updated_at();

alter table public.profiles enable row level security;

-- 본인 프로필만 조회 가능
drop policy if exists "profiles_select_own" on public.profiles;
create policy "profiles_select_own"
on public.profiles
for select
to authenticated
using (auth.uid() = id);

-- 본인 프로필만 수정 가능
drop policy if exists "profiles_update_own" on public.profiles;
create policy "profiles_update_own"
on public.profiles
for update
to authenticated
using (auth.uid() = id)
with check (auth.uid() = id);

-- =========================================
-- auth.users -> public.profiles 동기화 함수
-- 회원가입 / 사용자정보 수정 시 자동 반영
-- =========================================

create or replace function public.sync_profile_from_auth_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_nickname text;
begin
  v_nickname := nullif(trim(coalesce(new.raw_user_meta_data->>'nickname', '')), '');

  if v_nickname is null then
    v_nickname := split_part(coalesce(new.email, ''), '@', 1);
  end if;

  insert into public.profiles (id, email, nickname, created_at, updated_at)
  values (new.id, coalesce(new.email, ''), v_nickname, now(), now())
  on conflict (id)
  do update set
    email = excluded.email,
    nickname = excluded.nickname,
    updated_at = now();

  return new;
end;
$$;

drop trigger if exists on_auth_user_created_sync_profile on auth.users;
create trigger on_auth_user_created_sync_profile
after insert on auth.users
for each row
execute function public.sync_profile_from_auth_user();

drop trigger if exists on_auth_user_updated_sync_profile on auth.users;
create trigger on_auth_user_updated_sync_profile
after update of email, raw_user_meta_data on auth.users
for each row
execute function public.sync_profile_from_auth_user();

-- =========================================
-- 가입 가능 여부 확인용 RPC
-- anon도 호출 가능하게 security definer 사용
-- exclude_user_id는 마이페이지 닉네임 변경 때 사용
-- =========================================

create or replace function public.check_account_availability(
  p_email text default null,
  p_nickname text default null,
  p_exclude_user_id uuid default null
)
returns table (
  email_exists boolean,
  nickname_exists boolean
)
language plpgsql
security definer
set search_path = public
as $$
begin
  return query
  select
    exists (
      select 1
      from public.profiles
      where p_email is not null
        and lower(email) = lower(trim(p_email))
        and (p_exclude_user_id is null or id <> p_exclude_user_id)
    ) as email_exists,
    exists (
      select 1
      from public.profiles
      where p_nickname is not null
        and lower(nickname) = lower(trim(p_nickname))
        and (p_exclude_user_id is null or id <> p_exclude_user_id)
    ) as nickname_exists;
end;
$$;

grant execute on function public.check_account_availability(text, text, uuid)
to anon, authenticated;

-- =========================================
-- 기존 auth.users 데이터를 profiles로 한 번 밀어넣기
-- 이미 있으면 업데이트
-- =========================================

insert into public.profiles (id, email, nickname, created_at, updated_at)
select
  u.id,
  coalesce(u.email, ''),
  coalesce(nullif(trim(u.raw_user_meta_data->>'nickname'), ''), split_part(coalesce(u.email, ''), '@', 1)),
  now(),
  now()
from auth.users u
on conflict (id)
do update set
  email = excluded.email,
  nickname = excluded.nickname,
  updated_at = now();

  -- =========================================
-- 닉네임 변경 시 기존 게시물 / 댓글 작성자명 자동 동기화
-- =========================================

create or replace function public.sync_author_nickname_from_profile()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  -- nickname이 비어 있으면 아무 것도 하지 않음
  if new.nickname is null or btrim(new.nickname) = '' then
    return new;
  end if;

  -- 닉네임이 실제로 바뀐 경우에만 실행
  if tg_op = 'UPDATE' and coalesce(old.nickname, '') = coalesce(new.nickname, '') then
    return new;
  end if;

  -- 기존 게시물 작성자명 일괄 변경
  update public.posts
  set
    author_nickname = new.nickname,
    updated_at = now()
  where author_id = new.id;

  -- 기존 댓글 작성자명 일괄 변경
  update public.post_comments
  set author_nickname = new.nickname
  where author_id = new.id;

  return new;
end;
$$;

drop trigger if exists trg_profiles_sync_author_nickname on public.profiles;

create trigger trg_profiles_sync_author_nickname
after update of nickname on public.profiles
for each row
execute function public.sync_author_nickname_from_profile();

-- =========================================
-- 이미 가입된 기존 유저들의 글/댓글 닉네임도 현재 profiles 기준으로 1회 정리
-- =========================================

update public.posts p
set
  author_nickname = pr.nickname,
  updated_at = now()
from public.profiles pr
where p.author_id = pr.id
  and coalesce(p.author_nickname, '') <> coalesce(pr.nickname, '');

update public.post_comments c
set author_nickname = pr.nickname
from public.profiles pr
where c.author_id = pr.id
  and coalesce(c.author_nickname, '') <> coalesce(pr.nickname, '');

  -- =========================================================
-- 1. profiles에 관리자 여부 컬럼 추가
-- =========================================================
alter table public.profiles
add column if not exists is_admin boolean not null default false;

comment on column public.profiles.is_admin is '사이트 관리자 여부';

-- =========================================================
-- 2. 관리자 판별 함수
-- =========================================================
create or replace function public.is_admin_user(p_user_id uuid default auth.uid())
returns boolean
language sql
security definer
set search_path = public
stable
as $$
  select exists (
    select 1
    from public.profiles
    where id = p_user_id
      and is_admin = true
  );
$$;

grant execute on function public.is_admin_user(uuid) to anon, authenticated;

-- =========================================================
-- 3. posts에서 pinned를 일반유저가 못 건드리게 막는 트리거 함수
--    - insert 시 일반유저가 pinned=true 넣으면 에러
--    - update 시 일반유저가 pinned 값 바꾸면 에러
-- =========================================================
create or replace function public.guard_posts_pinned_admin_only()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  -- 로그인 사용자 기준
  if public.is_admin_user(auth.uid()) then
    return new;
  end if;

  -- 일반 유저는 insert 시 pinned=true 금지
  if tg_op = 'INSERT' then
    if coalesce(new.pinned, false) = true then
      raise exception 'pinned는 관리자만 설정할 수 있어.';
    end if;

    return new;
  end if;

  -- 일반 유저는 update 시 pinned 값 변경 금지
  if tg_op = 'UPDATE' then
    if coalesce(new.pinned, false) <> coalesce(old.pinned, false) then
      raise exception 'pinned 변경은 관리자만 할 수 있어.';
    end if;

    return new;
  end if;

  return new;
end;
$$;

drop trigger if exists trg_guard_posts_pinned_admin_only on public.posts;

create trigger trg_guard_posts_pinned_admin_only
before insert or update on public.posts
for each row
execute function public.guard_posts_pinned_admin_only();

-- =========================================================
-- 4. posts RLS 정책 재정리
-- =========================================================
alter table public.posts enable row level security;

-- 조회: 모두 가능
drop policy if exists "posts_select_all" on public.posts;
create policy "posts_select_all"
on public.posts
for select
to anon, authenticated
using (true);

-- 작성: 로그인 사용자 본인 author_id로만 작성 가능
drop policy if exists "posts_insert_own" on public.posts;
create policy "posts_insert_own"
on public.posts
for insert
to authenticated
with check (auth.uid() = author_id);

-- 수정: 작성자 본인 또는 관리자
drop policy if exists "posts_update_own" on public.posts;
drop policy if exists "posts_update_owner_or_admin" on public.posts;
create policy "posts_update_owner_or_admin"
on public.posts
for update
to authenticated
using (
  auth.uid() = author_id
  or public.is_admin_user(auth.uid())
)
with check (
  auth.uid() = author_id
  or public.is_admin_user(auth.uid())
);

-- 삭제: 작성자 본인 또는 관리자
drop policy if exists "posts_delete_own" on public.posts;
drop policy if exists "posts_delete_owner_or_admin" on public.posts;
create policy "posts_delete_owner_or_admin"
on public.posts
for delete
to authenticated
using (
  auth.uid() = author_id
  or public.is_admin_user(auth.uid())
);

-- =========================================================
-- 5. 관리자 여부 확인용 RPC
--    프론트에서 관리자 UI 노출 여부 판단할 때 사용
-- =========================================================
create or replace function public.get_my_role()
returns table (
  is_admin boolean
)
language sql
security definer
set search_path = public
stable
as $$
  select public.is_admin_user(auth.uid()) as is_admin;
$$;

grant execute on function public.get_my_role() to authenticated;

-- =========================================================
-- 6. 내가 관리자면 특정 사용자 관리자 지정/해제는
--    일단 SQL Editor에서 직접 처리하는 방식으로 가는 게 안전함
--    아래는 수동 예시
-- =========================================================
-- 특정 유저를 관리자로 지정할 때:
-- update public.profiles
-- set is_admin = true
-- where email = '네이메일@example.com';

-- 관리자 해제할 때:
-- update public.profiles
-- set is_admin = false
-- where email = '네이메일@example.com';

update public.profiles
set is_admin = true
where email = 'junna961@icloud.com';

select email, nickname, is_admin
from public.profiles
order by created_at asc;

update public.profiles
set is_admin = true
where email = 'junna961@icloud.com';

select email, nickname, is_admin
from public.profiles
order by created_at asc;

