-- =========================================================
create table if not exists public.suggestions (
  id bigint generated by default as identity primary key,
  body text not null check (char_length(trim(body)) >= 1 and char_length(body) <= 1000),
  author_id uuid not null references auth.users(id) on delete cascade,
  author_nickname text not null default '익명',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists suggestions_author_id_idx
  on public.suggestions(author_id);

create index if not exists suggestions_created_at_idx
  on public.suggestions(created_at desc);

drop trigger if exists trg_suggestions_updated_at on public.suggestions;
create trigger trg_suggestions_updated_at
before update on public.suggestions
for each row
execute function public.handle_updated_at();

alter table public.suggestions enable row level security;

drop policy if exists "건의사항 조회는 모두 가능" on public.suggestions;
create policy "건의사항 조회는 모두 가능"
on public.suggestions
for select
to anon, authenticated
using (true);

drop policy if exists "로그인 사용자는 건의사항 작성 가능" on public.suggestions;
create policy "로그인 사용자는 건의사항 작성 가능"
on public.suggestions
for insert
to authenticated
with check (auth.uid() = author_id);

drop policy if exists "건의사항 수정은 작성자만 가능" on public.suggestions;
create policy "건의사항 수정은 작성자만 가능"
on public.suggestions
for update
to authenticated
using (auth.uid() = author_id)
with check (auth.uid() = author_id);

drop policy if exists "건의사항 삭제는 작성자 또는 관리자 가능" on public.suggestions;
create policy "건의사항 삭제는 작성자 또는 관리자 가능"
on public.suggestions
for delete
to authenticated
using (
  auth.uid() = author_id
  or public.is_admin_user(auth.uid())
);

-- =========================================================
-- 건의사항 관리자 댓글 테이블
-- =========================================================
create table if not exists public.suggestion_admin_comments (
  id bigint generated by default as identity primary key,
  suggestion_id bigint not null references public.suggestions(id) on delete cascade,
  body text not null check (char_length(trim(body)) >= 1 and char_length(body) <= 500),
  author_id uuid not null references auth.users(id) on delete cascade,
  author_nickname text not null default '관리자',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists suggestion_admin_comments_suggestion_id_idx
  on public.suggestion_admin_comments(suggestion_id);

create index if not exists suggestion_admin_comments_created_at_idx
  on public.suggestion_admin_comments(created_at asc);

drop trigger if exists trg_suggestion_admin_comments_updated_at on public.suggestion_admin_comments;
create trigger trg_suggestion_admin_comments_updated_at
before update on public.suggestion_admin_comments
for each row
execute function public.handle_updated_at();

alter table public.suggestion_admin_comments enable row level security;

drop policy if exists "건의사항 관리자 댓글 조회는 모두 가능" on public.suggestion_admin_comments;
create policy "건의사항 관리자 댓글 조회는 모두 가능"
on public.suggestion_admin_comments
for select
to anon, authenticated
using (true);

drop policy if exists "관리자만 건의사항 댓글 작성 가능" on public.suggestion_admin_comments;
create policy "관리자만 건의사항 댓글 작성 가능"
on public.suggestion_admin_comments
for insert
to authenticated
with check (
  auth.uid() = author_id
  and public.is_admin_user(auth.uid())
);

drop policy if exists "관리자만 건의사항 댓글 수정 가능" on public.suggestion_admin_comments;
create policy "관리자만 건의사항 댓글 수정 가능"
on public.suggestion_admin_comments
for update
to authenticated
using (public.is_admin_user(auth.uid()))
with check (public.is_admin_user(auth.uid()));

drop policy if exists "관리자만 건의사항 댓글 삭제 가능" on public.suggestion_admin_comments;
create policy "관리자만 건의사항 댓글 삭제 가능"
on public.suggestion_admin_comments
for delete
to authenticated
using (public.is_admin_user(auth.uid()));

-- =========================================================
-- 닉네임 변경 시 건의사항/관리자댓글 작성자명도 동기화
-- 기존 함수 교체
-- =========================================================
create or replace function public.sync_author_nickname_from_profile()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.nickname is null or btrim(new.nickname) = '' then
    return new;
  end if;

  if tg_op = 'UPDATE'
     and coalesce(old.nickname, '') = coalesce(new.nickname, '') then
    return new;
  end if;

  update public.posts
  set
    author_nickname = new.nickname,
    updated_at = now()
  where author_id = new.id;

  update public.post_comments
  set author_nickname = new.nickname
  where author_id = new.id;

  update public.suggestions
  set
    author_nickname = new.nickname,
    updated_at = now()
  where author_id = new.id;

  update public.suggestion_admin_comments
  set
    author_nickname = new.nickname,
    updated_at = now()
  where author_id = new.id;

  return new;
end;
$$;

drop trigger if exists trg_profiles_sync_author_nickname on public.profiles;

create trigger trg_profiles_sync_author_nickname
after update of nickname on public.profiles
for each row
execute function public.sync_author_nickname_from_profile();

-- =========================================================
-- 기존 유저 데이터 닉네임 1회 동기화
-- =========================================================
update public.suggestions s
set
  author_nickname = p.nickname,
  updated_at = now()
from public.profiles p
where s.author_id = p.id
  and coalesce(s.author_nickname, '') <> coalesce(p.nickname, '');

update public.suggestion_admin_comments c
set
  author_nickname = p.nickname,
  updated_at = now()
from public.profiles p
where c.author_id = p.id
  and coalesce(c.author_nickname, '') <> coalesce(p.nickname, '');

  alter table public.suggestions enable row level security;

