-- 1. posts 테이블에 첨부 컬럼 추가
-- =========================================================
alter table public.posts
add column if not exists media_items jsonb not null default '[]'::jsonb;

comment on column public.posts.media_items is
'게시물 첨부 목록(JSONB 배열). image, video, file, link, map 타입 저장';

update public.posts
set media_items = '[]'::jsonb
where media_items is null;

do $$
begin
  if not exists (
    select 1
    from pg_constraint
    where conname = 'posts_media_items_is_array'
  ) then
    alter table public.posts
    add constraint posts_media_items_is_array
    check (jsonb_typeof(media_items) = 'array');
  end if;
end $$;

