-- =========================================
-- post_comments : 대댓글(답글) 지원
--  - parent_comment_id 추가
--  - 같은 post 안에서만 답글 가능
--  - 답글의 답글은 금지 (1단계까지만)
-- =========================================

alter table public.post_comments
add column if not exists parent_comment_id bigint null references public.post_comments(id) on delete cascade;

create index if not exists idx_post_comments_parent_comment_id
  on public.post_comments(parent_comment_id);

-- 자기 자신을 부모로 지정 금지
do $$
begin
  if not exists (
    select 1
    from pg_constraint
    where conname = 'post_comments_parent_not_self_chk'
  ) then
    alter table public.post_comments
    add constraint post_comments_parent_not_self_chk
    check (
      parent_comment_id is null or parent_comment_id <> id
    );
  end if;
end $$;

-- 부모 댓글 검증 함수
create or replace function public.validate_post_comment_parent()
returns trigger
language plpgsql
as $$
declare
  v_parent_post_id bigint;
  v_parent_parent_id bigint;
begin
  -- 일반 댓글이면 통과
  if new.parent_comment_id is null then
    return new;
  end if;

  -- 부모 댓글 조회
  select post_id, parent_comment_id
    into v_parent_post_id, v_parent_parent_id
  from public.post_comments
  where id = new.parent_comment_id;

  -- 부모 댓글이 없으면 에러
  if v_parent_post_id is null then
    raise exception '부모 댓글을 찾을 수 없어.';
  end if;

  -- 같은 게시글 안에서만 답글 허용
  if v_parent_post_id <> new.post_id then
    raise exception '다른 게시글의 댓글에는 답글을 달 수 없어.';
  end if;

  -- 답글의 답글 금지 (1단계까지만)
  if v_parent_parent_id is not null then
    raise exception '답글에는 다시 답글을 달 수 없어.';
  end if;

  return new;
end;
$$;

drop trigger if exists trg_validate_post_comment_parent on public.post_comments;
create trigger trg_validate_post_comment_parent
before insert or update on public.post_comments
for each row
execute function public.validate_post_comment_parent();

-- =========================================================
-- post_comments : 무한 답글 가능 + 같은 폭 답글 리스트 구조
-- - parent_comment_id : 루트(원댓글) id
-- - reply_to_comment_id : 실제 답글 대상 댓글 id
-- - reply_to_nickname : 답글 대상 닉네임 표시용
-- =========================================================

alter table public.post_comments
add column if not exists reply_to_comment_id bigint null
references public.post_comments(id) on delete set null;

alter table public.post_comments
add column if not exists reply_to_nickname text null;

create index if not exists idx_post_comments_reply_to_comment_id
  on public.post_comments(reply_to_comment_id);

-- =========================================================
-- 기존 1단계 답글 데이터 보정
-- - 기존 parent_comment_id가 있던 행은
--   reply_to_comment_id = parent_comment_id 로 맞춤
-- =========================================================

update public.post_comments c
set reply_to_comment_id = c.parent_comment_id
where c.parent_comment_id is not null
  and c.reply_to_comment_id is null;

update public.post_comments c
set reply_to_nickname = p.author_nickname
from public.post_comments p
where c.reply_to_comment_id = p.id
  and c.reply_to_nickname is null;

-- =========================================================
-- 검증 함수
-- - 일반 댓글: parent_comment_id null
-- - 답글: parent_comment_id는 반드시 "루트 댓글" id
-- - reply_to_comment_id는 같은 post 안의 댓글이어야 함
-- - reply_to_comment_id가 루트 또는 그 루트의 답글이어야 함
-- =========================================================

create or replace function public.validate_post_comment_thread()
returns trigger
language plpgsql
as $$
declare
  v_root_id bigint;
  v_root_post_id bigint;
  v_root_parent_id bigint;

  v_target_id bigint;
  v_target_post_id bigint;
  v_target_parent_id bigint;
  v_target_author_nickname text;
begin
  -- 일반 댓글
  if new.parent_comment_id is null then
    new.reply_to_comment_id := null;
    new.reply_to_nickname := null;
    return new;
  end if;

  -- 루트 댓글 검증
  select id, post_id, parent_comment_id
    into v_root_id, v_root_post_id, v_root_parent_id
  from public.post_comments
  where id = new.parent_comment_id;

  if v_root_id is null then
    raise exception '루트 댓글을 찾을 수 없어.';
  end if;

  if v_root_post_id <> new.post_id then
    raise exception '다른 게시글의 댓글 스레드에는 답글을 달 수 없어.';
  end if;

  -- parent_comment_id는 반드시 최상위 댓글이어야 함
  if v_root_parent_id is not null then
    raise exception 'parent_comment_id는 최상위 댓글이어야 해.';
  end if;

  -- reply_to_comment_id가 비어 있으면 루트 댓글에 답글 단 것으로 처리
  if new.reply_to_comment_id is null then
    new.reply_to_comment_id := new.parent_comment_id;
  end if;

  -- 실제 답글 대상 검증
  select id, post_id, parent_comment_id, author_nickname
    into v_target_id, v_target_post_id, v_target_parent_id, v_target_author_nickname
  from public.post_comments
  where id = new.reply_to_comment_id;

  if v_target_id is null then
    raise exception '답글 대상 댓글을 찾을 수 없어.';
  end if;

  if v_target_post_id <> new.post_id then
    raise exception '다른 게시글의 댓글에는 답글을 달 수 없어.';
  end if;

  -- 답글 대상은 같은 루트 스레드 안에 있어야 함
  if not (
    v_target_id = new.parent_comment_id
    or v_target_parent_id = new.parent_comment_id
  ) then
    raise exception '같은 댓글 스레드 안에서만 답글을 달 수 있어.';
  end if;

  -- reply_to_nickname 자동 보정
  if nullif(btrim(coalesce(new.reply_to_nickname, '')), '') is null then
    new.reply_to_nickname := coalesce(v_target_author_nickname, '익명');
  end if;

  return new;
end;
$$;

drop trigger if exists trg_validate_post_comment_parent on public.post_comments;
drop trigger if exists trg_validate_post_comment_thread on public.post_comments;

create trigger trg_validate_post_comment_thread
before insert or update on public.post_comments
for each row
execute function public.validate_post_comment_thread();

-- =========================================
-- posts.updated_at 자동 갱신 함수/트리거 재확인
-- 이미 있으면 교체
-- =========================================

create or replace function public.handle_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists trg_posts_updated_at on public.posts;
create trigger trg_posts_updated_at
before update on public.posts
for each row
execute function public.handle_updated_at();

-- 기존 데이터 중 updated_at이 비어 있거나 created_at보다 이상한 경우 정리
update public.posts
set updated_at = coalesce(updated_at, created_at, now())
where updated_at is null;

-- =========================================================
-- post_comments 에 updated_at 추가 + 자동 갱신 트리거
-- =========================================================

alter table public.post_comments
add column if not exists updated_at timestamptz not null default now();

update public.post_comments
set updated_at = coalesce(updated_at, created_at, now())
where updated_at is null;

drop trigger if exists trg_post_comments_updated_at on public.post_comments;
create trigger trg_post_comments_updated_at
before update on public.post_comments
for each row
execute function public.handle_updated_at();

-- =========================================
-- account recovery 확장
-- - 이름 / 생년월일 / 아이디찾기 질문 / 답변해시 저장
-- - 아이디 찾기용 RPC 2개 추가
-- =========================================

create extension if not exists pgcrypto;

-- -----------------------------------------
-- 1. 공용 정규화 함수
-- -----------------------------------------
create or replace function public.normalize_birth_key(p_value text)
returns text
language sql
immutable
as $$
  select regexp_replace(coalesce(p_value, ''), '[^0-9]', '', 'g');
$$;

create or replace function public.normalize_recovery_answer(p_value text)
returns text
language sql
immutable
as $$
  select lower(trim(regexp_replace(coalesce(p_value, ''), '\s+', ' ', 'g')));
$$;

create or replace function public.mask_email(p_email text)
returns text
language plpgsql
immutable
as $$
declare
  v_email text := coalesce(trim(p_email), '');
  v_local text;
  v_domain text;
  v_domain_name text;
  v_tld text;
begin
  if v_email = '' or position('@' in v_email) = 0 then
    return '';
  end if;

  v_local := split_part(v_email, '@', 1);
  v_domain := split_part(v_email, '@', 2);
  v_domain_name := split_part(v_domain, '.', 1);
  v_tld := regexp_replace(v_domain, '^[^.]+\.', '');

  if char_length(v_local) <= 1 then
    v_local := '*';
  else
    v_local := left(v_local, 1) || repeat('*', greatest(char_length(v_local) - 1, 1));
  end if;

  if char_length(v_domain_name) <= 1 then
    v_domain_name := '*';
  else
    v_domain_name := left(v_domain_name, 1) || repeat('*', greatest(char_length(v_domain_name) - 1, 1));
  end if;

  if v_tld = '' then
    return v_local || '@' || v_domain_name;
  end if;

  return v_local || '@' || v_domain_name || '.' || v_tld;
end;
$$;

-- -----------------------------------------
-- 2. profiles 컬럼 추가
-- -----------------------------------------
alter table public.profiles
add column if not exists real_name text,
add column if not exists birth_key text,
add column if not exists recovery_question text,
add column if not exists recovery_answer_hash text;

comment on column public.profiles.real_name is '회원가입 시 입력한 이름';
comment on column public.profiles.birth_key is '생년월일 6자리 + 뒤 1자리(숫자만 저장)';
comment on column public.profiles.recovery_question is '아이디 찾기 질문 키';
comment on column public.profiles.recovery_answer_hash is '아이디 찾기 답변 sha256 hex';

create index if not exists profiles_real_name_idx
  on public.profiles (lower(real_name));

create index if not exists profiles_birth_key_idx
  on public.profiles (birth_key);

create index if not exists profiles_real_name_birth_key_idx
  on public.profiles (lower(real_name), birth_key);

-- -----------------------------------------
-- 3. auth.users -> public.profiles 동기화 함수 교체
-- -----------------------------------------
create or replace function public.sync_profile_from_auth_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_nickname text;
  v_real_name text;
  v_birth_key text;
  v_recovery_question text;
  v_recovery_answer_hash text;
begin
  v_nickname := nullif(trim(coalesce(new.raw_user_meta_data->>'nickname', '')), '');
  if v_nickname is null then
    v_nickname := split_part(coalesce(new.email, ''), '@', 1);
  end if;

  v_real_name := nullif(trim(coalesce(new.raw_user_meta_data->>'real_name', '')), '');
  v_birth_key := nullif(public.normalize_birth_key(new.raw_user_meta_data->>'birth_key'), '');
  v_recovery_question := nullif(trim(coalesce(new.raw_user_meta_data->>'recovery_question', '')), '');
  v_recovery_answer_hash := nullif(trim(coalesce(new.raw_user_meta_data->>'recovery_answer_hash', '')), '');

  insert into public.profiles (
    id,
    email,
    nickname,
    real_name,
    birth_key,
    recovery_question,
    recovery_answer_hash,
    created_at,
    updated_at
  )
  values (
    new.id,
    coalesce(new.email, ''),
    v_nickname,
    v_real_name,
    v_birth_key,
    v_recovery_question,
    v_recovery_answer_hash,
    now(),
    now()
  )
  on conflict (id)
  do update set
    email = excluded.email,
    nickname = excluded.nickname,
    real_name = excluded.real_name,
    birth_key = excluded.birth_key,
    recovery_question = excluded.recovery_question,
    recovery_answer_hash = excluded.recovery_answer_hash,
    updated_at = now();

  return new;
end;
$$;

drop trigger if exists on_auth_user_created_sync_profile on auth.users;
create trigger on_auth_user_created_sync_profile
after insert on auth.users
for each row
execute function public.sync_profile_from_auth_user();

drop trigger if exists on_auth_user_updated_sync_profile on auth.users;
create trigger on_auth_user_updated_sync_profile
after update of email, raw_user_meta_data on auth.users
for each row
execute function public.sync_profile_from_auth_user();

-- -----------------------------------------
-- 4. 기존 사용자 1회 동기화
-- -----------------------------------------
insert into public.profiles (
  id,
  email,
  nickname,
  real_name,
  birth_key,
  recovery_question,
  recovery_answer_hash,
  created_at,
  updated_at
)
select
  u.id,
  coalesce(u.email, ''),
  coalesce(
    nullif(trim(u.raw_user_meta_data->>'nickname'), ''),
    split_part(coalesce(u.email, ''), '@', 1)
  ),
  nullif(trim(u.raw_user_meta_data->>'real_name'), ''),
  nullif(public.normalize_birth_key(u.raw_user_meta_data->>'birth_key'), ''),
  nullif(trim(u.raw_user_meta_data->>'recovery_question'), ''),
  nullif(trim(u.raw_user_meta_data->>'recovery_answer_hash'), ''),
  now(),
  now()
from auth.users u
on conflict (id)
do update set
  email = excluded.email,
  nickname = excluded.nickname,
  real_name = excluded.real_name,
  birth_key = excluded.birth_key,
  recovery_question = excluded.recovery_question,
  recovery_answer_hash = excluded.recovery_answer_hash,
  updated_at = now();

-- -----------------------------------------
-- 5. 아이디 찾기 1단계 RPC
-- - 이름 + 생년월일로 질문/마스킹 이메일 조회
-- - 동명이인 + 동일 birth_key 복수면 ambiguous=true
-- -----------------------------------------
create or replace function public.find_id_recovery_start(
  p_real_name text,
  p_birth_key text
)
returns table (
  found boolean,
  ambiguous boolean,
  masked_email text,
  recovery_question text,
  recovery_question_label text
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_name text := nullif(trim(coalesce(p_real_name, '')), '');
  v_birth text := nullif(public.normalize_birth_key(p_birth_key), '');
  v_count integer := 0;
begin
  if v_name is null or v_birth is null then
    return query
    select false, false, null::text, null::text, null::text;
    return;
  end if;

  select count(*)
    into v_count
  from public.profiles
  where lower(real_name) = lower(v_name)
    and birth_key = v_birth;

  if v_count = 0 then
    return query
    select false, false, null::text, null::text, null::text;
    return;
  end if;

  if v_count > 1 then
    return query
    select true, true, null::text, null::text, null::text;
    return;
  end if;

  return query
  select
    true as found,
    false as ambiguous,
    public.mask_email(email) as masked_email,
    recovery_question,
    case recovery_question
      when 'father_name' then '아버지의 성함'
      when 'favorite_item' then '좋아하는 물건'
      when 'hometown' then '나의 고향'
      when 'elementary_school' then '초등학교 이름'
      else '가입 시 선택한 질문'
    end as recovery_question_label
  from public.profiles
  where lower(real_name) = lower(v_name)
    and birth_key = v_birth
  limit 1;
end;
$$;

grant execute on function public.find_id_recovery_start(text, text)
to anon, authenticated;

-- -----------------------------------------
-- 6. 아이디 찾기 2단계 RPC
-- - 질문 + 답변해시 검증 후 이메일 반환
-- -----------------------------------------
create or replace function public.verify_id_recovery(
  p_real_name text,
  p_birth_key text,
  p_recovery_question text,
  p_recovery_answer_hash text
)
returns table (
  found boolean,
  ambiguous boolean,
  success boolean,
  email text
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_name text := nullif(trim(coalesce(p_real_name, '')), '');
  v_birth text := nullif(public.normalize_birth_key(p_birth_key), '');
  v_question text := nullif(trim(coalesce(p_recovery_question, '')), '');
  v_answer_hash text := nullif(trim(coalesce(p_recovery_answer_hash, '')), '');
  v_count integer := 0;
begin
  if v_name is null or v_birth is null or v_question is null or v_answer_hash is null then
    return query
    select false, false, false, null::text;
    return;
  end if;

  select count(*)
    into v_count
  from public.profiles
  where lower(real_name) = lower(v_name)
    and birth_key = v_birth;

  if v_count = 0 then
    return query
    select false, false, false, null::text;
    return;
  end if;

  if v_count > 1 then
    return query
    select true, true, false, null::text;
    return;
  end if;

  return query
  select
    true as found,
    false as ambiguous,
    (
      recovery_question = v_question
      and recovery_answer_hash = v_answer_hash
      and recovery_answer_hash is not null
    ) as success,
    case
      when recovery_question = v_question
      and recovery_answer_hash = v_answer_hash
      and recovery_answer_hash is not null
      then email
      else null::text
    end as email
  from public.profiles
  where lower(real_name) = lower(v_name)
    and birth_key = v_birth
  limit 1;
end;
$$;

grant execute on function public.verify_id_recovery(text, text, text, text)
to anon, authenticated;

