      when 'elementary_school' then '초등학교 이름'
      when 'hometown' then '나의 고향'
      when 'birthplace' then '태어난 곳'
      else '가입 시 선택한 질문'
    end as recovery_question_label
  from public.profiles
  where lower(real_name) = lower(v_name)
    and birth_key = v_birth
  limit 1;
end;
$$;

grant execute on function public.find_id_recovery_start(text, text)
to anon, authenticated;

-- -----------------------------------------
-- 6. 아이디 찾기 2단계 RPC
-- -----------------------------------------
create or replace function public.verify_id_recovery(
  p_real_name text,
  p_birth_key text,
  p_recovery_question text,
  p_recovery_answer_hash text
)
returns table (
  found boolean,
  ambiguous boolean,
  success boolean,
  email text
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_name text := nullif(trim(coalesce(p_real_name, '')), '');
  v_birth text := nullif(public.normalize_birth_key(p_birth_key), '');
  v_question text := nullif(trim(coalesce(p_recovery_question, '')), '');
  v_answer_hash text := nullif(trim(coalesce(p_recovery_answer_hash, '')), '');
  v_count integer := 0;
begin
  if v_name is null or v_birth is null or v_question is null or v_answer_hash is null then
    return query
    select false, false, false, null::text;
    return;
  end if;

  select count(*)
    into v_count
  from public.profiles
  where lower(real_name) = lower(v_name)
    and birth_key = v_birth;

  if v_count = 0 then
    return query
    select false, false, false, null::text;
    return;
  end if;

  if v_count > 1 then
    return query
    select true, true, false, null::text;
    return;
  end if;

  return query
  select
    true as found,
    false as ambiguous,
    (
      recovery_question = v_question
      and recovery_answer_hash = v_answer_hash
      and recovery_answer_hash is not null
    ) as success,
    case
      when recovery_question = v_question
      and recovery_answer_hash = v_answer_hash
      and recovery_answer_hash is not null
      then email
      else null::text
    end as email
  from public.profiles
  where lower(real_name) = lower(v_name)
    and birth_key = v_birth
  limit 1;
end;
$$;

grant execute on function public.verify_id_recovery(text, text, text, text)
to anon, authenticated;

