  -- =========================================
-- account recovery RPC 오류 수정 최종본
-- 핵심:
-- 1) recovery_question / recovery_answer_hash 컬럼 모호성 제거
-- 2) profiles 테이블 alias(p)로 전부 명확하게 참조
-- 3) 질문 라벨 확장
-- =========================================

create extension if not exists pgcrypto;

-- -----------------------------------------
-- 0. 보조 함수 (없으면 생성, 있으면 교체)
-- -----------------------------------------
create or replace function public.normalize_birth_key(p_value text)
returns text
language sql
immutable
as $$
  select regexp_replace(coalesce(p_value, ''), '[^0-9]', '', 'g');
$$;

create or replace function public.normalize_recovery_answer(p_value text)
returns text
language sql
immutable
as $$
  select lower(trim(regexp_replace(coalesce(p_value, ''), '\s+', ' ', 'g')));
$$;

create or replace function public.mask_email(p_email text)
returns text
language plpgsql
immutable
as $$
declare
  v_email text := coalesce(trim(p_email), '');
  v_local text;
  v_domain text;
  v_domain_name text;
  v_tld text;
begin
  if v_email = '' or position('@' in v_email) = 0 then
    return '';
  end if;

  v_local := split_part(v_email, '@', 1);
  v_domain := split_part(v_email, '@', 2);
  v_domain_name := split_part(v_domain, '.', 1);
  v_tld := regexp_replace(v_domain, '^[^.]+\.', '');

  if char_length(v_local) <= 1 then
    v_local := '*';
  else
    v_local := left(v_local, 1) || repeat('*', greatest(char_length(v_local) - 1, 1));
  end if;

  if char_length(v_domain_name) <= 1 then
    v_domain_name := '*';
  else
    v_domain_name := left(v_domain_name, 1) || repeat('*', greatest(char_length(v_domain_name) - 1, 1));
  end if;

  if v_tld = '' then
    return v_local || '@' || v_domain_name;
  end if;

  return v_local || '@' || v_domain_name || '.' || v_tld;
end;
$$;

-- -----------------------------------------
-- 1. profiles 컬럼 보정
-- -----------------------------------------
alter table public.profiles
add column if not exists real_name text,
add column if not exists birth_key text,
add column if not exists recovery_question text,
add column if not exists recovery_answer_hash text;

create index if not exists profiles_real_name_idx
  on public.profiles (lower(real_name));

create index if not exists profiles_birth_key_idx
  on public.profiles (birth_key);

create index if not exists profiles_real_name_birth_key_idx
  on public.profiles (lower(real_name), birth_key);

-- -----------------------------------------
-- 2. auth.users -> profiles 동기화 함수
-- -----------------------------------------
create or replace function public.sync_profile_from_auth_user()
returns trigger
language plpgsql
security definer
set search_path = public, auth
as $$
declare
  v_nickname text;
  v_real_name text;
  v_birth_key text;
  v_recovery_question text;
  v_recovery_answer_hash text;
begin
  v_nickname := nullif(trim(coalesce(new.raw_user_meta_data->>'nickname', '')), '');
  if v_nickname is null then
    v_nickname := split_part(coalesce(new.email, ''), '@', 1);
  end if;

  v_real_name := nullif(trim(coalesce(new.raw_user_meta_data->>'real_name', '')), '');
  v_birth_key := nullif(public.normalize_birth_key(new.raw_user_meta_data->>'birth_key'), '');
  v_recovery_question := nullif(trim(coalesce(new.raw_user_meta_data->>'recovery_question', '')), '');
  v_recovery_answer_hash := nullif(trim(coalesce(new.raw_user_meta_data->>'recovery_answer_hash', '')), '');

  insert into public.profiles (
    id,
    email,
    nickname,
    real_name,
    birth_key,
    recovery_question,
    recovery_answer_hash,
    created_at,
    updated_at
  )
  values (
    new.id,
    coalesce(new.email, ''),
    v_nickname,
    v_real_name,
    v_birth_key,
    v_recovery_question,
    v_recovery_answer_hash,
    now(),
    now()
  )
  on conflict (id)
  do update set
    email = excluded.email,
    nickname = excluded.nickname,
    real_name = excluded.real_name,
    birth_key = excluded.birth_key,
    recovery_question = excluded.recovery_question,
    recovery_answer_hash = excluded.recovery_answer_hash,
    updated_at = now();

  return new;
end;
$$;

drop trigger if exists on_auth_user_created_sync_profile on auth.users;
create trigger on_auth_user_created_sync_profile
after insert on auth.users
for each row
execute function public.sync_profile_from_auth_user();

drop trigger if exists on_auth_user_updated_sync_profile on auth.users;
create trigger on_auth_user_updated_sync_profile
after update of email, raw_user_meta_data on auth.users
for each row
execute function public.sync_profile_from_auth_user();

-- -----------------------------------------
-- 3. 기존 auth.users -> profiles 1회 동기화
-- -----------------------------------------
insert into public.profiles (
  id,
  email,
  nickname,
  real_name,
  birth_key,
  recovery_question,
  recovery_answer_hash,
  created_at,
  updated_at
)
select
  u.id,
  coalesce(u.email, ''),
  coalesce(
    nullif(trim(u.raw_user_meta_data->>'nickname'), ''),
    split_part(coalesce(u.email, ''), '@', 1)
  ) as nickname,
  nullif(trim(u.raw_user_meta_data->>'real_name'), '') as real_name,
  nullif(public.normalize_birth_key(u.raw_user_meta_data->>'birth_key'), '') as birth_key,
  nullif(trim(u.raw_user_meta_data->>'recovery_question'), '') as recovery_question,
  nullif(trim(u.raw_user_meta_data->>'recovery_answer_hash'), '') as recovery_answer_hash,
  now(),
  now()
from auth.users u
on conflict (id)
do update set
  email = excluded.email,
  nickname = excluded.nickname,
  real_name = excluded.real_name,
  birth_key = excluded.birth_key,
  recovery_question = excluded.recovery_question,
  recovery_answer_hash = excluded.recovery_answer_hash,
  updated_at = now();

-- -----------------------------------------
-- 4. 아이디 찾기 1단계 RPC
-- -----------------------------------------
create or replace function public.find_id_recovery_start(
  p_real_name text,
  p_birth_key text
)
returns table (
  found boolean,
  ambiguous boolean,
  masked_email text,
  recovery_question text,
  recovery_question_label text
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_name text := nullif(trim(coalesce(p_real_name, '')), '');
  v_birth text := nullif(public.normalize_birth_key(p_birth_key), '');
  v_count integer := 0;
begin
  if v_name is null or v_birth is null then
    return query
    select
      false as found,
      false as ambiguous,
      null::text as masked_email,
      null::text as recovery_question,
      null::text as recovery_question_label;
    return;
  end if;

  select count(*)
    into v_count
  from public.profiles p
  where lower(p.real_name) = lower(v_name)
    and p.birth_key = v_birth;

  if v_count = 0 then
    return query
    select
      false as found,
      false as ambiguous,
      null::text as masked_email,
      null::text as recovery_question,
      null::text as recovery_question_label;
    return;
  end if;

  if v_count > 1 then
    return query
    select
      true as found,
      true as ambiguous,
      null::text as masked_email,
      null::text as recovery_question,
      null::text as recovery_question_label;
    return;
  end if;

  return query
  select
    true as found,
    false as ambiguous,
    public.mask_email(p.email) as masked_email,
    p.recovery_question as recovery_question,
    case p.recovery_question
      when 'childhood_nickname' then '어릴 적 별명'
      when 'first_pet_name' then '처음 키운 반려동물 이름'
      when 'first_travel_place' then '처음으로 여행 간 곳'
      when 'special_treasure' then '소중하게 간직했던 물건'
      when 'childhood_dream' then '어릴 적 꿈'
      when 'treasure_no1' then '내 보물 1호'
      when 'favorite_item' then '좋아하는 물건'
      when 'favorite_food' then '가장 좋아하는 음식'
      when 'favorite_animal' then '가장 좋아하는 동물'
      when 'favorite_color' then '가장 좋아하는 색깔'
      when 'favorite_movie' then '가장 좋아하는 영화'
      when 'favorite_season' then '가장 좋아하는 계절'
      when 'best_subject' then '학창 시절 가장 좋아했던 과목'
      when 'memorable_place' then '기억에 남는 장소'
      when 'respect_person' then '가장 존경하는 사람'
      when 'father_name' then '아버지의 성함'
      when 'mother_name' then '어머니의 성함'
      when 'elementary_school' then '초등학교 이름'
      when 'hometown' then '나의 고향'
      when 'birthplace' then '태어난 곳'
      else '가입 시 선택한 질문'
    end as recovery_question_label
  from public.profiles p
  where lower(p.real_name) = lower(v_name)
    and p.birth_key = v_birth
  limit 1;
end;
$$;

grant execute on function public.find_id_recovery_start(text, text)
to anon, authenticated;

-- -----------------------------------------
-- 5. 아이디 찾기 2단계 RPC
-- -----------------------------------------
create or replace function public.verify_id_recovery(
  p_real_name text,
  p_birth_key text,
  p_recovery_question text,
  p_recovery_answer_hash text
)
returns table (
  found boolean,
  ambiguous boolean,
  success boolean,
  email text
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_name text := nullif(trim(coalesce(p_real_name, '')), '');
  v_birth text := nullif(public.normalize_birth_key(p_birth_key), '');
  v_question text := nullif(trim(coalesce(p_recovery_question, '')), '');
  v_answer_hash text := nullif(trim(coalesce(p_recovery_answer_hash, '')), '');
  v_count integer := 0;
begin
  if v_name is null or v_birth is null or v_question is null or v_answer_hash is null then
    return query
    select
      false as found,
      false as ambiguous,
      false as success,
      null::text as email;
    return;
  end if;

  select count(*)
    into v_count
  from public.profiles p
  where lower(p.real_name) = lower(v_name)
    and p.birth_key = v_birth;

  if v_count = 0 then
    return query
    select
      false as found,
      false as ambiguous,
      false as success,
      null::text as email;
    return;
  end if;

  if v_count > 1 then
    return query
    select
      true as found,
      true as ambiguous,
      false as success,
      null::text as email;
    return;
  end if;

  return query
  select
    true as found,
    false as ambiguous,
    (
      p.recovery_question = v_question
      and p.recovery_answer_hash = v_answer_hash
      and p.recovery_answer_hash is not null
    ) as success,
    case
      when p.recovery_question = v_question
       and p.recovery_answer_hash = v_answer_hash
       and p.recovery_answer_hash is not null
      then p.email
      else null::text
    end as email
  from public.profiles p
  where lower(p.real_name) = lower(v_name)
    and p.birth_key = v_birth
  limit 1;
end;
$$;

grant execute on function public.verify_id_recovery(text, text, text, text)
to anon, authenticated;

