-- -----------------------------------------
select
  email,
  nickname,
  real_name,
  birth_key,
  recovery_question,
  case
    when recovery_answer_hash is null or recovery_answer_hash = '' then '없음'
    else '있음'
  end as recovery_answer_hash_status
from public.profiles
order by created_at desc;

-- =========================================
-- 마이페이지 복구정보 설정 / 수정용 RPC
-- - 이름 / 생년월일: 최초 1회만 저장 가능
-- - 아이디 힌트 질문 / 답변: 계속 수정 가능
-- =========================================

create extension if not exists pgcrypto;

-- -----------------------------------------
-- 0. 보조 함수
-- -----------------------------------------
create or replace function public.normalize_birth_key(p_value text)
returns text
language sql
immutable
as $$
  select regexp_replace(coalesce(p_value, ''), '[^0-9]', '', 'g');
$$;

create or replace function public.get_my_recovery_profile()
returns table (
  email text,
  nickname text,
  real_name text,
  birth_key text,
  recovery_question text,
  has_recovery_answer boolean,
  can_set_identity boolean
)
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() is null then
    raise exception '로그인이 필요해.';
  end if;

  return query
  select
    p.email,
    p.nickname,
    p.real_name,
    p.birth_key,
    p.recovery_question,
    (p.recovery_answer_hash is not null and p.recovery_answer_hash <> '') as has_recovery_answer,
    (coalesce(trim(p.real_name), '') = '' and coalesce(trim(p.birth_key), '') = '') as can_set_identity
  from public.profiles p
  where p.id = auth.uid()
  limit 1;
end;
$$;

grant execute on function public.get_my_recovery_profile()
to authenticated;

-- -----------------------------------------
-- 1. 내 복구정보 저장
-- -----------------------------------------
create or replace function public.update_my_recovery_profile(
  p_real_name text default null,
  p_birth_key text default null,
  p_recovery_question text default null,
  p_recovery_answer_hash text default null
)
returns table (
  success boolean,
  message text,
  real_name text,
  birth_key text,
  recovery_question text,
  can_set_identity boolean
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_profile public.profiles%rowtype;
  v_real_name text := nullif(trim(coalesce(p_real_name, '')), '');
  v_birth_key text := nullif(public.normalize_birth_key(p_birth_key), '');
  v_recovery_question text := nullif(trim(coalesce(p_recovery_question, '')), '');
  v_recovery_answer_hash text := nullif(trim(coalesce(p_recovery_answer_hash, '')), '');
  v_can_set_identity boolean := false;
begin
  if v_uid is null then
    return query
    select
      false,
      '로그인이 필요해.',
      null::text,
      null::text,
      null::text,
      false;
    return;
  end if;

  select *
    into v_profile
  from public.profiles
  where id = v_uid
  for update;

  if not found then
    return query
    select
      false,
      '프로필 정보를 찾지 못했어.',
      null::text,
      null::text,
      null::text,
      false;
    return;
  end if;

  v_can_set_identity :=
    coalesce(trim(v_profile.real_name), '') = ''
    and coalesce(trim(v_profile.birth_key), '') = '';

  -- ---------------------------------------
  -- 이름 / 생년월일 최초 1회 저장
  -- ---------------------------------------
  if v_can_set_identity then
    if v_real_name is null or char_length(v_real_name) < 2 then
      return query
      select
        false,
        '이름은 2글자 이상 입력해줘.',
        v_profile.real_name,
        v_profile.birth_key,
        v_profile.recovery_question,
        true;
      return;
    end if;

    if v_birth_key is null or v_birth_key !~ '^\d{7}$' then
      return query
      select
        false,
        '생년월일은 960829-1 형식으로 입력해줘.',
        v_profile.real_name,
        v_profile.birth_key,
        v_profile.recovery_question,
        true;
      return;
    end if;

    update public.profiles
    set
      real_name = v_real_name,
      birth_key = v_birth_key,
      updated_at = now()
    where id = v_uid;

    v_profile.real_name := v_real_name;
    v_profile.birth_key := v_birth_key;
    v_can_set_identity := false;
  else
    -- 이미 저장된 경우 바꾸려 하면 차단
    if v_real_name is not null and v_real_name <> coalesce(v_profile.real_name, '') then
      return query
      select
        false,
        '이름은 한 번 저장하면 수정할 수 없어.',
        v_profile.real_name,
        v_profile.birth_key,
        v_profile.recovery_question,
        false;
      return;
    end if;

    if v_birth_key is not null and v_birth_key <> coalesce(v_profile.birth_key, '') then
      return query
      select
        false,
        '생년월일은 한 번 저장하면 수정할 수 없어.',
        v_profile.real_name,
        v_profile.birth_key,
        v_profile.recovery_question,
        false;
      return;
    end if;
  end if;

  -- ---------------------------------------
  -- 아이디 힌트는 계속 수정 가능
  -- ---------------------------------------
  if v_recovery_question is not null or v_recovery_answer_hash is not null then
    if v_recovery_question is null then
      return query
      select
        false,
        '아이디 힌트 질문을 선택해줘.',
        v_profile.real_name,
        v_profile.birth_key,
        v_profile.recovery_question,
        v_can_set_identity;
      return;
    end if;

    if v_recovery_answer_hash is null or v_recovery_answer_hash = '' then
      return query
      select
        false,
        '아이디 힌트 답변을 입력해줘.',
        v_profile.real_name,
        v_profile.birth_key,
        v_profile.recovery_question,
        v_can_set_identity;
      return;
    end if;

    update public.profiles
    set
      recovery_question = v_recovery_question,
      recovery_answer_hash = v_recovery_answer_hash,
      updated_at = now()
    where id = v_uid;

    v_profile.recovery_question := v_recovery_question;
  end if;

  return query
  select
    true,
    '복구정보 저장이 완료됐어.',
    (select p.real_name from public.profiles p where p.id = v_uid),
    (select p.birth_key from public.profiles p where p.id = v_uid),
    (select p.recovery_question from public.profiles p where p.id = v_uid),
    (
      select
        coalesce(trim(p.real_name), '') = ''
        and coalesce(trim(p.birth_key), '') = ''
      from public.profiles p
      where p.id = v_uid
    );
end;
$$;

grant execute on function public.update_my_recovery_profile(text, text, text, text)
to authenticated;

-- -----------------------------------------
-- 2. 확인용
-- -----------------------------------------
select
  id,
  email,
  nickname,
  real_name,
  birth_key,
  recovery_question,
  case
    when recovery_answer_hash is null or recovery_answer_hash = '' then '없음'
    else '있음'
  end as recovery_answer_hash_status
from public.profiles
order by created_at desc;

-- =========================================================
-- posts / post_comments
-- "진짜 수정"일 때만 updated_at 변경
-- - posts: title, excerpt, body, category, tags, pinned, media_items 변경 시만
-- - post_comments: body 관련 내용 변경 시만
-- 조회수 증가, 작성자명 동기화 같은 update는 updated_at 유지
-- =========================================================

-- -----------------------------------------
-- 1. posts 전용 updated_at 함수
-- -----------------------------------------
create or replace function public.handle_posts_updated_at_only_on_real_edit()
returns trigger
language plpgsql
as $$
begin
  if
    new.title        is distinct from old.title
    or new.excerpt   is distinct from old.excerpt
    or new.body      is distinct from old.body
    or new.category  is distinct from old.category
    or new.tags      is distinct from old.tags
    or new.pinned    is distinct from old.pinned
    or new.media_items is distinct from old.media_items
  then
    new.updated_at := now();
  else
    new.updated_at := old.updated_at;
  end if;

  return new;
end;
$$;

drop trigger if exists trg_posts_updated_at on public.posts;
create trigger trg_posts_updated_at
before update on public.posts
for each row
execute function public.handle_posts_updated_at_only_on_real_edit();

-- -----------------------------------------
-- 2. post_comments 전용 updated_at 함수
-- -----------------------------------------
create or replace function public.handle_post_comments_updated_at_only_on_real_edit()
returns trigger
language plpgsql
as $$
begin
  if
    new.body is distinct from old.body
    or new.parent_comment_id is distinct from old.parent_comment_id
    or new.reply_to_comment_id is distinct from old.reply_to_comment_id
    or new.reply_to_nickname is distinct from old.reply_to_nickname
  then
    new.updated_at := now();
  else
    new.updated_at := old.updated_at;
  end if;

  return new;
end;
$$;

drop trigger if exists trg_post_comments_updated_at on public.post_comments;
create trigger trg_post_comments_updated_at
before update on public.post_comments
for each row
execute function public.handle_post_comments_updated_at_only_on_real_edit();

-- -----------------------------------------
-- 3. updated_at가 없던 경우만 보정
-- 이미 잘못 덮인 "과거 수정시간"은 원래값 복구 불가
-- 별도 이력/백업이 없으면 정확 복원은 못함
-- -----------------------------------------
update public.posts
set updated_at = coalesce(updated_at, created_at, now())
where updated_at is null;

update public.post_comments
set updated_at = coalesce(updated_at, created_at, now())
where updated_at is null;

-- =========================================================
-- 비밀글 기능 최종본
-- - posts에 비밀글 컬럼 추가
-- - 공개 목록용 view
-- - 상세 조회용 RPC
-- - 수정용 RPC
-- - 비밀글용 updated_at도 "진짜 수정"일 때만 반영
-- =========================================================

create extension if not exists pgcrypto;

-- ---------------------------------------------------------
-- 1. posts 컬럼 추가
-- ---------------------------------------------------------
alter table public.posts
add column if not exists is_private boolean not null default false,
add column if not exists secret_password_hash text;

comment on column public.posts.is_private is '비밀글 여부';
comment on column public.posts.secret_password_hash is '비밀글 비밀번호 sha256 hex';

-- 비밀글이 아닌 글은 비밀번호 해시 없어야 하고,
-- 비밀글은 비밀번호 해시가 있어야 함
do $$
begin
  if not exists (
    select 1
    from pg_constraint
    where conname = 'posts_private_password_check'
  ) then
    alter table public.posts
    add constraint posts_private_password_check
    check (
      (is_private = false and secret_password_hash is null)
      or
      (is_private = true and secret_password_hash is not null and btrim(secret_password_hash) <> '')
    );
  end if;
end $$;

create index if not exists posts_is_private_idx
  on public.posts(is_private);

-- ---------------------------------------------------------
-- 2. 비밀번호 정규화 함수
-- ---------------------------------------------------------
create or replace function public.normalize_secret_password(p_value text)
returns text
language sql
immutable
as $$
  select trim(coalesce(p_value, ''));
$$;

create or replace function public.sha256_hex(p_value text)
returns text
language sql
immutable
as $$
  select encode(digest(coalesce(p_value, ''), 'sha256'), 'hex');
$$;

-- ---------------------------------------------------------
-- 3. 공개 목록용 view
-- body는 절대 노출하지 않음
-- ---------------------------------------------------------
create or replace view public.posts_public_list as
select
  p.id,
  p.title,
  p.excerpt,
  p.category,
  p.tags,
  p.pinned,
  p.views,
  p.media_items,
  p.author_id,
  p.author_nickname,
  p.created_at,
  p.updated_at,
  p.is_private
from public.posts p;

grant select on public.posts_public_list to anon, authenticated;

-- ---------------------------------------------------------
-- 4. 공개 목록 RLS 유지
--    기존 posts_select_all이 body까지 다 노출하므로 조정
-- ---------------------------------------------------------
alter table public.posts enable row level security;

drop policy if exists "posts_select_all" on public.posts;

-- 목록성 직접 조회는 일단 막고, 상세/수정은 RPC로 처리
create policy "posts_select_owner_or_admin_only"
on public.posts
for select
to authenticated
using (
  auth.uid() = author_id
  or public.is_admin_user(auth.uid())
);

-- anon은 posts 직접 select 불가
-- 목록은 posts_public_list로만 보게 감

-- 작성 정책
drop policy if exists "posts_insert_own" on public.posts;
create policy "posts_insert_own"
on public.posts
for insert
to authenticated
with check (auth.uid() = author_id);

-- 수정 정책
drop policy if exists "posts_update_own" on public.posts;
drop policy if exists "posts_update_owner_or_admin" on public.posts;
create policy "posts_update_owner_or_admin"
on public.posts
for update
to authenticated
using (
  auth.uid() = author_id
  or public.is_admin_user(auth.uid())
)
with check (
  auth.uid() = author_id
  or public.is_admin_user(auth.uid())
);

-- 삭제 정책
drop policy if exists "posts_delete_own" on public.posts;
drop policy if exists "posts_delete_owner_or_admin" on public.posts;
create policy "posts_delete_owner_or_admin"
on public.posts
for delete
to authenticated
using (
  auth.uid() = author_id
  or public.is_admin_user(auth.uid())
);

-- ---------------------------------------------------------
-- 5. 상세 조회 RPC
--    - 공개글: 바로 본문 반환
--    - 비밀글: 작성자/관리자 or 비밀번호 일치 시 본문 반환
--    - 잠긴 상태면 본문/body, media_items 반환 안 함
-- ---------------------------------------------------------
create or replace function public.get_post_detail(
  p_post_id bigint,
  p_secret_password text default null
)
returns table (
  id bigint,
  title text,
  excerpt text,
  body text,
  category text,
  tags text[],
  pinned boolean,
  views integer,
  media_items jsonb,
  author_id uuid,
  author_nickname text,
  created_at timestamptz,
  updated_at timestamptz,
  is_private boolean,
  is_unlocked boolean
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_is_admin boolean := public.is_admin_user(v_uid);
  v_post public.posts%rowtype;
  v_is_owner boolean := false;
  v_pw_ok boolean := false;
begin
  select *
    into v_post
  from public.posts
  where posts.id = p_post_id;

  if not found then
    return;
  end if;

  v_is_owner := (v_uid is not null and v_post.author_id = v_uid);

  if v_post.is_private = false then
    return query
    select
      v_post.id,
      v_post.title,
      v_post.excerpt,
      v_post.body,
      v_post.category,
      v_post.tags,
      v_post.pinned,
      v_post.views,
      v_post.media_items,
      v_post.author_id,
      v_post.author_nickname,
      v_post.created_at,
      v_post.updated_at,
      v_post.is_private,
      true;
    return;
  end if;

  if v_is_owner or v_is_admin then
    return query
    select
      v_post.id,
      v_post.title,
      v_post.excerpt,
      v_post.body,
      v_post.category,
      v_post.tags,
      v_post.pinned,
      v_post.views,
      v_post.media_items,
      v_post.author_id,
      v_post.author_nickname,
      v_post.created_at,
      v_post.updated_at,
      v_post.is_private,
      true;
    return;
  end if;

  if nullif(public.normalize_secret_password(p_secret_password), '') is not null then
    v_pw_ok := (
      public.sha256_hex(public.normalize_secret_password(p_secret_password))
      = coalesce(v_post.secret_password_hash, '')
    );
  end if;

  if v_pw_ok then
    return query
    select
      v_post.id,
      v_post.title,
      v_post.excerpt,
      v_post.body,
      v_post.category,
      v_post.tags,
      v_post.pinned,
      v_post.views,
      v_post.media_items,
      v_post.author_id,
      v_post.author_nickname,
      v_post.created_at,
      v_post.updated_at,
      v_post.is_private,
      true;
    return;
  end if;

  -- 잠긴 상태
  return query
  select
    v_post.id,
    v_post.title,
    v_post.excerpt,
    null::text as body,
    v_post.category,
    v_post.tags,
    v_post.pinned,
    v_post.views,
    '[]'::jsonb as media_items,
    v_post.author_id,
    v_post.author_nickname,
    v_post.created_at,
    v_post.updated_at,
    v_post.is_private,
    false;
end;
$$;

grant execute on function public.get_post_detail(bigint, text) to anon, authenticated;

-- ---------------------------------------------------------
-- 6. 수정용 RPC
--    작성자 본인 또는 관리자만 전체 글 조회 가능
-- ---------------------------------------------------------
create or replace function public.get_post_for_edit(
  p_post_id bigint
)
returns table (
  id bigint,
  title text,
  excerpt text,
  body text,
  category text,
  tags text[],
  pinned boolean,
  media_items jsonb,
  author_id uuid,
  author_nickname text,
  is_private boolean
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    return;
  end if;

  return query
  select
    p.id,
    p.title,
    p.excerpt,
    p.body,
    p.category,
    p.tags,
    p.pinned,
    p.media_items,
    p.author_id,
    p.author_nickname,
    p.is_private
  from public.posts p
  where p.id = p_post_id
    and (
      p.author_id = v_uid
      or public.is_admin_user(v_uid)
    );
end;
$$;

grant execute on function public.get_post_for_edit(bigint) to authenticated;

-- ---------------------------------------------------------
-- 7. updated_at 트리거 교체
--    실제 글 내용 수정일 때만 변경
-- ---------------------------------------------------------
create or replace function public.handle_posts_updated_at_real_change()
returns trigger
language plpgsql
as $$
begin
  if
    coalesce(new.title, '') is distinct from coalesce(old.title, '')
    or coalesce(new.excerpt, '') is distinct from coalesce(old.excerpt, '')
    or coalesce(new.body, '') is distinct from coalesce(old.body, '')
    or coalesce(new.category, '') is distinct from coalesce(old.category, '')
    or coalesce(new.tags, '{}'::text[]) is distinct from coalesce(old.tags, '{}'::text[])
    or coalesce(new.pinned, false) is distinct from coalesce(old.pinned, false)
    or coalesce(new.media_items, '[]'::jsonb) is distinct from coalesce(old.media_items, '[]'::jsonb)
    or coalesce(new.is_private, false) is distinct from coalesce(old.is_private, false)
    or coalesce(new.secret_password_hash, '') is distinct from coalesce(old.secret_password_hash, '')
  then
    new.updated_at = now();
  else
    new.updated_at = old.updated_at;
  end if;

  return new;
end;
$$;

drop trigger if exists trg_posts_updated_at on public.posts;
create trigger trg_posts_updated_at
before update on public.posts
for each row
execute function public.handle_posts_updated_at_real_change();

-- ---------------------------------------------------------
-- 8. 기존 공개글 데이터 정리
-- ---------------------------------------------------------
update public.posts
set
  is_private = coalesce(is_private, false),
  secret_password_hash = case
    when coalesce(is_private, false) = false then null
    else secret_password_hash
  end;

-- ---------------------------------------------------------
-- 9. 확인용
-- ---------------------------------------------------------
select
  id,
  title,
  is_private,
  case
    when secret_password_hash is null or secret_password_hash = '' then '없음'
    else '있음'
  end as secret_password_hash_status
from public.posts
order by created_at desc
limit 30;

