-- ---------------------------------------------------------
-- 7. updated_at 트리거
-- ---------------------------------------------------------
create or replace function public.handle_posts_updated_at_real_change()
returns trigger
language plpgsql
as $$
begin
  if
    coalesce(new.title, '') is distinct from coalesce(old.title, '')
    or coalesce(new.excerpt, '') is distinct from coalesce(old.excerpt, '')
    or coalesce(new.body, '') is distinct from coalesce(old.body, '')
    or coalesce(new.category, '') is distinct from coalesce(old.category, '')
    or coalesce(new.tags, '{}'::text[]) is distinct from coalesce(old.tags, '{}'::text[])
    or coalesce(new.pinned, false) is distinct from coalesce(old.pinned, false)
    or coalesce(new.media_items, '[]'::jsonb) is distinct from coalesce(old.media_items, '[]'::jsonb)
    or coalesce(new.is_private, false) is distinct from coalesce(old.is_private, false)
    or coalesce(new.secret_password_hash, '') is distinct from coalesce(old.secret_password_hash, '')
  then
    new.updated_at = now();
  else
    new.updated_at = old.updated_at;
  end if;

  return new;
end;
$$;

drop trigger if exists trg_posts_updated_at on public.posts;
create trigger trg_posts_updated_at
before update on public.posts
for each row
execute function public.handle_posts_updated_at_real_change();

-- ---------------------------------------------------------
-- 8. 기존 데이터 정리
-- ---------------------------------------------------------
update public.posts
set
  is_private = coalesce(is_private, false),
  secret_password_hash = case
    when coalesce(is_private, false) = false then null
    else secret_password_hash
  end;

-- ---------------------------------------------------------
-- 9. 확인용
-- ---------------------------------------------------------
select
  id,
  title,
  is_private,
  case
    when secret_password_hash is null or secret_password_hash = '' then '없음'
    else '있음'
  end as secret_password_hash_status
from public.posts
order by created_at desc
limit 30;

create extension if not exists pgcrypto with schema extensions;

-- =========================================================
-- posts 테이블: 비밀글 관련 컬럼 보강
-- =========================================================
alter table public.posts
  add column if not exists media_items jsonb not null default '[]'::jsonb;

alter table public.posts
  add column if not exists is_private boolean not null default false;

alter table public.posts
  add column if not exists secret_password_hash text;

-- 기존 데이터 방어
update public.posts
set media_items = '[]'::jsonb
where media_items is null;

update public.posts
set is_private = false
where is_private is null;

-- =========================================================
-- RLS: posts 직접 조회는 막고,
-- 상세조회는 RPC / 목록조회는 안전한 VIEW로만 처리
-- =========================================================
alter table public.posts enable row level security;

drop policy if exists "posts_select_all" on public.posts;
drop policy if exists "posts_select_own" on public.posts;
drop policy if exists "posts_insert_own" on public.posts;
drop policy if exists "posts_update_own" on public.posts;
drop policy if exists "posts_delete_own" on public.posts;

-- 자기 글만 직접 select 가능
create policy "posts_select_own"
on public.posts
for select
to authenticated
using ((select auth.uid()) = author_id);

-- 로그인 사용자만 자기 글 작성 가능
create policy "posts_insert_own"
on public.posts
for insert
to authenticated
with check ((select auth.uid()) = author_id);

-- 로그인 사용자는 자기 글만 수정 가능
create policy "posts_update_own"
on public.posts
for update
to authenticated
using ((select auth.uid()) = author_id)
with check ((select auth.uid()) = author_id);

-- 로그인 사용자는 자기 글만 삭제 가능
create policy "posts_delete_own"
on public.posts
for delete
to authenticated
using ((select auth.uid()) = author_id);

-- =========================================================
-- 공개 목록용 VIEW
-- 비밀글이어도 목록엔 제목/요약 등만 보이고 본문/비번해시는 안 내려감
-- =========================================================
drop view if exists public.posts_public_list;

create view public.posts_public_list
as
select
  p.id,
  p.title,
  p.excerpt,
  p.category,
  p.tags,
  p.pinned,
  p.views,
  p.media_items,
  p.author_id,
  p.author_nickname,
  p.created_at,
  p.updated_at,
  p.is_private
from public.posts p
order by p.pinned desc, p.created_at desc, p.id desc;

grant select on public.posts_public_list to anon, authenticated;

-- =========================================================
-- 상세 조회 RPC
-- 비밀글이면:
-- 1) 작성자 본인 또는
-- 2) 비밀번호 일치
-- 일 때만 본문/첨부를 열어줌
-- =========================================================
drop function if exists public.get_post_detail(bigint, text);

create or replace function public.get_post_detail(
  p_post_id bigint,
  p_secret_password text default null
)
returns table (
  id bigint,
  title text,
  excerpt text,
  body text,
  category text,
  tags text[],
  pinned boolean,
  views integer,
  media_items jsonb,
  author_id uuid,
  author_nickname text,
  created_at timestamptz,
  updated_at timestamptz,
  is_private boolean,
  is_unlocked boolean
)
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  v_post public.posts%rowtype;
  v_is_owner boolean := false;
  v_password_ok boolean := false;
  v_is_unlocked boolean := false;
begin
  select *
    into v_post
  from public.posts
  where posts.id = p_post_id;

  if not found then
    return;
  end if;

  v_is_owner := auth.uid() is not null and auth.uid() = v_post.author_id;

  if coalesce(v_post.is_private, false) = false then
    v_is_unlocked := true;
  else
    if v_is_owner then
      v_is_unlocked := true;
    else
      v_password_ok :=
        p_secret_password is not null
        and v_post.secret_password_hash is not null
        and encode(
              extensions.digest(p_secret_password, 'sha256'),
              'hex'
            ) = v_post.secret_password_hash;

      v_is_unlocked := v_password_ok;
    end if;
  end if;

  return query
  select
    v_post.id,
    v_post.title,
    v_post.excerpt,
    case
      when v_is_unlocked then v_post.body
      else ''
    end as body,
    v_post.category,
    v_post.tags,
    v_post.pinned,
    v_post.views,
    case
      when v_is_unlocked then v_post.media_items
      else '[]'::jsonb
    end as media_items,
    v_post.author_id,
    v_post.author_nickname,
    v_post.created_at,
    v_post.updated_at,
    coalesce(v_post.is_private, false) as is_private,
    v_is_unlocked as is_unlocked;
end;
$$;

grant execute on function public.get_post_detail(bigint, text) to anon, authenticated;

-- =========================================================
-- 수정용 RPC
-- 작성자 본인만 수정 데이터 전체 조회 가능
-- =========================================================
drop function if exists public.get_post_for_edit(bigint);

create or replace function public.get_post_for_edit(
  p_post_id bigint
)
returns table (
  id bigint,
  title text,
  excerpt text,
  body text,
  category text,
  tags text[],
  pinned boolean,
  media_items jsonb,
  author_id uuid,
  author_nickname text,
  created_at timestamptz,
  updated_at timestamptz,
  is_private boolean
)
language sql
security definer
set search_path = public
as $$
  select
    p.id,
    p.title,
    p.excerpt,
    p.body,
    p.category,
    p.tags,
    p.pinned,
    p.media_items,
    p.author_id,
    p.author_nickname,
    p.created_at,
    p.updated_at,
    coalesce(p.is_private, false) as is_private
  from public.posts p
  where p.id = p_post_id
    and auth.uid() is not null
    and auth.uid() = p.author_id;
$$;

grant execute on function public.get_post_for_edit(bigint) to authenticated;

