-- =========================================================
-- 피클 시스템
-- =========================================================

-- 1) profiles 에 보유 피클 컬럼 추가
alter table public.profiles
add column if not exists pickles integer not null default 0;

comment on column public.profiles.pickles is '사용자 보유 피클';

-- 2) 한국 날짜 기준 함수
create or replace function public.seoul_today()
returns date
language sql
stable
as $$
  select (timezone('Asia/Seoul', now()))::date;
$$;

-- 3) 피클 내역 테이블
create table if not exists public.pickle_ledger (
  id bigint generated by default as identity primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  amount integer not null,
  reason_code text not null check (
    reason_code in ('attendance', 'post_create', 'comment_post')
  ),
  reason_label text not null,
  description text not null default '',
  source_post_id bigint null references public.posts(id) on delete set null,
  source_comment_id bigint null references public.post_comments(id) on delete set null,
  awarded_on date not null default public.seoul_today(),
  created_at timestamptz not null default now()
);

create index if not exists pickle_ledger_user_id_idx
  on public.pickle_ledger(user_id);

create index if not exists pickle_ledger_user_id_created_at_idx
  on public.pickle_ledger(user_id, created_at desc);

create index if not exists pickle_ledger_reason_code_idx
  on public.pickle_ledger(reason_code);

create index if not exists pickle_ledger_source_post_id_idx
  on public.pickle_ledger(source_post_id);

alter table public.pickle_ledger enable row level security;

drop policy if exists "피클 내역은 본인만 조회 가능" on public.pickle_ledger;
create policy "피클 내역은 본인만 조회 가능"
on public.pickle_ledger
for select
to authenticated
using (auth.uid() = user_id);

grant select on public.pickle_ledger to authenticated;

-- 4) 피클 지급 공통 함수
create or replace function public.grant_pickle_reward(
  p_user_id uuid,
  p_amount integer,
  p_reason_code text,
  p_reason_label text,
  p_description text default '',
  p_source_post_id bigint default null,
  p_source_comment_id bigint default null,
  p_awarded_on date default null
)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_exists boolean := false;
  v_awarded_on date := coalesce(p_awarded_on, public.seoul_today());
begin
  if p_user_id is null then
    return false;
  end if;

  if coalesce(p_amount, 0) = 0 then
    return false;
  end if;

  if coalesce(trim(p_reason_code), '') = '' then
    return false;
  end if;

  if p_reason_code = 'attendance' then
    select exists (
      select 1
      from public.pickle_ledger
      where user_id = p_user_id
        and reason_code = 'attendance'
        and awarded_on = v_awarded_on
    )
    into v_exists;

  elsif p_reason_code = 'post_create' then
    select exists (
      select 1
      from public.pickle_ledger
      where user_id = p_user_id
        and reason_code = 'post_create'
        and source_post_id = p_source_post_id
    )
    into v_exists;

  elsif p_reason_code = 'comment_post' then
    select exists (
      select 1
      from public.pickle_ledger
      where user_id = p_user_id
        and reason_code = 'comment_post'
        and source_post_id = p_source_post_id
    )
    into v_exists;

  else
    return false;
  end if;

  if v_exists then
    return false;
  end if;

  insert into public.pickle_ledger (
    user_id,
    amount,
    reason_code,
    reason_label,
    description,
    source_post_id,
    source_comment_id,
    awarded_on
  )
  values (
    p_user_id,
    p_amount,
    p_reason_code,
    coalesce(nullif(trim(p_reason_label), ''), '피클 획득'),
    coalesce(p_description, ''),
    p_source_post_id,
    p_source_comment_id,
    v_awarded_on
  );

  update public.profiles
  set pickles = coalesce(pickles, 0) + p_amount,
      updated_at = now()
  where id = p_user_id;

  return true;
end;
$$;

-- 5) 로그인 출석 체크 함수
create or replace function public.claim_daily_attendance()
returns table (
  ok boolean,
  amount integer,
  message text,
  balance integer
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid := auth.uid();
  v_granted boolean := false;
begin
  if v_user_id is null then
    raise exception '로그인이 필요해.';
  end if;

  v_granted := public.grant_pickle_reward(
    v_user_id,
    30,
    'attendance',
    '출석 체크',
    '로그인 출석 체크로 피클을 받았어.',
    null,
    null,
    public.seoul_today()
  );

  return query
  select
    v_granted,
    case when v_granted then 30 else 0 end,
    case
      when v_granted then '오늘 출석 체크로 피클 30개를 받았어.'
      else '오늘 출석 피클은 이미 받았어.'
    end,
    coalesce(
      (select p.pickles from public.profiles p where p.id = v_user_id),
      0
    );
end;
$$;

grant execute on function public.claim_daily_attendance() to authenticated;

-- 6) 게시글 작성 피클 지급 트리거
create or replace function public.handle_pickle_on_post_insert()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  perform public.grant_pickle_reward(
    new.author_id,
    30,
    'post_create',
    '게시글 작성',
    '게시글 작성으로 피클을 받았어.',
    new.id,
    null,
    public.seoul_today()
  );

  return new;
end;
$$;

drop trigger if exists trg_pickle_on_post_insert on public.posts;
create trigger trg_pickle_on_post_insert
after insert on public.posts
for each row
execute function public.handle_pickle_on_post_insert();

-- 7) 댓글/답글 작성 피클 지급 트리거
create or replace function public.handle_pickle_on_comment_insert()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_reason_label text;
  v_description text;
begin
  if new.parent_comment_id is null then
    v_reason_label := '댓글 작성';
    v_description := '댓글 작성으로 피클을 받았어.';
  else
    v_reason_label := '답글 작성';
    v_description := '답글 작성으로 피클을 받았어.';
  end if;

  perform public.grant_pickle_reward(
    new.author_id,
    10,
    'comment_post',
    v_reason_label,
    v_description,
    new.post_id,
    new.id,
    public.seoul_today()
  );

  return new;
end;
$$;

drop trigger if exists trg_pickle_on_comment_insert on public.post_comments;
create trigger trg_pickle_on_comment_insert
after insert on public.post_comments
for each row
execute function public.handle_pickle_on_comment_insert();

drop function if exists public.get_post_detail(bigint, text);

create or replace function public.get_post_detail(
  p_post_id bigint,
  p_secret_password text default null
)
returns table (
  id bigint,
  title text,
  excerpt text,
  body text,
  category text,
  tags text[],
  pinned boolean,
  views integer,
  likes_count bigint,
  dislikes_count bigint,
  total_reactions_count bigint,
  media_items jsonb,
  author_id uuid,
  author_nickname text,
  created_at timestamptz,
  updated_at timestamptz,
  is_private boolean,
  is_unlocked boolean
)
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  v_post public.posts%rowtype;
  v_password_ok boolean := false;
  v_is_unlocked boolean := false;
begin
  select *
    into v_post
  from public.posts
  where posts.id = p_post_id;

  if not found then
    return;
  end if;

  if coalesce(v_post.is_private, false) = false then
    v_is_unlocked := true;
  else
    v_password_ok :=
      p_secret_password is not null
      and v_post.secret_password_hash is not null
      and encode(
            extensions.digest(p_secret_password, 'sha256'),
            'hex'
          ) = v_post.secret_password_hash;

    v_is_unlocked := v_password_ok;
  end if;

  return query
  select
    v_post.id,
    v_post.title,
    v_post.excerpt,
    case
      when v_is_unlocked then v_post.body
      else ''
    end as body,
    v_post.category,
    v_post.tags,
    v_post.pinned,
    v_post.views,
    (
      select count(*)::bigint
      from public.post_reactions pr
      where pr.post_id = v_post.id
        and pr.reaction_type = 'like'
    ) as likes_count,
    (
      select count(*)::bigint
      from public.post_reactions pr
      where pr.post_id = v_post.id
        and pr.reaction_type = 'dislike'
    ) as dislikes_count,
    (
      select count(*)::bigint
      from public.post_reactions pr
      where pr.post_id = v_post.id
    ) as total_reactions_count,
    case
      when v_is_unlocked then v_post.media_items
      else '[]'::jsonb
    end as media_items,
    v_post.author_id,
    v_post.author_nickname,
    v_post.created_at,
    v_post.updated_at,
    coalesce(v_post.is_private, false) as is_private,
    v_is_unlocked as is_unlocked;
end;
$$;

grant execute on function public.get_post_detail(bigint, text) to anon, authenticated;

create or replace function public.grant_pickle_reward(
  p_user_id uuid,
  p_amount integer,
  p_reason_code text,
  p_reason_label text,
  p_description text default '',
  p_source_post_id bigint default null,
  p_source_comment_id bigint default null,
  p_awarded_on date default null
)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_exists boolean := false;
  v_awarded_on date := coalesce(p_awarded_on, public.seoul_today());
  v_daily_count integer := 0;
begin
  if p_user_id is null then
    return false;
  end if;

  if coalesce(p_amount, 0) = 0 then
    return false;
  end if;

  if coalesce(trim(p_reason_code), '') = '' then
    return false;
  end if;

  if p_reason_code = 'attendance' then
    select exists (
      select 1
      from public.pickle_ledger
      where user_id = p_user_id
        and reason_code = 'attendance'
        and awarded_on = v_awarded_on
    )
    into v_exists;

  elsif p_reason_code = 'post_create' then
    -- 같은 게시글에 대한 중복 지급 방지
    select exists (
      select 1
      from public.pickle_ledger
      where user_id = p_user_id
        and reason_code = 'post_create'
        and source_post_id = p_source_post_id
    )
    into v_exists;

    if v_exists then
      return false;
    end if;

    -- 하루 최대 5개 게시글까지만 지급
    select count(*)
      into v_daily_count
    from public.pickle_ledger
    where user_id = p_user_id
      and reason_code = 'post_create'
      and awarded_on = v_awarded_on;

    if v_daily_count >= 5 then
      return false;
    end if;

  elsif p_reason_code = 'comment_post' then
    -- 같은 댓글/답글에 대한 중복 지급 방지
    select exists (
      select 1
      from public.pickle_ledger
      where user_id = p_user_id
        and reason_code = 'comment_post'
        and source_comment_id = p_source_comment_id
    )
    into v_exists;

    if v_exists then
      return false;
    end if;

    -- 하루 최대 10개 댓글/답글까지만 지급
    select count(*)
      into v_daily_count
    from public.pickle_ledger
    where user_id = p_user_id
      and reason_code = 'comment_post'
      and awarded_on = v_awarded_on;

    if v_daily_count >= 10 then
      return false;
    end if;

  else
    return false;
  end if;

  if v_exists then
    return false;
  end if;

  insert into public.pickle_ledger (
    user_id,
    amount,
    reason_code,
    reason_label,
    description,
    source_post_id,
    source_comment_id,
    awarded_on
  )
  values (
    p_user_id,
    p_amount,
    p_reason_code,
    coalesce(nullif(trim(p_reason_label), ''), '피클 획득'),
    coalesce(p_description, ''),
    p_source_post_id,
    p_source_comment_id,
    v_awarded_on
  );

  update public.profiles
  set pickles = coalesce(pickles, 0) + p_amount,
      updated_at = now()
  where id = p_user_id;

  return true;
end;
$$;

-- =========================================================
-- 조회수 중복 상승 방지용 로그 테이블
-- 같은 게시물 + 같은 viewer_key 조합의 마지막 조회 시각을 저장
-- =========================================================

create table if not exists public.post_view_logs (
  post_id bigint not null references public.posts(id) on delete cascade,
  viewer_key text not null,
  last_viewed_at timestamptz not null default now(),
  view_count integer not null default 1,
  created_at timestamptz not null default now(),
  primary key (post_id, viewer_key)
);

create index if not exists idx_post_view_logs_last_viewed_at
  on public.post_view_logs(last_viewed_at);

alter table public.post_view_logs enable row level security;

revoke all on public.post_view_logs from anon, authenticated;

-- =========================================================
-- 기존 함수 교체
-- 이전: 게시물 들어올 때마다 무조건 +1
-- 변경: 같은 viewer_key는 cooldown 시간 내 재조회 시 증가 안 함
-- =========================================================

drop function if exists public.increment_post_views(bigint);

create or replace function public.increment_post_views(
  p_post_id bigint,
  p_viewer_key text,
  p_cooldown_seconds integer default 1800
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_now timestamptz := now();
  v_last_viewed_at timestamptz;
  v_views bigint := 0;
  v_counted boolean := false;
  v_cooldown integer := greatest(coalesce(p_cooldown_seconds, 1800), 0);
begin
  if p_post_id is null then
    return jsonb_build_object(
      'views', 0,
      'counted', false
    );
  end if;

  if coalesce(btrim(p_viewer_key), '') = '' then
    select coalesce(views, 0)
      into v_views
    from public.posts
    where id = p_post_id;

    return jsonb_build_object(
      'views', coalesce(v_views, 0),
      'counted', false
    );
  end if;

  -- 같은 게시물 + 같은 viewer_key 동시 요청 경쟁 방지
  perform pg_advisory_xact_lock(hashtext('post-view:' || p_post_id::text || ':' || p_viewer_key));

  select last_viewed_at
    into v_last_viewed_at
  from public.post_view_logs
  where post_id = p_post_id
    and viewer_key = p_viewer_key;

  if v_last_viewed_at is null then
    insert into public.post_view_logs (
      post_id,
      viewer_key,
      last_viewed_at,
      view_count,
      created_at
    )
    values (
      p_post_id,
      p_viewer_key,
      v_now,
      1,
      v_now
    );

    update public.posts
    set views = coalesce(views, 0) + 1
    where id = p_post_id
    returning views into v_views;

    v_counted := true;
  elsif v_last_viewed_at <= (v_now - make_interval(secs => v_cooldown)) then
    update public.post_view_logs
    set last_viewed_at = v_now,
        view_count = coalesce(view_count, 0) + 1
    where post_id = p_post_id
      and viewer_key = p_viewer_key;

    update public.posts
    set views = coalesce(views, 0) + 1
    where id = p_post_id
    returning views into v_views;

    v_counted := true;
  else
    select coalesce(views, 0)
      into v_views
    from public.posts
    where id = p_post_id;
  end if;

  return jsonb_build_object(
    'views', coalesce(v_views, 0),
    'counted', v_counted
  );
end;
$$;

grant execute on function public.increment_post_views(bigint, text, integer) to anon, authenticated;

-- =========================================================
-- 상점 구매 / 이모티콘 인벤토리
-- =========================================================

create table if not exists public.user_store_items (
  id bigint generated by default as identity primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  item_id text not null,
  item_name text not null,
  item_category text not null,
  purchase_price integer not null default 0,
  purchased_at timestamptz not null default now(),
  unique (user_id, item_id)
);

create index if not exists user_store_items_user_id_idx
  on public.user_store_items(user_id);

alter table public.user_store_items enable row level security;

drop policy if exists "내 상점 구매내역 조회" on public.user_store_items;
create policy "내 상점 구매내역 조회"
on public.user_store_items
for select
to authenticated
using (auth.uid() = user_id);

grant select on public.user_store_items to authenticated;

create table if not exists public.user_emoticons (
  id bigint generated by default as identity primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  item_id text not null,
  emoticon_code text not null,
  emoticon_label text not null,
  image_path text not null,
  display_order integer not null default 0,
  is_equipped boolean not null default false,
  acquired_at timestamptz not null default now(),
  unique (user_id, emoticon_code)
);

create index if not exists user_emoticons_user_id_idx
  on public.user_emoticons(user_id);

create index if not exists user_emoticons_user_id_order_idx
  on public.user_emoticons(user_id, display_order);

alter table public.user_emoticons enable row level security;

drop policy if exists "내 이모티콘 조회" on public.user_emoticons;
create policy "내 이모티콘 조회"
on public.user_emoticons
for select
to authenticated
using (auth.uid() = user_id);

grant select on public.user_emoticons to authenticated;

drop policy if exists "내 이모티콘 장착상태 수정" on public.user_emoticons;
create policy "내 이모티콘 장착상태 수정"
on public.user_emoticons
for update
to authenticated
using (auth.uid() = user_id)
with check (auth.uid() = user_id);

grant update (is_equipped) on public.user_emoticons to authenticated;

create or replace function public.purchase_store_item(p_item_id text)
returns table (
  ok boolean,
  message text,
  balance integer
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid := auth.uid();
  v_price integer := 0;
  v_name text := '';
  v_category text := '';
  v_exists boolean := false;
begin
  if v_user_id is null then
    raise exception '로그인이 필요해.';
  end if;

  if coalesce(trim(p_item_id), '') = '' then
    raise exception '품목 id가 비어 있어.';
  end if;

  if p_item_id = 'emo-basic-01' then
    v_price := 0;
    v_name := '기본 말린오이 이모티콘팩';
    v_category := 'emoticon';
  else
    return query
    select
      false,
      '아직 구매 가능한 품목이 아니야.',
      coalesce((select p.pickles from public.profiles p where p.id = v_user_id), 0);
    return;
  end if;

  select exists (
    select 1
    from public.user_store_items
    where user_id = v_user_id
      and item_id = p_item_id
  )
  into v_exists;

  if v_exists then
    return query
    select
      false,
      '이미 보유 중인 품목이야.',
      coalesce((select p.pickles from public.profiles p where p.id = v_user_id), 0);
    return;
  end if;

  if v_price > 0 then
    update public.profiles
    set pickles = pickles - v_price,
        updated_at = now()
    where id = v_user_id
      and coalesce(pickles, 0) >= v_price;

    if not found then
      return query
      select
        false,
        '피클이 부족해.',
        coalesce((select p.pickles from public.profiles p where p.id = v_user_id), 0);
      return;
    end if;
  end if;

  insert into public.user_store_items (
    user_id,
    item_id,
    item_name,
    item_category,
    purchase_price
  )
  values (
    v_user_id,
    p_item_id,
    v_name,
    v_category,
    v_price
  );

  if p_item_id = 'emo-basic-01' then
    insert into public.user_emoticons (
      user_id,
      item_id,
      emoticon_code,
      emoticon_label,
      image_path,
      display_order
    )
    values
      (v_user_id, 'emo-basic-01', 'free-1', '기본 이모티콘 1', './images/emoticons/free-1.png', 1),
      (v_user_id, 'emo-basic-01', 'free-2', '기본 이모티콘 2', './images/emoticons/free-2.png', 2),
      (v_user_id, 'emo-basic-01', 'free-3', '기본 이모티콘 3', './images/emoticons/free-3.png', 3),
      (v_user_id, 'emo-basic-01', 'free-4', '기본 이모티콘 4', './images/emoticons/free-4.png', 4),
      (v_user_id, 'emo-basic-01', 'free-5', '기본 이모티콘 5', './images/emoticons/free-5.png', 5),
      (v_user_id, 'emo-basic-01', 'free-6', '기본 이모티콘 6', './images/emoticons/free-6.png', 6),
      (v_user_id, 'emo-basic-01', 'free-7', '기본 이모티콘 7', './images/emoticons/free-7.png', 7)
    on conflict (user_id, emoticon_code) do nothing;
  end if;

  return query
  select
    true,
    '기본 이모티콘팩이 지급됐어. 이제 게시물/댓글/답글에서 사용할 수 있어.',
    coalesce((select p.pickles from public.profiles p where p.id = v_user_id), 0);
end;
$$;

grant execute on function public.purchase_store_item(text) to authenticated;

