      when p_item_id = 'emo-carrot-01'
        then '특별제작 당근 이모티콘팩 구매가 완료됐어. 310피클이 차감됐고 바로 사용할 수 있어.'
      when p_item_id = 'character-carrot-01'
        then '테토당근 캐릭터 구매가 완료됐어. 530피클이 차감됐고 내프로필에서 착용할 수 있어.'
      else '구매가 완료됐어.'
    end,
    coalesce(v_balance, 0);
end;
$$;

grant execute on function public.purchase_store_item(text) to authenticated;

create or replace function public.claim_daily_attendance()
returns table (
  ok boolean,
  amount integer,
  message text,
  balance integer
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid := auth.uid();
  v_granted boolean := false;
begin
  if v_user_id is null then
    raise exception '로그인이 필요해.';
  end if;

  v_granted := public.grant_pickle_reward(
    v_user_id,
    50,
    'attendance',
    '출석 체크',
    '로그인 출석 체크로 피클을 받았어.',
    null,
    null,
    public.seoul_today()
  );

  return query
  select
    v_granted,
    case when v_granted then 50 else 0 end,
    case
      when v_granted then '오늘 출석 체크로 피클 50개를 받았어.'
      else '오늘 출석 피클은 이미 받았어.'
    end,
    coalesce(
      (select p.pickles from public.profiles p where p.id = v_user_id),
      0
    );
end;
$$;

grant execute on function public.claim_daily_attendance() to authenticated;

create or replace function public.grant_pickle_reward(
  p_user_id uuid,
  p_amount integer,
  p_reason_code text,
  p_reason_label text default null,
  p_description text default null,
  p_source_post_id bigint default null,
  p_source_comment_id bigint default null,
  p_awarded_on date default null
)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_exists boolean := false;
  v_awarded_on date := coalesce(p_awarded_on, public.seoul_today());
  v_daily_count integer := 0;
begin
  if p_user_id is null then
    return false;
  end if;

  if coalesce(p_amount, 0) = 0 then
    return false;
  end if;

  if coalesce(trim(p_reason_code), '') = '' then
    return false;
  end if;

  if p_reason_code = 'attendance' then
    select exists (
      select 1
      from public.pickle_ledger
      where user_id = p_user_id
        and reason_code = 'attendance'
        and awarded_on = v_awarded_on
    )
    into v_exists;

  elsif p_reason_code = 'post_create' then
    select exists (
      select 1
      from public.pickle_ledger
      where user_id = p_user_id
        and reason_code = 'post_create'
        and source_post_id = p_source_post_id
    )
    into v_exists;

    if v_exists then
      return false;
    end if;

    select count(*)
      into v_daily_count
    from public.pickle_ledger
    where user_id = p_user_id
      and reason_code = 'post_create'
      and awarded_on = v_awarded_on;

    if v_daily_count >= 5 then
      return false;
    end if;

  elsif p_reason_code = 'comment_post' then
    select exists (
      select 1
      from public.pickle_ledger
      where user_id = p_user_id
        and reason_code = 'comment_post'
        and source_comment_id = p_source_comment_id
    )
    into v_exists;

    if v_exists then
      return false;
    end if;

    select count(*)
      into v_daily_count
    from public.pickle_ledger
    where user_id = p_user_id
      and reason_code = 'comment_post'
      and awarded_on = v_awarded_on;

    if v_daily_count >= 20 then
      return false;
    end if;

  else
    return false;
  end if;

  if v_exists then
    return false;
  end if;

  insert into public.pickle_ledger (
    user_id,
    amount,
    reason_code,
    reason_label,
    description,
    source_post_id,
    source_comment_id,
    awarded_on
  )
  values (
    p_user_id,
    p_amount,
    p_reason_code,
    coalesce(nullif(trim(p_reason_label), ''), '피클 획득'),
    coalesce(p_description, ''),
    p_source_post_id,
    p_source_comment_id,
    v_awarded_on
  );

  update public.profiles
  set pickles = coalesce(pickles, 0) + p_amount,
      updated_at = now()
  where id = p_user_id;

  return true;
end;
$$;

create or replace function public.purchase_store_item(p_item_id text)
returns table (
  ok boolean,
  message text,
  balance integer
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid := auth.uid();
  v_price integer := 0;
  v_name text := '';
  v_category text := '';
  v_exists boolean := false;
  v_balance integer := 0;
begin
  if v_user_id is null then
    raise exception '로그인이 필요해.';
  end if;

  if coalesce(trim(p_item_id), '') = '' then
    raise exception '품목 id가 비어 있어.';
  end if;

  if p_item_id = 'emo-basic-01' then
    v_price := 0;
    v_name := '기본 말린오이 이모티콘팩';
    v_category := 'emoticon';

  elsif p_item_id = 'emo-cheer-01' then
    v_price := 150;
    v_name := '응원 오이 이모티콘팩';
    v_category := 'emoticon';

  elsif p_item_id = 'emo-police-01' then
    v_price := 230;
    v_name := '경찰오이 이모티콘팩';
    v_category := 'emoticon';

  elsif p_item_id = 'emo-thanks-01' then
    v_price := 150;
    v_name := '감사오이 이모티콘팩';
    v_category := 'emoticon';

  elsif p_item_id = 'emo-sorry-01' then
    v_price := 180;
    v_name := '사과오이 이모티콘팩';
    v_category := 'emoticon';

  elsif p_item_id = 'emo-carrot-01' then
    v_price := 310;
    v_name := '특별제작 당근 이모티콘팩';
    v_category := 'emoticon';

  elsif p_item_id = 'character-carrot-01' then
    v_price := 530;
    v_name := '테토당근 캐릭터';
    v_category := 'character';

  elsif p_item_id = 'emo-heart-01' then
    v_price := 300;
    v_name := '애정오이 이모티콘팩';
    v_category := 'emoticon';

  else
    return query
    select
      false,
      '아직 구매 가능한 품목이 아니야.',
      coalesce((select p.pickles from public.profiles p where p.id = v_user_id), 0);
    return;
  end if;

  select exists (
    select 1
    from public.user_store_items
    where user_id = v_user_id
      and item_id = p_item_id
  )
  into v_exists;

  if v_exists then
    return query
    select
      false,
      '이미 보유 중인 품목이야.',
      coalesce((select p.pickles from public.profiles p where p.id = v_user_id), 0);
    return;
  end if;

  if v_price > 0 then
    update public.profiles
    set pickles = coalesce(pickles, 0) - v_price,
        updated_at = now()
    where id = v_user_id
      and coalesce(pickles, 0) >= v_price;

    if not found then
      return query
      select
        false,
        '피클이 부족해.',
        coalesce((select p.pickles from public.profiles p where p.id = v_user_id), 0);
      return;
    end if;
  end if;

  insert into public.user_store_items (
    user_id,
    item_id,
    item_name,
    item_category,
    purchase_price
  )
  values (
    v_user_id,
    p_item_id,
    v_name,
    v_category,
    v_price
  );

  if p_item_id = 'emo-basic-01' then
    insert into public.user_emoticons (
      user_id,
