create or replace function public.purchase_store_item(p_item_id text)
returns table (
  ok boolean,
  message text,
  balance integer
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid := auth.uid();
  v_price integer := 0;
  v_name text := '';
  v_category text := '';
  v_exists boolean := false;
  v_balance integer := 0;
begin
  if v_user_id is null then
    raise exception '로그인이 필요해.';
  end if;

  if coalesce(trim(p_item_id), '') = '' then
    raise exception '품목 id가 비어 있어.';
  end if;

  if p_item_id = 'emo-basic-01' then
    v_price := 0;
    v_name := '기본 말린오이 이모티콘팩';
    v_category := 'emoticon';

  elsif p_item_id = 'emo-cheer-01' then
    v_price := 150;
    v_name := '응원 오이 이모티콘팩';
    v_category := 'emoticon';

  elsif p_item_id = 'emo-police-01' then
    v_price := 230;
    v_name := '경찰오이 이모티콘팩';
    v_category := 'emoticon';

  elsif p_item_id = 'emo-thanks-01' then
    v_price := 150;
    v_name := '감사오이 이모티콘팩';
    v_category := 'emoticon';

  elsif p_item_id = 'emo-sorry-01' then
    v_price := 180;
    v_name := '사과오이 이모티콘팩';
    v_category := 'emoticon';

  elsif p_item_id = 'emo-carrot-01' then
    v_price := 310;
    v_name := '특별제작 당근 이모티콘팩';
    v_category := 'emoticon';

  elsif p_item_id = 'character-carrot-01' then
    v_price := 530;
    v_name := '테토당근 캐릭터';
    v_category := 'character';

  elsif p_item_id = 'emo-heart-01' then
    v_price := 300;
    v_name := '애정오이 이모티콘팩';
    v_category := 'emoticon';

  elsif p_item_id = 'skin-cucumbergirl' then
    v_price := 820;
    v_name := '오이소녀 오이스킨';
    v_category := 'skin';

  elsif p_item_id = 'character-fat-avocado-01' then
    v_price := 580;
    v_name := '아보카도 캐릭터';
    v_category := 'character';

  elsif p_item_id = 'character-grilled-egg-01' then
    v_price := 640;
    v_name := '구운계란 캐릭터';
    v_category := 'character';

  else
    return query
    select
      false,
      '아직 구매 가능한 품목이 아니야.',
      coalesce((select p.pickles from public.profiles p where p.id = v_user_id), 0);
    return;
  end if;

  select exists (
    select 1
    from public.user_store_items
    where user_id = v_user_id
      and item_id = p_item_id
  )
  into v_exists;

  if v_exists then
    return query
    select
      false,
      '이미 보유 중인 품목이야.',
      coalesce((select p.pickles from public.profiles p where p.id = v_user_id), 0);
    return;
  end if;

  if v_price > 0 then
    update public.profiles
    set pickles = coalesce(pickles, 0) - v_price,
        updated_at = now()
    where id = v_user_id
      and coalesce(pickles, 0) >= v_price;

    if not found then
      return query
      select
        false,
        '피클이 부족해.',
        coalesce((select p.pickles from public.profiles p where p.id = v_user_id), 0);
      return;
    end if;
  end if;

  insert into public.user_store_items (
    user_id,
    item_id,
    item_name,
    item_category,
    purchase_price
  )
  values (
    v_user_id,
    p_item_id,
    v_name,
    v_category,
    v_price
  );

  if p_item_id = 'emo-basic-01' then
