    );
  end if;

  select coalesce(p.pickles, 0)
    into v_balance
  from public.profiles p
  where p.id = v_user_id;

  return query
  select
    true,
    case
      when p_item_id = 'emo-basic-01'
        then '기본 이모티콘팩이 지급됐어. 이제 게시물/댓글/답글에서 사용할 수 있어.'
      when p_item_id = 'emo-cheer-01'
