      when p_item_id = 'emo-carrot-01'
        then '특별제작 당근 이모티콘팩 구매가 완료됐어. 310피클이 차감됐고 바로 사용할 수 있어.'
      when p_item_id = 'character-carrot-01'
        then '테토당근 캐릭터 구매가 완료됐어. 530피클이 차감됐고 내프로필에서 착용할 수 있어.'
      when p_item_id = 'emo-heart-01'
        then '애정오이 이모티콘팩 구매가 완료됐어. 300피클이 차감됐고 바로 사용할 수 있어.'
      when p_item_id = 'skin-cucumbergirl'
        then '오이소녀 오이스킨 구매가 완료됐어. 820피클이 차감됐고 내프로필 기본오이 스킨 인벤토리에서 착용할 수 있어.'
      when p_item_id = 'character-fat-avocado-01'
        then '아보카도 캐릭터 구매가 완료됐어. 580피클이 차감됐고 내프로필에서 착용할 수 있어.'
      when p_item_id = 'character-grilled-egg-01'
        then '구운계란 캐릭터 구매가 완료됐어. 640피클이 차감됐고 내프로필에서 착용할 수 있어.'
      else '구매가 완료됐어.'
    end,
    coalesce(v_balance, 0);
end;
$$;

grant execute on function public.purchase_store_item(text) to authenticated;

-- 1) 기존 구매내역 문구/분류 정리
update public.user_store_items
set item_name = '오이소녀 캐릭터',
    item_category = 'character'
where item_id = 'skin-cucumbergirl';

-- 2) 기존 스킨 인벤토리 데이터를 오이소녀 캐릭터 전용 기본 스킨으로 변경
update public.user_character_skins
set character_code = 'char-cucumber-girl',
    skin_code = 'char-cucumber-girl-basic',
    skin_name = '오이소녀 캐릭터',
    image_path = './images/characters/cucumbergirl.png',
    display_order = 101
where skin_code = 'char-cucumber-girl'
   or (
     character_code = 'char-cucumber'
     and image_path = './images/skins/cucumbergirl.png'
   );

-- 3) 기존 구매자들에게 오이소녀 캐릭터 자체를 캐릭터 인벤토리에 추가
insert into public.user_characters (
  user_id,
  character_code,
  character_name,
  base_image_path,
  preview_image_path,
  display_order,
  acquired_reason
)
select
  usi.user_id,
  'char-cucumber-girl',
  '오이소녀 캐릭터',
  './images/characters/cucumbergirl.png',
  './images/characters/cucumbergirl.png',
  2,
  'store_purchase'
from public.user_store_items usi
where usi.item_id = 'skin-cucumbergirl'
on conflict (user_id, character_code) do update
set character_name = excluded.character_name,
    base_image_path = excluded.base_image_path,
    preview_image_path = excluded.preview_image_path,
    display_order = excluded.display_order;

-- 4) 현재 착용중인 이미지 경로도 새 경로로 교체
update public.profiles
set equipped_character_image_url = './images/characters/cucumbergirl.png'
where equipped_character_image_url = './images/skins/cucumbergirl.png';

create or replace function public.purchase_store_item(p_item_id text)
returns table (
  ok boolean,
  message text,
  balance integer
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid := auth.uid();
  v_price integer := 0;
  v_name text := '';
  v_category text := '';
  v_exists boolean := false;
  v_balance integer := 0;
begin
  if v_user_id is null then
    raise exception '로그인이 필요해.';
  end if;

  if coalesce(trim(p_item_id), '') = '' then
    raise exception '품목 id가 비어 있어.';
  end if;

  if p_item_id = 'emo-basic-01' then
    v_price := 0;
    v_name := '기본 말린오이 이모티콘팩';
    v_category := 'emoticon';

