      when p_item_id = 'emo-carrot-01'
        then '특별제작 당근 이모티콘팩 구매가 완료됐어. 310피클이 차감됐고 바로 사용할 수 있어.'
      when p_item_id = 'character-carrot-01'
        then '테토당근 캐릭터 구매가 완료됐어. 530피클이 차감됐고 내프로필에서 착용할 수 있어.'
      when p_item_id = 'emo-heart-01'
        then '애정오이 이모티콘팩 구매가 완료됐어. 300피클이 차감됐고 바로 사용할 수 있어.'
      when p_item_id = 'skin-cucumbergirl'
        then '오이소녀 캐릭터 구매가 완료됐어. 820피클이 차감됐고 내프로필 캐릭터 인벤토리에서 착용할 수 있어.'
      when p_item_id = 'character-fat-avocado-01'
        then '아보카도 캐릭터 구매가 완료됐어. 580피클이 차감됐고 내프로필에서 착용할 수 있어.'
      when p_item_id = 'character-grilled-egg-01'
        then '구운계란 캐릭터 구매가 완료됐어. 640피클이 차감됐고 내프로필에서 착용할 수 있어.'
      when p_item_id = 'emo-sad-01'
        then '슬픈오이 이모티콘팩 구매가 완료됐어. 210피클이 차감됐고 바로 사용할 수 있어.'
      when p_item_id = 'skin-cucumbergirl-01'
        then '오이소녀 경찰스킨 구매가 완료됐어. 923피클이 차감됐고 내프로필 오이소녀 스킨 인벤토리에서 착용할 수 있어.'
              when p_item_id = 'bgm-tetocarrot-01'
        then '테토당근 BGM 구매가 완료됐어. 420피클이 차감됐고 내프로필 BGM 인벤토리에서 장착할 수 있어.'
      else '구매가 완료됐어.'
      
    end,
    coalesce(v_balance, 0);
end;
$$;

grant execute on function public.purchase_store_item(text) to authenticated;

alter table public.profiles
  add column if not exists bgm_selected_track_ids jsonb not null default '["mallin-oi-welcome"]'::jsonb,
  add column if not exists bgm_current_track_id text;

comment on column public.profiles.bgm_selected_track_ids is '프로필에서 선택한 BGM 트랙 ID 목록';
comment on column public.profiles.bgm_current_track_id is '현재 대표 BGM 트랙 ID';

update public.profiles
set
  bgm_selected_track_ids = coalesce(bgm_selected_track_ids, '["mallin-oi-welcome"]'::jsonb),
  bgm_current_track_id = coalesce(nullif(trim(bgm_current_track_id), ''), 'mallin-oi-welcome')
where
  bgm_selected_track_ids is null
  or bgm_current_track_id is null
  or trim(coalesce(bgm_current_track_id, '')) = '';

  insert into public.user_character_skins (
  user_id,
  character_code,
  skin_code,
  skin_name,
  image_path,
  display_order,
  acquired_reason
)
select
  usi.user_id,
  'char-cucumber-girl',
  'char-cucumber-girl-police',
  '오이소녀 경찰스킨',
  './images/skins/cucumbergirl-police.png',
  102,
  'store_purchase'
from public.user_store_items usi
where usi.item_id = 'skin-cucumbergirl-01'
  and not exists (
    select 1
    from public.user_character_skins ucs
    where ucs.user_id = usi.user_id
      and ucs.skin_code = 'char-cucumber-girl-police'
  );

  -- =========================================================
-- 1) 피클 원장 reason_code 확장
-- =========================================================
alter table public.pickle_ledger
drop constraint if exists pickle_ledger_reason_code_check;

alter table public.pickle_ledger
add constraint pickle_ledger_reason_code_check
check (
  reason_code in (
    'attendance',
    'post_create',
    'comment_post',
    'store_purchase',
    'post_reaction',
    'admin_auto_charge',
    'event_grant'
  )
);

-- =========================================================
-- 2) 관리자 자동충전 대상 판별 함수
--    현재 관리자 계정: junna961@icloud.com
-- =========================================================
create or replace function public.is_auto_topup_admin_user(p_user_id uuid)
returns boolean
language sql
security definer
stable
set search_path = public
as $$
  select exists (
    select 1
    from public.profiles p
    where p.id = p_user_id
      and lower(coalesce(p.email, '')) = lower('junna961@icloud.com')
  );
$$;

grant execute on function public.is_auto_topup_admin_user(uuid) to authenticated;

-- =========================================================
-- 3) 부족한 만큼만 자동충전하는 공용 함수
--    나중에 이벤트 지급 기능에서도 재사용 가능
-- =========================================================
create or replace function public.ensure_user_pickles(
  p_user_id uuid,
  p_required_amount integer,
  p_reason_code text default 'admin_auto_charge',
  p_reason_label text default '관리자 자동충전',
  p_description text default null
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_balance integer := 0;
  v_shortage integer := 0;
begin
  if p_user_id is null then
    raise exception 'USER_NOT_FOUND';
  end if;

  if coalesce(p_required_amount, 0) <= 0 then
    select coalesce(p.pickles, 0)
      into v_balance
    from public.profiles p
    where p.id = p_user_id;

    return coalesce(v_balance, 0);
  end if;

  select coalesce(p.pickles, 0)
    into v_balance
  from public.profiles p
  where p.id = p_user_id
  for update;

  v_shortage := greatest(p_required_amount - coalesce(v_balance, 0), 0);

  if v_shortage > 0 then
    update public.profiles
    set pickles = coalesce(pickles, 0) + v_shortage,
        updated_at = now()
    where id = p_user_id;

    insert into public.pickle_ledger (
      user_id,
      amount,
      reason_code,
      reason_label,
      description,
      awarded_on
    )
    values (
      p_user_id,
      v_shortage,
      coalesce(nullif(trim(p_reason_code), ''), 'admin_auto_charge'),
      coalesce(nullif(trim(p_reason_label), ''), '관리자 자동충전'),
      coalesce(
        p_description,
        '구매/지급 진행을 위해 부족한 피클만큼 자동충전'
      ),
      public.seoul_today()
    );

    v_balance := coalesce(v_balance, 0) + v_shortage;
  end if;

  return coalesce(v_balance, 0);
end;
$$;

grant execute on function public.ensure_user_pickles(uuid, integer, text, text, text) to authenticated;

-- =========================================================
-- 4) 상점 구매 함수 전체 교체
--    - 관리자 자동충전 적용
--    - 오이소녀 경찰스킨 지급 분기 정상화
--    - 테토당근 BGM 분기 정상화
-- =========================================================
create or replace function public.purchase_store_item(p_item_id text)
returns table (
  ok boolean,
  message text,
  balance integer
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid := auth.uid();
  v_price integer := 0;
  v_name text := '';
  v_category text := '';
  v_exists boolean := false;
  v_balance integer := 0;
  v_is_auto_topup_admin boolean := false;
begin
  if v_user_id is null then
    raise exception '로그인이 필요해.';
  end if;

  if coalesce(trim(p_item_id), '') = '' then
    raise exception '품목 id가 비어 있어.';
  end if;

  if p_item_id = 'emo-basic-01' then
    v_price := 0;
    v_name := '기본 말린오이 이모티콘팩';
    v_category := 'emoticon';

  elsif p_item_id = 'emo-cheer-01' then
    v_price := 150;
    v_name := '응원 오이 이모티콘팩';
    v_category := 'emoticon';

  elsif p_item_id = 'emo-police-01' then
    v_price := 230;
    v_name := '경찰오이 이모티콘팩';
    v_category := 'emoticon';

  elsif p_item_id = 'emo-thanks-01' then
    v_price := 150;
    v_name := '감사오이 이모티콘팩';
    v_category := 'emoticon';

  elsif p_item_id = 'emo-sorry-01' then
    v_price := 180;
    v_name := '사과오이 이모티콘팩';
    v_category := 'emoticon';

  elsif p_item_id = 'emo-carrot-01' then
    v_price := 310;
    v_name := '특별제작 당근 이모티콘팩';
    v_category := 'emoticon';

  elsif p_item_id = 'character-carrot-01' then
    v_price := 530;
    v_name := '테토당근 캐릭터';
    v_category := 'character';

  elsif p_item_id = 'emo-heart-01' then
    v_price := 300;
    v_name := '애정오이 이모티콘팩';
    v_category := 'emoticon';

  elsif p_item_id = 'skin-cucumbergirl' then
    v_price := 820;
    v_name := '오이소녀 캐릭터';
    v_category := 'character';

  elsif p_item_id = 'character-fat-avocado-01' then
    v_price := 580;
    v_name := '아보카도 캐릭터';
    v_category := 'character';

  elsif p_item_id = 'character-grilled-egg-01' then
    v_price := 640;
    v_name := '구운계란 캐릭터';
    v_category := 'character';

  elsif p_item_id = 'emo-sad-01' then
    v_price := 210;
    v_name := '슬픈오이 이모티콘팩';
    v_category := 'emoticon';

  elsif p_item_id = 'skin-cucumbergirl-01' then
    v_price := 923;
    v_name := '오이소녀 경찰스킨';
    v_category := 'skin';

  elsif p_item_id = 'bgm-tetocarrot-01' then
    v_price := 420;
    v_name := '테토당근 BGM';
    v_category := 'bgm';

  else
    return query
    select
      false,
      '아직 구매 가능한 품목이 아니야.',
      coalesce((select p.pickles from public.profiles p where p.id = v_user_id), 0);
    return;
  end if;

  select exists (
    select 1
    from public.user_store_items
    where user_id = v_user_id
      and item_id = p_item_id
  )
  into v_exists;

  if v_exists then
    return query
    select
      false,
      '이미 보유 중인 품목이야.',
      coalesce((select p.pickles from public.profiles p where p.id = v_user_id), 0);
    return;
  end if;

  if v_price > 0 then
    select public.is_auto_topup_admin_user(v_user_id)
      into v_is_auto_topup_admin;

    if coalesce(v_is_auto_topup_admin, false) then
      perform public.ensure_user_pickles(
        v_user_id,
        v_price,
        'admin_auto_charge',
        '관리자 자동충전',
        v_name || ' 구매 전 부족 피클 자동충전'
      );
    end if;

    update public.profiles
    set pickles = coalesce(pickles, 0) - v_price,
        updated_at = now()
    where id = v_user_id
      and coalesce(pickles, 0) >= v_price;

    if not found then
      return query
      select
        false,
        '피클이 부족해.',
        coalesce((select p.pickles from public.profiles p where p.id = v_user_id), 0);
      return;
    end if;
  end if;

  insert into public.user_store_items (
    user_id,
    item_id,
    item_name,
    item_category,
    purchase_price
  )
  values (
    v_user_id,
    p_item_id,
    v_name,
    v_category,
    v_price
  );

  if p_item_id = 'emo-basic-01' then
    insert into public.user_emoticons (
      user_id,
      item_id,
      emoticon_code,
      emoticon_label,
      image_path,
      display_order
    )
    values
      (v_user_id, 'emo-basic-01', 'free-1', '기본 이모티콘 1', './images/emoticons/free-1.png', 1),
      (v_user_id, 'emo-basic-01', 'free-2', '기본 이모티콘 2', './images/emoticons/free-2.png', 2),
      (v_user_id, 'emo-basic-01', 'free-3', '기본 이모티콘 3', './images/emoticons/free-3.png', 3),
      (v_user_id, 'emo-basic-01', 'free-4', '기본 이모티콘 4', './images/emoticons/free-4.png', 4),
      (v_user_id, 'emo-basic-01', 'free-5', '기본 이모티콘 5', './images/emoticons/free-5.png', 5),
      (v_user_id, 'emo-basic-01', 'free-6', '기본 이모티콘 6', './images/emoticons/free-6.png', 6),
      (v_user_id, 'emo-basic-01', 'free-7', '기본 이모티콘 7', './images/emoticons/free-7.png', 7)
    on conflict (user_id, emoticon_code) do nothing;

  elsif p_item_id = 'emo-cheer-01' then
    insert into public.user_emoticons (
      user_id,
      item_id,
      emoticon_code,
      emoticon_label,
      image_path,
      display_order
    )
    values
      (v_user_id, 'emo-cheer-01', 'cheer-1', '응원 이모티콘 1', './images/emoticons/cheer-1.png', 101),
      (v_user_id, 'emo-cheer-01', 'cheer-2', '응원 이모티콘 2', './images/emoticons/cheer-2.png', 102),
      (v_user_id, 'emo-cheer-01', 'cheer-3', '응원 이모티콘 3', './images/emoticons/cheer-3.png', 103),
      (v_user_id, 'emo-cheer-01', 'cheer-4', '응원 이모티콘 4', './images/emoticons/cheer-4.png', 104),
      (v_user_id, 'emo-cheer-01', 'cheer-5', '응원 이모티콘 5', './images/emoticons/cheer-5.png', 105)
    on conflict (user_id, emoticon_code) do nothing;

  elsif p_item_id = 'emo-police-01' then
    insert into public.user_emoticons (
      user_id,
      item_id,
      emoticon_code,
      emoticon_label,
      image_path,
