    v_price := 542;
    v_name := '오이소녀의 데뷔 BGM';
    v_category := 'bgm';

      elsif p_item_id = 'emo-eat-01' then
    v_price := 220;
    v_name := '먹방오이 이모티콘팩';
    v_category := 'emoticon';

