create extension if not exists pgcrypto;

create or replace function public.create_suggestion_thread(
  p_body text,
  p_is_secret boolean default false,
  p_secret_password text default ''
)
returns bigint
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid := auth.uid();
  v_nickname text := '익명';
  v_id bigint;
  v_password text := trim(coalesce(p_secret_password, ''));
begin
  if v_user_id is null then
    raise exception '로그인이 필요해.';
  end if;

  if char_length(trim(coalesce(p_body, ''))) < 1 then
    raise exception '내용을 입력해줘.';
  end if;

  if char_length(p_body) > 1000 then
    raise exception '1000자 이하만 가능해.';
  end if;

  if p_is_secret and v_password = '' then
    raise exception '비밀글 비밀번호를 입력해줘.';
  end if;

  select coalesce(nullif(trim(nickname), ''), '익명')
    into v_nickname
  from public.profiles
  where id = v_user_id;

  insert into public.suggestions (
    body,
    author_id,
    author_nickname,
    is_secret,
    secret_password_hash
  )
  values (
    trim(p_body),
    v_user_id,
    v_nickname,
    coalesce(p_is_secret, false),
    case
      when coalesce(p_is_secret, false)
        then public.sha256_hex(public.normalize_secret_password(v_password))
      else null
    end
  )
  returning id into v_id;

  return v_id;
end;
$$;

grant execute on function public.create_suggestion_thread(text, boolean, text) to authenticated;

create or replace function public.list_suggestion_threads()
returns table (
  id bigint,
  body text,
  author_id uuid,
  author_nickname text,
  created_at timestamptz,
  is_secret boolean,
  is_mine boolean,
  can_edit boolean,
  can_delete boolean,
  can_view_full boolean
)
language sql
security definer
set search_path = public
as $$
  select
    s.id,
    case
      when s.is_secret and not public.is_admin_user(auth.uid()) then null
      else s.body
    end as body,
    s.author_id,
    s.author_nickname,
    s.created_at,
    s.is_secret,
    (auth.uid() = s.author_id) as is_mine,
    (
      auth.uid() = s.author_id
      and (not s.is_secret or false)
    ) as can_edit,
    (
      auth.uid() = s.author_id
      or public.is_admin_user(auth.uid())
    ) as can_delete,
    (
      not s.is_secret
      or public.is_admin_user(auth.uid())
    ) as can_view_full
  from public.suggestions s
  order by s.created_at desc, s.id desc;
$$;

grant execute on function public.list_suggestion_threads() to anon, authenticated;

create or replace function public.list_qna_threads()
returns table (
  id bigint,
  body text,
  author_id uuid,
  author_nickname text,
  created_at timestamptz,
  is_secret boolean,
  is_mine boolean,
  can_edit boolean,
  can_delete boolean,
  can_view_full boolean
)
language sql
security definer
set search_path = public
as $$
  select
    q.id,
    case
      when q.is_secret and not public.is_admin_user(auth.uid()) then null
      else q.body
    end as body,
    q.author_id,
    q.author_nickname,
    q.created_at,
    q.is_secret,
    (auth.uid() = q.author_id) as is_mine,
    (
      auth.uid() = q.author_id
      and (not q.is_secret or false)
    ) as can_edit,
    (
      auth.uid() = q.author_id
      or public.is_admin_user(auth.uid())
    ) as can_delete,
    (
      not q.is_secret
      or public.is_admin_user(auth.uid())
    ) as can_view_full
  from public.qna_threads q
  order by q.created_at desc, q.id desc;
$$;

grant execute on function public.list_qna_threads() to anon, authenticated;

create or replace function public.unlock_suggestion_thread(
  p_thread_id bigint,
  p_secret_password text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_row public.suggestions%rowtype;
  v_ok boolean := false;
begin
  select *
    into v_row
  from public.suggestions
  where id = p_thread_id;

  if not found then
    return jsonb_build_object('success', false, 'message', '글이 없어.');
  end if;

  if public.is_admin_user(v_uid) then
    v_ok := true;
  elsif v_uid = v_row.author_id then
    v_ok := (
      v_row.secret_password_hash =
      public.sha256_hex(public.normalize_secret_password(p_secret_password))
    );
  else
    return jsonb_build_object('success', false, 'message', '권한이 없어.');
  end if;

  if not v_ok then
    return jsonb_build_object('success', false, 'message', '비밀번호가 일치하지 않아.');
  end if;

  return jsonb_build_object(
    'success', true,
    'body', v_row.body,
    'replies',
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'id', c.id,
            'thread_id', c.suggestion_id,
            'body', c.body,
            'author_id', c.author_id,
            'author_nickname', c.author_nickname,
            'created_at', c.created_at
          )
          order by c.created_at asc, c.id asc
        )
        from public.suggestion_admin_comments c
        where c.suggestion_id = v_row.id
      ),
      '[]'::jsonb
    )
  );
end;
$$;

grant execute on function public.unlock_suggestion_thread(bigint, text) to authenticated;

create or replace function public.create_qna_reply(
  p_thread_id bigint,
  p_body text
)
returns bigint
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_nickname text := '관리자';
  v_id bigint;
begin
  if v_uid is null then
    raise exception '로그인이 필요해.';
  end if;

  if not public.is_admin_user(v_uid) then
    raise exception '관리자만 답변 가능해.';
  end if;

  if char_length(trim(coalesce(p_body, ''))) < 1 then
    raise exception '답변 내용을 입력해줘.';
  end if;

  if char_length(p_body) > 500 then
    raise exception '답변은 500자 이하로 입력해줘.';
  end if;

  select coalesce(nullif(trim(nickname), ''), '관리자')
    into v_nickname
  from public.profiles
  where id = v_uid;

  insert into public.qna_admin_comments (
    thread_id, body, author_id, author_nickname
  )
  values (
    p_thread_id, trim(p_body), v_uid, v_nickname
  )
  returning id into v_id;

  return v_id;
end;
$$;

grant execute on function public.create_qna_reply(bigint, text) to authenticated;

alter table public.suggestions enable row level security;
alter table public.suggestion_admin_comments enable row level security;
alter table public.qna_threads enable row level security;
alter table public.qna_admin_comments enable row level security;

drop policy if exists "건의사항 조회는 모두 가능" on public.suggestions;
