drop policy if exists "qna replies select all" on public.qna_admin_comments;

create policy "suggestions_insert_owner"
on public.suggestions
for insert
to authenticated
with check (auth.uid() = author_id);

create policy "suggestions_update_owner"
on public.suggestions
for update
to authenticated
using (auth.uid() = author_id)
with check (auth.uid() = author_id);

create policy "suggestions_delete_owner_or_admin"
on public.suggestions
for delete
to authenticated
using (
  auth.uid() = author_id
  or public.is_admin_user(auth.uid())
);

create policy "suggestion_admin_reply_insert"
on public.suggestion_admin_comments
for insert
to authenticated
with check (
  auth.uid() = author_id
  and public.is_admin_user(auth.uid())
);

create policy "suggestion_admin_reply_delete"
on public.suggestion_admin_comments
for delete
to authenticated
using (public.is_admin_user(auth.uid()));

create or replace function public.create_qna_thread(
  p_body text,
  p_is_secret boolean default false,
  p_secret_password text default ''
)
returns bigint
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid := auth.uid();
  v_nickname text := '익명';
  v_id bigint;
  v_password text := trim(coalesce(p_secret_password, ''));
begin
  if v_user_id is null then
    raise exception '로그인이 필요해.';
  end if;

  if char_length(trim(coalesce(p_body, ''))) < 1 then
    raise exception '내용을 입력해줘.';
  end if;

  if char_length(coalesce(p_body, '')) > 1000 then
    raise exception '1000자 이하만 가능해.';
  end if;

  if coalesce(p_is_secret, false) and v_password = '' then
    raise exception '비밀글 비밀번호를 입력해줘.';
  end if;

  select coalesce(nullif(trim(nickname), ''), '익명')
    into v_nickname
  from public.profiles
  where id = v_user_id;

  insert into public.qna_threads (
    body,
    author_id,
    author_nickname,
    is_secret,
    secret_password_hash
  )
  values (
    trim(p_body),
    v_user_id,
    v_nickname,
    coalesce(p_is_secret, false),
    case
      when coalesce(p_is_secret, false)
        then public.sha256_hex(public.normalize_secret_password(v_password))
      else null
    end
  )
  returning id into v_id;

  return v_id;
end;
$$;

