create or replace function public.delete_qna_thread(
  p_thread_id bigint
)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_author_id uuid;
begin
  if v_uid is null then
    raise exception '로그인이 필요해.';
  end if;

  select author_id
    into v_author_id
  from public.qna_threads
  where id = p_thread_id;

  if v_author_id is null then
    raise exception '글이 없어.';
  end if;

  if v_uid <> v_author_id and not public.is_admin_user(v_uid) then
    raise exception '삭제 권한이 없어.';
  end if;

  delete from public.qna_threads
  where id = p_thread_id;

  return true;
end;
$$;

grant execute on function public.delete_qna_thread(bigint) to authenticated;

