create or replace function public.update_qna_thread(
  p_thread_id bigint,
  p_body text
)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_author_id uuid;
  v_is_secret boolean;
begin
  if v_uid is null then
    raise exception '로그인이 필요해.';
  end if;

  if char_length(trim(coalesce(p_body, ''))) < 1 then
    raise exception '내용을 입력해줘.';
  end if;

  if char_length(coalesce(p_body, '')) > 1000 then
    raise exception '1000자 이하만 가능해.';
  end if;

  select author_id, is_secret
    into v_author_id, v_is_secret
  from public.qna_threads
  where id = p_thread_id;

  if v_author_id is null then
    raise exception '글이 없어.';
  end if;

  if v_uid <> v_author_id then
    raise exception '수정 권한이 없어.';
  end if;

  if v_is_secret then
    raise exception '비밀글 수정은 잠금 해제 흐름에서만 허용하도록 별도 처리해줘.';
  end if;

  update public.qna_threads
  set body = trim(p_body),
      updated_at = now()
  where id = p_thread_id;

  return true;
end;
$$;

grant execute on function public.update_qna_thread(bigint, text) to authenticated;

create or replace function public.create_qna_thread(
  p_body text,
  p_is_secret boolean default false,
  p_secret_password text default ''
)
returns bigint
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid := auth.uid();
  v_nickname text := '익명';
  v_id bigint;
  v_password text := public.normalize_secret_password(p_secret_password);
begin
  if v_user_id is null then
    raise exception '로그인이 필요해.';
  end if;

  if char_length(trim(coalesce(p_body, ''))) < 1 then
    raise exception '내용을 입력해줘.';
  end if;

  if char_length(coalesce(p_body, '')) > 1000 then
    raise exception '1000자 이하만 가능해.';
  end if;

  if coalesce(p_is_secret, false) and nullif(v_password, '') is null then
    raise exception '비밀글 비밀번호를 입력해줘.';
  end if;

  select coalesce(nullif(trim(nickname), ''), '익명')
    into v_nickname
  from public.profiles
  where id = v_user_id;

  insert into public.qna_threads (
    body,
    author_id,
    author_nickname,
    is_secret,
    secret_password_hash
  )
  values (
    trim(p_body),
    v_user_id,
    v_nickname,
    coalesce(p_is_secret, false),
    case
      when coalesce(p_is_secret, false)
        then public.sha256_hex(v_password)
      else null
    end
  )
  returning id into v_id;

  return v_id;
end;
$$;

grant execute on function public.create_qna_thread(text, boolean, text) to authenticated;

