begin;

create extension if not exists pgcrypto schema extensions;

create or replace function public.normalize_secret_password(p_value text)
returns text
language sql
immutable
as $$
  select trim(coalesce(p_value, ''));
$$;

create or replace function public.sha256_hex(p_value text)
returns text
language sql
immutable
as $$
  select encode(
    extensions.digest(
      convert_to(coalesce(p_value, ''), 'UTF8'),
      'sha256'
    ),
    'hex'
  );
$$;

-- =========================================
-- 건의사항: 목록 조회 (수정 불가이므로 can_edit=false 고정)
-- =========================================
create or replace function public.list_suggestion_threads()
returns table (
  id bigint,
  body text,
  author_id uuid,
  author_nickname text,
  created_at timestamptz,
  is_secret boolean,
  is_mine boolean,
  can_edit boolean,
  can_delete boolean,
  can_view_full boolean
)
language sql
security definer
set search_path = public
as $$
  select
    s.id,
    case
      when s.is_secret and not public.is_admin_user(auth.uid()) then null
      else s.body
    end as body,
    s.author_id,
    s.author_nickname,
    s.created_at,
    s.is_secret,
    (auth.uid() = s.author_id) as is_mine,
    false as can_edit,
    (
      auth.uid() = s.author_id
      or public.is_admin_user(auth.uid())
    ) as can_delete,
    (
      not s.is_secret
      or public.is_admin_user(auth.uid())
    ) as can_view_full
  from public.suggestions s
  order by s.created_at desc, s.id desc;
$$;

