-- 기존 유저별 기본 카테고리 생성
insert into public.study_calendar_categories (
  user_id,
  name,
  slug,
  color,
  is_default,
  sort_order
)
select distinct
  user_id,
  '공부',
  'study',
  '#e7f6ff',
  true,
  10
from public.study_calendar_todos
where user_id is not null
on conflict (user_id, slug) do nothing;

insert into public.study_calendar_categories (
  user_id,
  name,
  slug,
  color,
  is_default,
  sort_order
)
select distinct
  user_id,
  '운동',
  'workout',
  '#eaffd7',
  true,
  20
from public.study_calendar_todos
where user_id is not null
on conflict (user_id, slug) do nothing;

insert into public.study_calendar_categories (
  user_id,
  name,
  slug,
  color,
  is_default,
  sort_order
)
select distinct
  user_id,
  '기타',
  'etc',
  '#fff1d1',
  true,
  30
from public.study_calendar_todos
where user_id is not null
on conflict (user_id, slug) do nothing;

-- 기존 todo_type 문자열 데이터를 category_id와 연결
update public.study_calendar_todos t
set category_id = c.id
from public.study_calendar_categories c
where t.user_id = c.user_id
  and t.category_id is null
  and c.slug = case
    when t.todo_type = 'study' then 'study'
    when t.todo_type = 'workout' then 'workout'
    else 'etc'
  end;

-- category_id가 없는 기존 데이터는 기타로 보정
update public.study_calendar_todos t
set category_id = c.id,
    todo_type = 'etc'
from public.study_calendar_categories c
where t.user_id = c.user_id
  and t.category_id is null
  and c.slug = 'etc';

