after insert on public.post_comments
for each row
execute function public.handle_pickle_on_comment_insert();

create or replace function public.toggle_post_reaction(
  p_post_id bigint,
  p_reaction_type text
)
returns table (
  likes_count bigint,
  dislikes_count bigint,
  my_reaction text,
  reward_granted boolean,
  reward_amount integer
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid;
  v_existing_reaction text;
  v_safe_reaction text;
  v_post_author_id uuid;
  v_actor_nickname text;
  v_created_new_reaction boolean := false;
  v_reward_granted boolean := false;
  v_reward_amount integer := 0;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  v_safe_reaction := lower(trim(coalesce(p_reaction_type, '')));

  if v_safe_reaction not in ('like', 'dislike') then
    raise exception 'INVALID_REACTION_TYPE';
  end if;

  select p.author_id
    into v_post_author_id
  from public.posts p
  where p.id = p_post_id;

  if v_post_author_id is null then
    raise exception 'POST_NOT_FOUND';
  end if;

  select reaction_type
    into v_existing_reaction
  from public.post_reactions
  where post_id = p_post_id
    and user_id = v_user_id
  limit 1;

  if v_existing_reaction is null then
    insert into public.post_reactions (
      post_id,
      user_id,
      reaction_type
    )
    values (
      p_post_id,
      v_user_id,
      v_safe_reaction
    );

    v_created_new_reaction := true;
    v_reward_granted := public.grant_pickle_reward(
      v_user_id,
      1,
      'post_reaction',
      '게시물 반응',
      '좋아요/참신해요 반응으로 피클을 받았어.',
      p_post_id,
      null,
      public.seoul_today()
    );
    v_reward_amount := case when v_reward_granted then 1 else 0 end;

  elsif v_existing_reaction = v_safe_reaction then
    delete from public.post_reactions
    where post_id = p_post_id
      and user_id = v_user_id;

  else
    update public.post_reactions
    set reaction_type = v_safe_reaction,
        updated_at = now()
    where post_id = p_post_id
      and user_id = v_user_id;
  end if;

  if v_created_new_reaction
    and v_post_author_id is not null
    and v_post_author_id <> v_user_id then

    select coalesce(nullif(trim(p.nickname), ''), '익명')
      into v_actor_nickname
    from public.profiles p
    where p.id = v_user_id;

    insert into public.user_notifications (
      recipient_user_id,
      actor_user_id,
      actor_nickname,
      post_id,
      comment_id,
      notification_type,
      title,
      message,
      action_url,
      metadata
    )
    select
      v_post_author_id,
      v_user_id,
      coalesce(v_actor_nickname, '익명'),
      p_post_id,
      null,
      case
        when v_safe_reaction = 'like' then 'post_reaction_like'
        else 'post_reaction_dislike'
      end,
      case
        when v_safe_reaction = 'like'
          then format('%s님이 네 게시글을 좋아해.', coalesce(v_actor_nickname, '익명'))
        else format('%s님이 네 게시글을 참신해해.', coalesce(v_actor_nickname, '익명'))
      end,
      case
        when v_safe_reaction = 'like'
          then '좋아요가 눌렸어.'
        else '참신해요가 눌렸어.'
      end,
      format('/post.html?id=%s', p_post_id),
      jsonb_build_object('reactionType', v_safe_reaction)
    where not exists (
      select 1
      from public.user_notifications n
      where n.recipient_user_id = v_post_author_id
        and n.actor_user_id = v_user_id
        and n.post_id = p_post_id
        and n.notification_type = case
          when v_safe_reaction = 'like' then 'post_reaction_like'
          else 'post_reaction_dislike'
        end
        and n.created_at > now() - interval '12 hours'
    );
  end if;

  return query
  select
    coalesce(count(*) filter (where pr.reaction_type = 'like'), 0)::bigint as likes_count,
    coalesce(count(*) filter (where pr.reaction_type = 'dislike'), 0)::bigint as dislikes_count,
    (
      select pr2.reaction_type
      from public.post_reactions pr2
      where pr2.post_id = p_post_id
        and pr2.user_id = v_user_id
      limit 1
    ) as my_reaction,
    v_reward_granted as reward_granted,
    v_reward_amount as reward_amount
  from public.post_reactions pr
  where pr.post_id = p_post_id;
end;
$$;

grant execute on function public.toggle_post_reaction(bigint, text)
to authenticated;


-- =========================================
-- 캘린더 그룹 공유 기능 누적본 (2026-05-28)
-- Supabase SQL Editor 실행 대상: calendar-groups.sql과 동일
-- =========================================

-- =========================================
-- 캘린더 그룹 공유 기능
-- 2026-05-28
-- =========================================

create extension if not exists pgcrypto;

create table if not exists public.calendar_groups (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references auth.users(id) on delete cascade,
  name text not null,
  color text not null default '#f54260',
  visibility text not null default 'public',
  password_hash text,
  is_hidden boolean not null default false,
  allow_study boolean not null default true,
  allow_work boolean not null default true,
  allow_event boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  constraint calendar_groups_name_check
    check (char_length(trim(name)) between 1 and 30),
  constraint calendar_groups_color_check
    check (color ~ '^#[0-9A-Fa-f]{6}$'),
  constraint calendar_groups_visibility_check
    check (visibility in ('public', 'private')),
  constraint calendar_groups_allow_one_check
    check (allow_study or allow_work or allow_event)
);

create index if not exists calendar_groups_visible_idx
  on public.calendar_groups (is_hidden, visibility, created_at desc);

create table if not exists public.calendar_group_members (
  id uuid primary key default gen_random_uuid(),
  group_id uuid not null references public.calendar_groups(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  role text not null default 'member',
  status text not null default 'active',
  joined_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  constraint calendar_group_members_role_check
    check (role in ('owner', 'admin', 'member')),
  constraint calendar_group_members_status_check
    check (status in ('active', 'invited', 'blocked', 'left')),
  constraint calendar_group_members_unique
    unique (group_id, user_id)
);

create index if not exists calendar_group_members_user_idx
  on public.calendar_group_members (user_id, status, group_id);

create table if not exists public.calendar_group_invites (
  id uuid primary key default gen_random_uuid(),
  group_id uuid not null references public.calendar_groups(id) on delete cascade,
  inviter_id uuid not null references auth.users(id) on delete cascade,
  invitee_id uuid not null references auth.users(id) on delete cascade,
  status text not null default 'pending',
  created_at timestamptz not null default now(),
  responded_at timestamptz,

  constraint calendar_group_invites_status_check
    check (status in ('pending', 'accepted', 'declined', 'cancelled'))
);

create index if not exists calendar_group_invites_invitee_idx
  on public.calendar_group_invites (invitee_id, status, created_at desc);

create table if not exists public.calendar_group_shared_events (
  id uuid primary key default gen_random_uuid(),
  group_id uuid not null references public.calendar_groups(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  calendar_type text not null,
  source_event_id text not null,
  event_date date not null,
  event_type text,
  title text not null,
  memo text not null default '',
  color text,
  payload jsonb not null default '{}'::jsonb,
  backed_up_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  constraint calendar_group_shared_events_type_check
    check (calendar_type in ('study', 'work', 'event')),
  constraint calendar_group_shared_events_title_check
    check (char_length(trim(title)) between 1 and 100),
  constraint calendar_group_shared_events_unique
    unique (group_id, user_id, calendar_type, source_event_id)
);

create index if not exists calendar_group_shared_events_view_idx
  on public.calendar_group_shared_events (group_id, calendar_type, event_date, user_id);

create table if not exists public.calendar_group_user_settings (
  id uuid primary key default gen_random_uuid(),
  group_id uuid not null references public.calendar_groups(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  is_hidden_for_user boolean not null default false,
  selected boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  constraint calendar_group_user_settings_unique
    unique (group_id, user_id)
);

