  if not public.is_calendar_group_member(p_group_id, auth.uid()) then
    raise exception '그룹 멤버만 볼 수 있습니다.';
  end if;

  select case p_calendar_type
    when 'study' then cg.allow_study
    when 'work' then cg.allow_work
    when 'event' then cg.allow_event
    else false
  end
    into v_allowed
  from public.calendar_groups cg
  where cg.id = p_group_id;

  if not coalesce(v_allowed, false) then
    return;
  end if;

  return query
  select
    e.id,
    e.group_id,
    e.user_id,
    coalesce(nullif(trim(p.nickname), ''), '회원') as user_nickname,
    e.calendar_type,
    e.source_event_id,
    e.event_date,
    e.event_type,
    e.title,
    e.memo,
    e.color,
    e.payload,
    e.backed_up_at
  from public.calendar_group_shared_events e
  join public.calendar_group_members m
    on m.group_id = e.group_id
   and m.user_id = e.user_id
   and m.status = 'active'
  left join public.profiles p on p.id = e.user_id
  where e.group_id = p_group_id
    and e.calendar_type = p_calendar_type
    and e.event_date between p_start_date and p_end_date
  order by e.event_date, coalesce(nullif(trim(p.nickname), ''), '회원'), e.created_at;
end;
$$;

grant execute on function public.backup_my_calendar_to_group(uuid, text) to authenticated;

grant execute on function public.get_group_calendar_view(uuid, text, date, date) to authenticated;


-- 20260529-01 캘린더 그룹장 양도 및 그룹 삭제 RPC 추가

create or replace function public.leave_calendar_group(p_group_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_member_count bigint := 0;
begin
  if v_uid is null then
    raise exception '로그인이 필요합니다.';
  end if;

  if exists (
    select 1
    from public.calendar_groups g
    join public.calendar_group_members m on m.group_id = g.id
    where g.id = p_group_id
      and m.user_id = v_uid
      and m.status = 'active'
      and (g.owner_id = v_uid or m.role = 'owner')
  ) then
    select count(*)
      into v_member_count
    from public.calendar_group_members
    where group_id = p_group_id
      and status = 'active';

    if v_member_count > 1 then
      raise exception '먼저 그룹장을 넘긴 뒤 나갈 수 있습니다.';
    end if;

    raise exception '그룹장은 바로 나갈 수 없습니다. 그룹을 삭제해 주세요.';
  end if;

  update public.calendar_group_members
  set status = 'left',
      updated_at = now()
  where group_id = p_group_id
    and user_id = v_uid;
end;
$$;

create or replace function public.calendar_transfer_group_owner(
  p_group_id uuid,
  p_new_owner_id uuid
)
returns table (
  success boolean,
  message text
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_owner_id uuid;
begin
  if v_uid is null then
    raise exception '로그인이 필요합니다.';
  end if;

  select g.owner_id
    into v_owner_id
  from public.calendar_groups g
  where g.id = p_group_id;

  if v_owner_id is null then
    raise exception '그룹을 찾을 수 없습니다.';
  end if;

  if v_owner_id <> v_uid then
    raise exception '그룹장만 그룹장을 넘길 수 있습니다.';
  end if;

  if p_new_owner_id = v_uid then
    raise exception '본인에게는 그룹장을 넘길 수 없습니다.';
  end if;

  if not exists (
    select 1
    from public.calendar_group_members m
    where m.group_id = p_group_id
      and m.user_id = p_new_owner_id
      and m.status = 'active'
  ) then
    raise exception '새 그룹장은 현재 그룹 참여자여야 합니다.';
  end if;

  update public.calendar_groups g
  set owner_id = p_new_owner_id,
      updated_at = now()
  where g.id = p_group_id;

  update public.calendar_group_members m
  set role = case
        when m.user_id = p_new_owner_id then 'owner'
        when m.user_id = v_uid then 'member'
        else m.role
      end,
      updated_at = now()
  where m.group_id = p_group_id
    and m.user_id in (v_uid, p_new_owner_id)
    and m.status = 'active';

  return query
  select true, '그룹장을 넘겼습니다.';
end;
$$;

create or replace function public.calendar_delete_group(p_group_id uuid)
returns table (
  success boolean,
  message text
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_owner_id uuid;
begin
  if v_uid is null then
    raise exception '로그인이 필요합니다.';
  end if;

  select g.owner_id
    into v_owner_id
  from public.calendar_groups g
  where g.id = p_group_id;

  if v_owner_id is null then
    raise exception '그룹을 찾을 수 없습니다.';
  end if;

  if v_owner_id <> v_uid then
    raise exception '그룹장만 그룹을 삭제할 수 있습니다.';
  end if;

  delete from public.calendar_group_shared_events e
  where e.group_id = p_group_id;

  delete from public.calendar_group_user_settings s
  where s.group_id = p_group_id;

  delete from public.calendar_group_invites i
  where i.group_id = p_group_id;

  delete from public.calendar_group_members m
  where m.group_id = p_group_id;

  delete from public.calendar_groups g
  where g.id = p_group_id
    and g.owner_id = v_uid;

  return query
  select true, '그룹을 삭제했습니다.';
end;
$$;

grant execute on function public.leave_calendar_group(uuid) to authenticated;
grant execute on function public.calendar_transfer_group_owner(uuid, uuid) to authenticated;
grant execute on function public.calendar_delete_group(uuid) to authenticated;

-- 20260531 회원탈퇴 기능 추가
-- Supabase Edge Function(delete-account)에서 현재 로그인 사용자의 JWT로 호출합니다.

create or replace function public.cleanup_my_account_data()
returns table (
  success boolean,
  message text
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception '로그인이 필요합니다.';
  end if;

  delete from public.calendar_group_shared_events
  where user_id = v_uid;

  delete from public.calendar_group_user_settings
  where user_id = v_uid;

  delete from public.calendar_group_invites
  where inviter_id = v_uid
     or invitee_id = v_uid;

  delete from public.calendar_group_members
  where user_id = v_uid;

  delete from public.calendar_groups
  where owner_id = v_uid;

  delete from public.user_notifications
  where recipient_user_id = v_uid
     or actor_user_id = v_uid;

  delete from public.user_push_subscriptions
  where user_id = v_uid;

  delete from public.user_notification_preferences
  where user_id = v_uid;

  delete from public.event_calendar_todos
  where user_id = v_uid;

  delete from public.event_calendar_categories
  where user_id = v_uid;

  delete from public.work_calendar_todos
  where user_id = v_uid;

  delete from public.work_calendar_categories
  where user_id = v_uid;

  delete from public.study_calendar_todos
  where user_id = v_uid;

  delete from public.study_calendar_categories
  where user_id = v_uid;

  delete from public.user_emoticons
  where user_id = v_uid;

  delete from public.user_store_items
  where user_id = v_uid;

  delete from public.user_character_skins
  where user_id = v_uid;

  delete from public.user_characters
  where user_id = v_uid;

  delete from public.pickle_ledger
  where user_id = v_uid;

  delete from public.post_reactions
  where user_id = v_uid;

  delete from public.post_comments
  where author_id = v_uid;

  delete from public.posts
  where author_id = v_uid;

  delete from public.profiles
  where id = v_uid;

  return query
  select true, '계정 데이터가 정리되었습니다.';
end;
$$;

revoke all on function public.cleanup_my_account_data() from public;
revoke all on function public.cleanup_my_account_data() from anon;
grant execute on function public.cleanup_my_account_data() to authenticated;

