-- 2026-06-10 그룹 캘린더 우리일정 전용 행 표시를 위한 get_group_calendar_view 반환값 보강
drop function if exists public.get_group_calendar_view(uuid, text, date, date);

create or replace function public.get_group_calendar_view(
  p_group_id uuid,
  p_calendar_type text,
  p_start_date date,
  p_end_date date
)
returns table (
  id uuid,
  group_id uuid,
  user_id uuid,
  user_nickname text,
  calendar_type text,
  source_event_id text,
  event_date date,
  event_type text,
  title text,
  memo text,
  color text,
  payload jsonb,
  backed_up_at timestamptz,
  shared_group_id uuid,
  shared_origin_todo_id uuid,
  shared_origin_user_id uuid,
  shared_created_by uuid,
  is_shared_copy boolean
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_allowed boolean := false;
begin
  if not public.is_calendar_group_member(p_group_id, auth.uid()) then
    raise exception '그룹 멤버만 볼 수 있습니다.';
  end if;

  select case p_calendar_type
    when 'study' then cg.allow_study
    when 'work' then cg.allow_work
    when 'event' then cg.allow_event
    else false
  end
    into v_allowed
  from public.calendar_groups cg
  where cg.id = p_group_id;

  if not coalesce(v_allowed, false) then
    return;
  end if;

  return query
  select
    e.id,
    e.group_id,
    e.user_id,
    coalesce(nullif(trim(p.nickname), ''), '회원') as user_nickname,
    e.calendar_type,
    e.source_event_id,
    e.event_date,
    e.event_type,
    e.title,
    e.memo,
    e.color,
    e.payload,
    e.backed_up_at,
    coalesce(st.shared_group_id, wt.shared_group_id, et.shared_group_id) as shared_group_id,
    coalesce(st.shared_origin_todo_id, wt.shared_origin_todo_id, et.shared_origin_todo_id) as shared_origin_todo_id,
    coalesce(st.shared_origin_user_id, wt.shared_origin_user_id, et.shared_origin_user_id) as shared_origin_user_id,
    coalesce(st.shared_created_by, wt.shared_created_by, et.shared_created_by) as shared_created_by,
    coalesce(st.is_shared_copy, wt.is_shared_copy, et.is_shared_copy, false) as is_shared_copy
  from public.calendar_group_shared_events e
  join public.calendar_group_members m
    on m.group_id = e.group_id
   and m.user_id = e.user_id
   and m.status = 'active'
  left join public.profiles p on p.id = e.user_id
  left join public.study_calendar_todos st
    on p_calendar_type = 'study'
   and st.id = case
     when e.source_event_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       then e.source_event_id::uuid
     else null
   end
  left join public.work_calendar_todos wt
    on p_calendar_type = 'work'
   and wt.id = case
     when e.source_event_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       then e.source_event_id::uuid
     else null
   end
  left join public.event_calendar_todos et
    on p_calendar_type = 'event'
   and et.id = case
     when e.source_event_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       then e.source_event_id::uuid
     else null
   end
  where e.group_id = p_group_id
    and e.calendar_type = p_calendar_type
    and e.event_date between p_start_date and p_end_date
  order by e.event_date, coalesce(nullif(trim(p.nickname), ''), '회원'), e.created_at;
end;
$$;

grant execute on function public.get_group_calendar_view(uuid, text, date, date) to authenticated;

-- =========================================
-- 2026-06-10 캘린더 그룹 소개글 컬럼 추가
-- =========================================

alter table public.calendar_groups
  add column if not exists description text;

drop function if exists public.create_calendar_group(text, text, boolean, boolean, boolean, text, text, boolean);

create or replace function public.create_calendar_group(
  p_name text,
  p_description text default '',
  p_color text default '#f54260',
  p_allow_study boolean default true,
  p_allow_work boolean default true,
  p_allow_event boolean default false,
  p_visibility text default 'public',
  p_password text default null,
  p_is_hidden boolean default false
)
returns uuid
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  v_uid uuid := auth.uid();
  v_group_id uuid;
  v_visibility text := case when p_visibility = 'private' then 'private' else 'public' end;
begin
  if v_uid is null then
    raise exception '로그인이 필요합니다.';
  end if;

  if not (coalesce(p_allow_study, false) or coalesce(p_allow_work, false) or coalesce(p_allow_event, false)) then
    raise exception '연동할 캘린더를 하나 이상 선택해야 합니다.';
  end if;

  insert into public.calendar_groups (
    owner_id,
    name,
    description,
    color,
    visibility,
    password_hash,
    is_hidden,
    allow_study,
    allow_work,
    allow_event
  )
  values (
    v_uid,
    trim(p_name),
    nullif(left(trim(coalesce(p_description, '')), 100), ''),
    case when coalesce(p_color, '') ~ '^#[0-9A-Fa-f]{6}$' then lower(p_color) else '#f54260' end,
    v_visibility,
    case
      when v_visibility = 'private' and nullif(p_password, '') is not null
        then crypt(p_password, gen_salt('bf'))
      else null
    end,
    coalesce(p_is_hidden, false),
    coalesce(p_allow_study, false),
    coalesce(p_allow_work, false),
    coalesce(p_allow_event, false)
  )
  returning id into v_group_id;

  insert into public.calendar_group_members (group_id, user_id, role, status)
  values (v_group_id, v_uid, 'owner', 'active');

  return v_group_id;
end;
$$;

drop function if exists public.update_calendar_group(uuid, text, text, boolean, boolean, boolean, text, text, boolean);

create or replace function public.update_calendar_group(
  p_group_id uuid,
  p_name text,
  p_description text,
  p_color text,
  p_allow_study boolean,
  p_allow_work boolean,
  p_allow_event boolean,
  p_visibility text,
  p_password text default null,
  p_is_hidden boolean default false
)
returns void
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  v_visibility text := case when p_visibility = 'private' then 'private' else 'public' end;
begin
  if not public.is_calendar_group_manager(p_group_id, auth.uid()) then
    raise exception '그룹 관리자만 수정할 수 있습니다.';
  end if;

  if not (coalesce(p_allow_study, false) or coalesce(p_allow_work, false) or coalesce(p_allow_event, false)) then
    raise exception '연동할 캘린더를 하나 이상 선택해야 합니다.';
  end if;

  update public.calendar_groups
  set name = trim(p_name),
      description = nullif(left(trim(coalesce(p_description, '')), 100), ''),
      color = case when coalesce(p_color, '') ~ '^#[0-9A-Fa-f]{6}$' then lower(p_color) else color end,
      allow_study = coalesce(p_allow_study, false),
      allow_work = coalesce(p_allow_work, false),
      allow_event = coalesce(p_allow_event, false),
      visibility = v_visibility,
      password_hash = case
        when v_visibility = 'private' and nullif(p_password, '') is not null
          then crypt(p_password, gen_salt('bf'))
        when v_visibility = 'public' then null
        else password_hash
      end,
      is_hidden = coalesce(p_is_hidden, false),
      updated_at = now()
  where id = p_group_id;
end;
$$;

drop function if exists public.get_my_calendar_groups();

create or replace function public.get_my_calendar_groups()
returns table (
  id uuid,
  name text,
  description text,
  color text,
  visibility text,
  is_hidden boolean,
  allow_study boolean,
  allow_work boolean,
  allow_event boolean,
  role text,
  member_count bigint,
  can_manage boolean,
  joined_at timestamptz
)
language sql
security definer
set search_path = public
as $$
  select
    g.id,
    g.name,
    g.description,
    g.color,
    g.visibility,
    g.is_hidden,
    g.allow_study,
    g.allow_work,
    g.allow_event,
    m.role,
    (
      select count(*)
      from public.calendar_group_members cm
      where cm.group_id = g.id
        and cm.status = 'active'
    ) as member_count,
    m.role in ('owner', 'admin') as can_manage,
    m.joined_at
  from public.calendar_group_members m
  join public.calendar_groups g on g.id = m.group_id
  where m.user_id = auth.uid()
    and m.status = 'active'
  order by m.joined_at desc;
$$;

drop function if exists public.get_visible_calendar_groups(boolean);

create or replace function public.get_visible_calendar_groups(p_include_hidden boolean default false)
returns table (
  id uuid,
  name text,
  description text,
  color text,
  visibility text,
  is_hidden boolean,
  allow_study boolean,
  allow_work boolean,
  allow_event boolean,
  role text,
  member_count bigint,
  can_manage boolean,
  joined_at timestamptz
)
language sql
security definer
set search_path = public
as $$
  select
    g.id,
    g.name,
    g.description,
    g.color,
    g.visibility,
    g.is_hidden,
    g.allow_study,
    g.allow_work,
    g.allow_event,
    coalesce(m.role, '') as role,
    (
      select count(*)
      from public.calendar_group_members cm
      where cm.group_id = g.id
        and cm.status = 'active'
    ) as member_count,
    coalesce(m.role in ('owner', 'admin'), false) as can_manage,
    m.joined_at
  from public.calendar_groups g
  left join public.calendar_group_members m
    on m.group_id = g.id
   and m.user_id = auth.uid()
   and m.status = 'active'
  where g.visibility in ('public', 'private')
    and (p_include_hidden = true or g.is_hidden = false)
  order by g.created_at desc;
$$;

grant execute on function public.create_calendar_group(text, text, text, boolean, boolean, boolean, text, text, boolean) to authenticated;
grant execute on function public.update_calendar_group(uuid, text, text, text, boolean, boolean, boolean, text, text, boolean) to authenticated;
grant execute on function public.get_my_calendar_groups() to authenticated;
grant execute on function public.get_visible_calendar_groups(boolean) to authenticated;

-- 2026-06-10 캘린더 앱 홈화면 위젯용 개인 캘린더 조회 RPC
-- 위젯에는 내 캘린더 일정만 표시하고, 그룹/공유 개인 일정 복사본은 제외한다.
create or replace function public.get_my_calendar_widget_items(
  p_start_date date default current_date,
  p_end_date date default current_date + 30
)
returns table (
  calendar_type text,
  item_id uuid,
  item_date date,
  category_name text,
  category_color text,
  title text,
  memo text,
  event_time time,
  sort_order integer,
  created_at timestamptz
)
language sql
stable
security invoker
set search_path = public
as $$
  select
    'study'::text as calendar_type,
    t.id as item_id,
    t.todo_date as item_date,
    coalesce(c.name, t.todo_type, '기타') as category_name,
    coalesce(c.color, '') as category_color,
    t.todo_text as title,
    coalesce(t.memo, '') as memo,
    null::time as event_time,
    coalesce(c.sort_order, 100) as sort_order,
    t.created_at
  from public.study_calendar_todos t
  left join public.study_calendar_categories c
    on c.id = t.category_id
   and c.user_id = t.user_id
  where t.user_id = auth.uid()
    and t.todo_date between p_start_date and p_end_date
    and t.shared_group_id is null
    and t.shared_origin_todo_id is null
    and coalesce(t.is_shared_copy, false) = false

  union all

  select
    'work'::text as calendar_type,
    t.id as item_id,
    t.work_date as item_date,
    coalesce(c.name, t.work_type, '기타') as category_name,
    coalesce(c.color, '') as category_color,
    t.work_text as title,
    coalesce(t.memo, '') as memo,
    null::time as event_time,
    coalesce(c.sort_order, 100) as sort_order,
    t.created_at
  from public.work_calendar_todos t
  left join public.work_calendar_categories c
    on c.id = t.category_id
   and c.user_id = t.user_id
  where t.user_id = auth.uid()
    and t.work_date between p_start_date and p_end_date
    and t.shared_group_id is null
    and t.shared_origin_todo_id is null
    and coalesce(t.is_shared_copy, false) = false

  union all

  select
    'event'::text as calendar_type,
    t.id as item_id,
    t.event_date as item_date,
    coalesce(c.name, t.event_type, '기타') as category_name,
    coalesce(c.color, '') as category_color,
    t.event_text as title,
    coalesce(t.memo, '') as memo,
    t.event_time as event_time,
    coalesce(c.sort_order, 100) as sort_order,
    t.created_at
  from public.event_calendar_todos t
  left join public.event_calendar_categories c
    on c.id = t.category_id
   and c.user_id = t.user_id
  where t.user_id = auth.uid()
    and t.event_date between p_start_date and p_end_date
    and t.shared_group_id is null
    and t.shared_origin_todo_id is null
    and coalesce(t.is_shared_copy, false) = false

  order by
    item_date asc,
    calendar_type asc,
    event_time asc nulls last,
    sort_order asc,
    created_at asc;
$$;

revoke all on function public.get_my_calendar_widget_items(date, date) from public;
