-- 마이그레이션 중 기존 트리거가 auth.uid() null로 막지 않도록 잠시 해제한다.
drop trigger if exists trg_common_group_event_write on public.calendar_common_group_events;

-- 1차 구현으로 이미 저장된 일정은 데이터 손실 없이 공개 완료 상태로 이관한다.
-- 기존 1차 일정의 카테고리 ID를 이름/slug/색상 스냅샷으로 보강한다.
update public.calendar_common_group_events e
set payload = coalesce(e.payload,'{}'::jsonb) || jsonb_build_object(
  'categoryName',c.name,'categorySlug',c.slug,'categoryColor',c.color
)
from public.work_calendar_categories c
where e.calendar_type='work' and c.id::text=e.payload->>'categoryId'
  and not (e.payload ? 'categoryName');

update public.calendar_common_group_events e
set payload = coalesce(e.payload,'{}'::jsonb) || jsonb_build_object(
  'categoryName',c.name,'categorySlug',c.slug,'categoryColor',c.color
)
from public.study_calendar_categories c
where e.calendar_type='study' and c.id::text=e.payload->>'categoryId'
  and not (e.payload ? 'categoryName');

update public.calendar_common_group_events e
set payload = coalesce(e.payload,'{}'::jsonb) || jsonb_build_object(
  'categoryName',c.name,'categorySlug',c.slug,'categoryColor',c.color
)
from public.event_calendar_categories c
where e.calendar_type='event' and c.id::text=e.payload->>'categoryId'
  and not (e.payload ? 'categoryName');


update public.calendar_common_group_events
set published_date_key = coalesce(published_date_key, date_key),
    published_schedule_type = coalesce(published_schedule_type, schedule_type),
    published_title = coalesce(published_title, title),
    published_memo = coalesce(published_memo, memo),
    published_color = coalesce(published_color, color),
    published_payload = coalesce(published_payload, payload, '{}'::jsonb),
    published_is_deleted = false,
    published_at = coalesce(published_at, updated_at, created_at, now())
where published_at is null;

-- 마이그레이션 데이터 보강 후 쓰기 검증 트리거를 다시 연결한다.
drop trigger if exists trg_common_group_event_write on public.calendar_common_group_events;
create trigger trg_common_group_event_write before insert or update on public.calendar_common_group_events
for each row execute function public.handle_common_group_event_write();

drop policy if exists "common_group_events_select_member" on public.calendar_common_group_events;
drop policy if exists "common_group_events_select_owner" on public.calendar_common_group_events;
create policy "common_group_events_select_owner"
on public.calendar_common_group_events for select to authenticated
using (exists (
  select 1 from public.calendar_groups g
  where g.id = group_id and g.owner_id = auth.uid() and g.is_common_calendar
));

create or replace function public.get_common_group_calendar_events(
  p_group_id uuid,
  p_calendar_type text
)
returns table (
  id uuid, group_id uuid, calendar_type text, date_key date,
  schedule_type text, title text, memo text, color text, payload jsonb,
  created_by uuid, updated_by uuid, created_at timestamptz, updated_at timestamptz
)
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_is_owner boolean;
begin
  if v_uid is null then raise exception '로그인이 필요합니다.'; end if;
  if not public.is_calendar_group_member(p_group_id, v_uid) then
    raise exception '그룹 참여자만 공통 캘린더를 볼 수 있습니다.';
  end if;
  select exists(select 1 from public.calendar_groups g where g.id = p_group_id and g.owner_id = v_uid)
    into v_is_owner;

  if v_is_owner then
    return query
    select e.id,e.group_id,e.calendar_type,e.date_key,e.schedule_type,e.title,e.memo,e.color,e.payload,
           e.created_by,e.updated_by,e.created_at,e.updated_at
    from public.calendar_common_group_events e
    where e.group_id=p_group_id and e.calendar_type=p_calendar_type and not e.is_deleted
    order by e.date_key,e.created_at;
  else
    return query
    select e.id,e.group_id,e.calendar_type,e.published_date_key,e.published_schedule_type,
           e.published_title,e.published_memo,e.published_color,coalesce(e.published_payload,'{}'::jsonb),
           e.created_by,e.updated_by,e.created_at,e.published_at
    from public.calendar_common_group_events e
    where e.group_id=p_group_id and e.calendar_type=p_calendar_type
      and e.published_at is not null and not e.published_is_deleted
    order by e.published_date_key,e.created_at;
  end if;
end; $$;

create or replace function public.common_group_calendar_has_changes(
  p_group_id uuid,
  p_calendar_type text
)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  if not exists(select 1 from public.calendar_groups g where g.id=p_group_id and g.owner_id=auth.uid() and g.is_common_calendar) then
    return false;
  end if;
  return exists (
    select 1 from public.calendar_common_group_events e
    where e.group_id=p_group_id and e.calendar_type=p_calendar_type and (
      e.published_at is null or e.is_deleted is distinct from e.published_is_deleted or
      e.date_key is distinct from e.published_date_key or
      e.schedule_type is distinct from e.published_schedule_type or
      e.title is distinct from e.published_title or
      e.memo is distinct from e.published_memo or
      e.color is distinct from e.published_color or
      coalesce(e.payload,'{}'::jsonb) is distinct from coalesce(e.published_payload,'{}'::jsonb)
    )
  );
end; $$;

create or replace function public.publish_common_group_calendar(
  p_group_id uuid,
  p_calendar_type text
)
returns table (event_count bigint, backed_up_at timestamptz)
language plpgsql security definer set search_path = public as $$
declare v_now timestamptz := now(); v_count bigint;
begin
  if not exists(select 1 from public.calendar_groups g where g.id=p_group_id and g.owner_id=auth.uid() and g.is_common_calendar) then
    raise exception '공통 그룹 캘린더는 그룹장만 백업할 수 있습니다.';
  end if;
  update public.calendar_common_group_events e
  set published_date_key=e.date_key,
      published_schedule_type=e.schedule_type,
      published_title=e.title,
      published_memo=e.memo,
      published_color=e.color,
      published_payload=coalesce(e.payload,'{}'::jsonb),
      published_is_deleted=e.is_deleted,
      published_at=v_now
  where e.group_id=p_group_id and e.calendar_type=p_calendar_type;
  select count(*) into v_count from public.calendar_common_group_events e
  where e.group_id=p_group_id and e.calendar_type=p_calendar_type and not e.published_is_deleted;
  return query select v_count,v_now;
end; $$;

revoke all on function public.get_common_group_calendar_events(uuid,text) from public, anon;
revoke all on function public.common_group_calendar_has_changes(uuid,text) from public, anon;
revoke all on function public.publish_common_group_calendar(uuid,text) from public, anon;
grant execute on function public.get_common_group_calendar_events(uuid,text) to authenticated;
grant execute on function public.common_group_calendar_has_changes(uuid,text) to authenticated;
grant execute on function public.publish_common_group_calendar(uuid,text) to authenticated;

-- 20260705 공통 그룹 캘린더 위젯: published 일정 전용 조회
create or replace function public.get_common_group_calendar_widget_events(p_group_id uuid, p_calendar_type text)
returns table (id uuid, group_id uuid, group_name text, calendar_type text, date_key date, schedule_type text, title text, memo text, color text, payload jsonb, created_at timestamptz, updated_at timestamptz)
language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception '로그인이 필요합니다.'; end if;
  if p_calendar_type not in ('study', 'work', 'event') then raise exception '지원하지 않는 캘린더 종류입니다.'; end if;
  if not exists (select 1 from public.calendar_groups g where g.id=p_group_id and g.is_common_calendar and case p_calendar_type when 'study' then g.allow_study when 'work' then g.allow_work else g.allow_event end and public.is_calendar_group_member(g.id,v_uid)) then raise exception '사용 가능한 공통 그룹 캘린더가 아닙니다.'; end if;
  return query select e.id,e.group_id,g.name,e.calendar_type,e.published_date_key,e.published_schedule_type,e.published_title,e.published_memo,e.published_color,coalesce(e.published_payload,'{}'::jsonb),e.created_at,e.published_at
  from public.calendar_common_group_events e join public.calendar_groups g on g.id=e.group_id
  where e.group_id=p_group_id and e.calendar_type=p_calendar_type and e.published_at is not null and not e.published_is_deleted order by e.published_date_key,e.created_at;
end; $$;
revoke all on function public.get_common_group_calendar_widget_events(uuid,text) from public, anon;
grant execute on function public.get_common_group_calendar_widget_events(uuid,text) to authenticated;

-- 20260705 그룹 캘린더 백업 복사/개인 캘린더 붙여넣기

update public.calendar_groups
set is_common_calendar = false
where is_common_calendar is true;

create or replace function public.get_group_calendar_copy_sources(
  p_group_id uuid,
  p_calendar_type text
)
returns table (
  source_user_id uuid,
  nickname text,
  avatar_url text,
  backup_count integer,
  last_backed_up_at timestamptz
)
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() is null then raise exception '로그인이 필요해요.'; end if;
  if p_calendar_type not in ('study', 'work', 'event') then raise exception '지원하지 않는 캘린더 타입이에요.'; end if;
  if not exists (
    select 1 from public.calendar_group_members m
    where m.group_id = p_group_id and m.user_id = auth.uid() and m.status = 'active'
  ) then raise exception '이 그룹의 참여자가 아니에요.'; end if;
  if not exists (
    select 1 from public.calendar_groups g
    where g.id = p_group_id
      and case p_calendar_type when 'study' then g.allow_study when 'work' then g.allow_work else g.allow_event end
  ) then raise exception '이 그룹에서 사용할 수 없는 캘린더 타입이에요.'; end if;

  return query
  select e.user_id, coalesce(p.nickname, '알 수 없는 사용자'), null::text,
         count(*)::integer, max(e.backed_up_at)
  from public.calendar_group_shared_events e
  join public.calendar_group_members m
    on m.group_id = e.group_id and m.user_id = e.user_id and m.status = 'active'
  left join public.profiles p on p.id = e.user_id
  where e.group_id = p_group_id and e.calendar_type = p_calendar_type
  group by e.user_id, p.nickname
  order by max(e.backed_up_at) desc, coalesce(p.nickname, '알 수 없는 사용자');
end;
$$;

create or replace function public.paste_group_calendar_backup_to_my_calendar(
  p_group_id uuid,
  p_calendar_type text,
  p_source_user_id uuid
)
returns table (success boolean, message text, inserted_count integer)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid := auth.uid();
  v_count integer := 0;
begin
  if v_user_id is null then raise exception '로그인이 필요해요.'; end if;
  if p_calendar_type not in ('study', 'work', 'event') then raise exception '지원하지 않는 캘린더 타입이에요.'; end if;
  if not exists (
    select 1 from public.calendar_group_members m
    where m.group_id = p_group_id and m.user_id = v_user_id and m.status = 'active'
  ) then raise exception '이 그룹의 참여자가 아니에요.'; end if;
  if not exists (
    select 1 from public.calendar_groups g
    where g.id = p_group_id
      and case p_calendar_type when 'study' then g.allow_study when 'work' then g.allow_work else g.allow_event end
  ) then raise exception '이 그룹에서 사용할 수 없는 캘린더 타입이에요.'; end if;
  if not exists (
    select 1 from public.calendar_group_members m
    where m.group_id = p_group_id and m.user_id = p_source_user_id and m.status = 'active'
  ) then raise exception '복사할 그룹원이 현재 참여 중이 아니에요.'; end if;
  if not exists (
    select 1 from public.calendar_group_shared_events e
    where e.group_id = p_group_id and e.user_id = p_source_user_id and e.calendar_type = p_calendar_type
  ) then raise exception '복사할 백업 일정이 없어요.'; end if;

  if p_calendar_type = 'study' then
    delete from public.study_calendar_todos where user_id = v_user_id;
    insert into public.study_calendar_categories (user_id, name, slug, color, is_default, sort_order)
    select distinct v_user_id, left(coalesce(nullif(e.payload->>'categoryName', ''), e.title), 20),
           coalesce(nullif(e.event_type, ''), 'etc'),
           case when coalesce(e.color, '') ~ '^#[0-9A-Fa-f]{6}$' then e.color else '#eaffd7' end,
           false, 100
    from public.calendar_group_shared_events e
    where e.group_id = p_group_id and e.user_id = p_source_user_id and e.calendar_type = 'study'
    on conflict (user_id, slug) do nothing;
    insert into public.study_calendar_todos (user_id, todo_date, todo_type, category_id, todo_text, memo, is_done)
    select v_user_id, e.event_date,
           coalesce(nullif(e.event_type, ''), 'etc'),
           (select c.id from public.study_calendar_categories c where c.user_id = v_user_id and c.slug = coalesce(nullif(e.event_type, ''), 'etc') limit 1),
           e.title, coalesce(e.memo, ''), coalesce((e.payload->>'isDone')::boolean, false)
    from public.calendar_group_shared_events e
    where e.group_id = p_group_id and e.user_id = p_source_user_id and e.calendar_type = 'study'
    order by e.event_date, e.created_at;
  elsif p_calendar_type = 'work' then
    delete from public.work_calendar_todos where user_id = v_user_id;
    insert into public.work_calendar_categories (user_id, name, slug, color, is_default, sort_order)
    select distinct v_user_id, left(coalesce(nullif(e.payload->>'categoryName', ''), e.title), 20),
           coalesce(nullif(e.event_type, ''), 'workday'),
           case when coalesce(e.color, '') ~ '^#[0-9A-Fa-f]{6}$' then e.color else '#e7f6ff' end,
           false, 100
    from public.calendar_group_shared_events e
    where e.group_id = p_group_id and e.user_id = p_source_user_id and e.calendar_type = 'work'
    on conflict (user_id, slug) do nothing;
    insert into public.work_calendar_todos (user_id, work_date, work_type, category_id, work_text, memo, is_done)
    select v_user_id, e.event_date, coalesce(nullif(e.event_type, ''), 'workday'),
           (select c.id from public.work_calendar_categories c where c.user_id = v_user_id and c.slug = coalesce(nullif(e.event_type, ''), 'workday') limit 1),
           coalesce(nullif(e.payload->>'workText', ''), e.title), coalesce(e.memo, ''),
           coalesce((e.payload->>'isDone')::boolean, false)
    from public.calendar_group_shared_events e
    where e.group_id = p_group_id and e.user_id = p_source_user_id and e.calendar_type = 'work'
    order by e.event_date, e.created_at;
  else
    delete from public.event_calendar_todos where user_id = v_user_id;
    insert into public.event_calendar_categories (user_id, name, slug, color, is_default, sort_order)
    select distinct v_user_id, left(coalesce(nullif(e.payload->>'categoryName', ''), e.title), 20),
           coalesce(nullif(e.event_type, ''), 'appointment'),
           case when coalesce(e.color, '') ~ '^#[0-9A-Fa-f]{6}$' then e.color else '#ffe0ef' end,
           false, 100
    from public.calendar_group_shared_events e
    where e.group_id = p_group_id and e.user_id = p_source_user_id and e.calendar_type = 'event'
    on conflict (user_id, slug) do nothing;
    insert into public.event_calendar_todos (
      user_id, event_date, event_type, category_id, event_text, memo,
      event_time, event_end_time, is_done
    )
    select v_user_id, e.event_date, coalesce(nullif(e.event_type, ''), 'appointment'),
           (select c.id from public.event_calendar_categories c where c.user_id = v_user_id and c.slug = coalesce(nullif(e.event_type, ''), 'appointment') limit 1),
           e.title, coalesce(e.memo, ''),
           coalesce(nullif(e.payload->>'eventTime', '')::time, '00:00'::time),
           nullif(e.payload->>'eventEndTime', '')::time,
           coalesce((e.payload->>'isDone')::boolean, false)
    from public.calendar_group_shared_events e
    where e.group_id = p_group_id and e.user_id = p_source_user_id and e.calendar_type = 'event'
    order by e.event_date, e.created_at;
  end if;

  get diagnostics v_count = row_count;
  return query select true, '캘린더 붙여넣기를 완료했어요.'::text, v_count;
end;
$$;

revoke all on function public.get_group_calendar_copy_sources(uuid, text) from public, anon;
revoke all on function public.paste_group_calendar_backup_to_my_calendar(uuid, text, uuid) from public, anon;
grant execute on function public.get_group_calendar_copy_sources(uuid, text) to authenticated;
grant execute on function public.paste_group_calendar_backup_to_my_calendar(uuid, text, uuid) to authenticated;

-- 20260706 그룹 캘린더 백업 날짜 범위 복사/붙여넣기

drop function if exists public.paste_group_calendar_backup_to_my_calendar(uuid, text, uuid);

create or replace function public.paste_group_calendar_backup_to_my_calendar(
  p_group_id uuid,
  p_calendar_type text,
  p_source_user_id uuid,
  p_start_date date default null,
  p_end_date date default null
)
returns table (success boolean, message text, inserted_count integer)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid := auth.uid();
  v_count integer := 0;
  v_is_range boolean := p_start_date is not null and p_end_date is not null;
begin
  if v_user_id is null then raise exception '로그인이 필요해요.'; end if;
  if p_calendar_type not in ('study', 'work', 'event') then raise exception '지원하지 않는 캘린더 타입이에요.'; end if;
  if (p_start_date is null) <> (p_end_date is null) then raise exception '시작일과 종료일을 모두 입력해줘.'; end if;
  if v_is_range and p_start_date > p_end_date then raise exception '시작일은 종료일보다 늦을 수 없어요.'; end if;
  if not exists (
    select 1 from public.calendar_group_members m
    where m.group_id = p_group_id and m.user_id = v_user_id and m.status = 'active'
  ) then raise exception '이 그룹의 참여자가 아니에요.'; end if;
  if not exists (
    select 1 from public.calendar_groups g
    where g.id = p_group_id
      and case p_calendar_type when 'study' then g.allow_study when 'work' then g.allow_work else g.allow_event end
  ) then raise exception '이 그룹에서 사용할 수 없는 캘린더 타입이에요.'; end if;
  if not exists (
    select 1 from public.calendar_group_members m
    where m.group_id = p_group_id and m.user_id = p_source_user_id and m.status = 'active'
  ) then raise exception '복사할 그룹원이 현재 참여 중이 아니에요.'; end if;
  if not exists (
    select 1 from public.calendar_group_shared_events e
    where e.group_id = p_group_id
      and e.user_id = p_source_user_id
      and e.calendar_type = p_calendar_type
      and (not v_is_range or e.event_date between p_start_date and p_end_date)
  ) then
    if v_is_range then raise exception '해당 날짜 범위에 복사할 일정이 없어요.';
    else raise exception '복사할 백업 일정이 없어요.';
    end if;
  end if;

  if p_calendar_type = 'study' then
    if v_is_range then
      delete from public.study_calendar_todos
      where user_id = v_user_id and todo_date between p_start_date and p_end_date;
    else
      delete from public.study_calendar_todos where user_id = v_user_id;
    end if;
    insert into public.study_calendar_categories (user_id, name, slug, color, is_default, sort_order)
    select distinct v_user_id, left(coalesce(nullif(e.payload->>'categoryName', ''), e.title), 20),
           coalesce(nullif(e.event_type, ''), 'etc'),
           case when coalesce(e.color, '') ~ '^#[0-9A-Fa-f]{6}$' then e.color else '#eaffd7' end,
           false, 100
    from public.calendar_group_shared_events e
    where e.group_id = p_group_id and e.user_id = p_source_user_id and e.calendar_type = 'study'
      and (not v_is_range or e.event_date between p_start_date and p_end_date)
    on conflict (user_id, slug) do nothing;
    insert into public.study_calendar_todos (user_id, todo_date, todo_type, category_id, todo_text, memo, is_done)
    select v_user_id, e.event_date, coalesce(nullif(e.event_type, ''), 'etc'),
           (select c.id from public.study_calendar_categories c where c.user_id = v_user_id and c.slug = coalesce(nullif(e.event_type, ''), 'etc') limit 1),
           e.title, coalesce(e.memo, ''), coalesce((e.payload->>'isDone')::boolean, false)
    from public.calendar_group_shared_events e
    where e.group_id = p_group_id and e.user_id = p_source_user_id and e.calendar_type = 'study'
      and (not v_is_range or e.event_date between p_start_date and p_end_date)
    order by e.event_date, e.created_at;
  elsif p_calendar_type = 'work' then
    if v_is_range then
      delete from public.work_calendar_todos
      where user_id = v_user_id and work_date between p_start_date and p_end_date;
    else
      delete from public.work_calendar_todos where user_id = v_user_id;
    end if;
    insert into public.work_calendar_categories (user_id, name, slug, color, is_default, sort_order)
    select distinct v_user_id, left(coalesce(nullif(e.payload->>'categoryName', ''), e.title), 20),
           coalesce(nullif(e.event_type, ''), 'workday'),
           case when coalesce(e.color, '') ~ '^#[0-9A-Fa-f]{6}$' then e.color else '#e7f6ff' end,
           false, 100
    from public.calendar_group_shared_events e
    where e.group_id = p_group_id and e.user_id = p_source_user_id and e.calendar_type = 'work'
      and (not v_is_range or e.event_date between p_start_date and p_end_date)
    on conflict (user_id, slug) do nothing;
    insert into public.work_calendar_todos (user_id, work_date, work_type, category_id, work_text, memo, is_done)
    select v_user_id, e.event_date, coalesce(nullif(e.event_type, ''), 'workday'),
           (select c.id from public.work_calendar_categories c where c.user_id = v_user_id and c.slug = coalesce(nullif(e.event_type, ''), 'workday') limit 1),
           coalesce(nullif(e.payload->>'workText', ''), e.title), coalesce(e.memo, ''),
           coalesce((e.payload->>'isDone')::boolean, false)
    from public.calendar_group_shared_events e
    where e.group_id = p_group_id and e.user_id = p_source_user_id and e.calendar_type = 'work'
      and (not v_is_range or e.event_date between p_start_date and p_end_date)
    order by e.event_date, e.created_at;
  else
    if v_is_range then
      delete from public.event_calendar_todos
      where user_id = v_user_id and event_date between p_start_date and p_end_date;
    else
      delete from public.event_calendar_todos where user_id = v_user_id;
    end if;
    insert into public.event_calendar_categories (user_id, name, slug, color, is_default, sort_order)
    select distinct v_user_id, left(coalesce(nullif(e.payload->>'categoryName', ''), e.title), 20),
           coalesce(nullif(e.event_type, ''), 'appointment'),
           case when coalesce(e.color, '') ~ '^#[0-9A-Fa-f]{6}$' then e.color else '#ffe0ef' end,
           false, 100
    from public.calendar_group_shared_events e
    where e.group_id = p_group_id and e.user_id = p_source_user_id and e.calendar_type = 'event'
      and (not v_is_range or e.event_date between p_start_date and p_end_date)
    on conflict (user_id, slug) do nothing;
    insert into public.event_calendar_todos (
      user_id, event_date, event_type, category_id, event_text, memo,
      event_time, event_end_time, is_done
    )
    select v_user_id, e.event_date, coalesce(nullif(e.event_type, ''), 'appointment'),
           (select c.id from public.event_calendar_categories c where c.user_id = v_user_id and c.slug = coalesce(nullif(e.event_type, ''), 'appointment') limit 1),
           e.title, coalesce(e.memo, ''),
           coalesce(nullif(e.payload->>'eventTime', '')::time, '00:00'::time),
           nullif(e.payload->>'eventEndTime', '')::time,
           coalesce((e.payload->>'isDone')::boolean, false)
    from public.calendar_group_shared_events e
    where e.group_id = p_group_id and e.user_id = p_source_user_id and e.calendar_type = 'event'
      and (not v_is_range or e.event_date between p_start_date and p_end_date)
    order by e.event_date, e.created_at;
  end if;

  get diagnostics v_count = row_count;
  return query select true,
    case when v_is_range then '선택한 날짜 범위 붙여넣기를 완료했어요.' else '캘린더 붙여넣기를 완료했어요.' end,
    v_count;
end;
$$;

revoke all on function public.paste_group_calendar_backup_to_my_calendar(uuid, text, uuid, date, date) from public, anon;
grant execute on function public.paste_group_calendar_backup_to_my_calendar(uuid, text, uuid, date, date) to authenticated;

-- =========================================================
-- 사이트 회원 수 / 금일 방문 수 통계
-- =========================================================

create table if not exists public.site_daily_visits (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  visit_date date not null,
  created_at timestamptz not null default now(),
  constraint site_daily_visits_user_date_key unique (user_id, visit_date)
);

alter table public.site_daily_visits enable row level security;
revoke all on table public.site_daily_visits from public, anon, authenticated;

create or replace function public.record_today_site_visit()
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    return false;
  end if;

  insert into public.site_daily_visits (user_id, visit_date)
  values (v_user_id, (now() at time zone 'Asia/Seoul')::date)
  on conflict (user_id, visit_date) do nothing;

  return true;
end;
$$;

create or replace function public.get_site_stats()
returns table (member_count integer, today_visit_count integer)
language sql
stable
security definer
set search_path = ''
as $$
  select
    (select count(*)::integer from auth.users) as member_count,
    (
      select count(*)::integer
      from public.site_daily_visits
      where visit_date = (now() at time zone 'Asia/Seoul')::date
    ) as today_visit_count;
$$;

revoke all on function public.record_today_site_visit() from public, anon;
grant execute on function public.record_today_site_visit() to authenticated;

revoke all on function public.get_site_stats() from public;
grant execute on function public.get_site_stats() to anon, authenticated;

-- =========================================================
-- 비회원 포함 일일 방문자 중복 방지 집계 기능
-- =========================================================

create table if not exists public.site_daily_visits (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references auth.users(id) on delete cascade,
  visitor_key text,
  visit_date date not null,
  created_at timestamptz not null default now()
);

alter table public.site_daily_visits
  add column if not exists visitor_key text;

alter table public.site_daily_visits
  alter column user_id drop not null;

update public.site_daily_visits
set visitor_key = 'user:' || user_id::text
where visitor_key is null
  and user_id is not null;

update public.site_daily_visits
set visitor_key = 'guest:' || id::text
where visitor_key is null;

alter table public.site_daily_visits
  alter column visitor_key set not null;

do $$
begin
  if not exists (
    select 1
    from pg_constraint
    where conname = 'site_daily_visits_visitor_key_format_check'
      and conrelid = 'public.site_daily_visits'::regclass
  ) then
    alter table public.site_daily_visits
      add constraint site_daily_visits_visitor_key_format_check
      check (visitor_key ~ '^(user|guest):[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$');
  end if;
end;
$$;

do $$
begin
  if not exists (
    select 1
    from pg_constraint
    where conname = 'site_daily_visits_visit_date_visitor_key_key'
      and conrelid = 'public.site_daily_visits'::regclass
  ) then
    alter table public.site_daily_visits
      add constraint site_daily_visits_visit_date_visitor_key_key
      unique (visit_date, visitor_key);
  end if;
end;
$$;

alter table public.site_daily_visits enable row level security;
revoke all on table public.site_daily_visits from public, anon, authenticated;

drop function if exists public.record_today_site_visit();

create or replace function public.record_today_site_visit(p_guest_id uuid default null)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := auth.uid();
  v_visit_date date := (now() at time zone 'Asia/Seoul')::date;
  v_user_key text;
  v_guest_key text;
begin
  if p_guest_id is not null then
    v_guest_key := 'guest:' || p_guest_id::text;
  end if;

  if v_user_id is not null then
    v_user_key := 'user:' || v_user_id::text;

    insert into public.site_daily_visits (user_id, visitor_key, visit_date)
    values (v_user_id, v_user_key, v_visit_date)
    on conflict (visit_date, visitor_key) do nothing;

    if v_guest_key is not null then
      delete from public.site_daily_visits
      where visit_date = v_visit_date
        and visitor_key = v_guest_key;
    end if;

    return true;
  end if;

  if v_guest_key is null then
    return false;
  end if;

  insert into public.site_daily_visits (user_id, visitor_key, visit_date)
  values (null, v_guest_key, v_visit_date)
  on conflict (visit_date, visitor_key) do nothing;

  return true;
end;
$$;

create or replace function public.get_site_stats()
returns table (member_count integer, today_visit_count integer)
language sql
stable
security definer
set search_path = ''
as $$
  select
    (select count(*)::integer from auth.users) as member_count,
    (
      select count(*)::integer
      from public.site_daily_visits
      where visit_date = (now() at time zone 'Asia/Seoul')::date
    ) as today_visit_count;
$$;

revoke all on function public.record_today_site_visit(uuid) from public;
grant execute on function public.record_today_site_visit(uuid) to anon, authenticated;

revoke all on function public.get_site_stats() from public;
grant execute on function public.get_site_stats() to anon, authenticated;


-- ============================================================
-- 이벤트 캘린더 기존 일정 종료 날짜 수정 및 기간 식별자 추가
-- 작업일: 2026-07-12
-- 설명: 이벤트 기간 row를 event_range_id로 식별하고 생성/수정을 트랜잭션 처리
-- ============================================================

alter table public.event_calendar_todos
  add column if not exists event_range_id uuid;

create index if not exists event_calendar_todos_user_range_date_idx
  on public.event_calendar_todos (user_id, event_range_id, event_date);

create index if not exists event_calendar_todos_range_date_idx
  on public.event_calendar_todos (event_range_id, event_date)
  where event_range_id is not null;

create or replace function public.create_event_calendar_todo_range(
  p_start_date date,
  p_end_date date,
  p_category_id uuid,
  p_event_text text,
  p_memo text default '',
  p_event_time time default '00:00',
  p_event_end_time time default null
)
returns table (
  id uuid,
  user_id uuid,
  event_date date,
  event_type text,
  category_id uuid,
  event_text text,
  memo text,
  event_time time,
  event_end_time time,
  is_done boolean,
  event_range_id uuid,
  shared_origin_todo_id uuid,
  shared_origin_user_id uuid,
  shared_group_id uuid,
  shared_created_by uuid,
  is_shared_copy boolean,
  created_at timestamptz
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_category public.event_calendar_categories%rowtype;
  v_group public.calendar_groups%rowtype;
  v_range_id uuid := gen_random_uuid();
  v_end_date date := coalesce(p_end_date, p_start_date);
  v_date date;
  v_author_todo_id uuid;
  v_member record;
  v_member_category_id uuid;
begin
  if v_uid is null then
    raise exception '로그인이 필요합니다.';
  end if;

  if p_start_date is null then
    raise exception '일정 시작 날짜를 입력해 주세요.';
  end if;

  if v_end_date < p_start_date then
    raise exception '종료 날짜는 시작 날짜보다 빠를 수 없습니다.';
  end if;

  if nullif(trim(coalesce(p_event_text, '')), '') is null then
    raise exception '일정 제목을 입력해 주세요.';
  end if;

  select c.*
    into v_category
  from public.event_calendar_categories c
  where c.id = p_category_id
    and c.user_id = v_uid;

  if not found then
    raise exception '카테고리를 찾을 수 없습니다.';
  end if;

  if v_category.is_shared_personal then
    if v_category.shared_group_id is null then
      raise exception '우리 일정 그룹을 선택해야 합니다.';
    end if;

    select g.*
      into v_group
    from public.calendar_groups g
    where g.id = v_category.shared_group_id
      and g.allow_event = true;

    if not found
       or not public.is_calendar_group_member(v_category.shared_group_id, v_uid) then
      raise exception '이 그룹에 이벤트 우리 일정을 추가할 수 없습니다.';
    end if;
  end if;

  for v_date in
    select gs::date
    from generate_series(p_start_date, v_end_date, interval '1 day') gs
  loop
    insert into public.event_calendar_todos (
      user_id, event_date, event_type, category_id, event_text, memo,
      event_time, event_end_time, is_done, event_range_id,
      shared_group_id, shared_created_by, is_shared_copy
    )
    values (
      v_uid, v_date, coalesce(v_category.slug, 'anniversary'), v_category.id,
      trim(p_event_text), coalesce(p_memo, ''),
      coalesce(p_event_time, '00:00'::time), p_event_end_time, false,
      v_range_id,
      case when v_category.is_shared_personal then v_category.shared_group_id else null end,
      case when v_category.is_shared_personal then v_uid else null end,
      false
    )
    returning public.event_calendar_todos.id into v_author_todo_id;

    if v_category.is_shared_personal then
      for v_member in
        select gm.member_user_id as user_id
        from public.get_shared_personal_group_member_ids(v_category.shared_group_id) gm
        where gm.member_user_id <> v_uid
      loop
        v_member_category_id := public.ensure_shared_event_calendar_category(
          v_member.user_id,
          v_category.id
        );

        insert into public.event_calendar_todos (
          user_id, event_date, event_type, category_id, event_text, memo,
          event_time, event_end_time, is_done, event_range_id,
          shared_origin_todo_id, shared_origin_user_id, shared_group_id,
          shared_created_by, is_shared_copy
        )
        values (
          v_member.user_id, v_date, coalesce(v_category.slug, 'anniversary'),
          v_member_category_id, trim(p_event_text), coalesce(p_memo, ''),
          coalesce(p_event_time, '00:00'::time), p_event_end_time, false,
          v_range_id,
          v_author_todo_id, v_uid, v_category.shared_group_id, v_uid, true
        );
      end loop;
    end if;
  end loop;

  return query
  select
    t.id, t.user_id, t.event_date, t.event_type, t.category_id,
    t.event_text, t.memo, t.event_time, t.event_end_time, t.is_done,
    t.event_range_id, t.shared_origin_todo_id, t.shared_origin_user_id,
    t.shared_group_id, t.shared_created_by, t.is_shared_copy, t.created_at
  from public.event_calendar_todos t
  where t.user_id = v_uid
    and t.event_range_id = v_range_id
  order by t.event_date, t.created_at;
end;
$$;

create or replace function public.save_event_calendar_todo_range(
  p_todo_id uuid,
  p_event_text text,
  p_memo text,
  p_event_time time,
  p_event_end_time time,
  p_start_date date,
  p_end_date date,
  p_category_id uuid
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_selected public.event_calendar_todos%rowtype;
  v_root public.event_calendar_todos%rowtype;
  v_author_row public.event_calendar_todos%rowtype;
  v_target public.event_calendar_categories%rowtype;
  v_root_category public.event_calendar_categories%rowtype;
  v_old_group_id uuid;
  v_new_group_id uuid;
  v_range_id uuid;
  v_end_date date := coalesce(p_end_date, p_start_date);
  v_root_ids uuid[];
  v_used_root_ids uuid[] := array[]::uuid[];
  v_removed_root_ids uuid[];
  v_related_ids text[];
  v_date date;
  v_source_root_id uuid;
  v_existing_copy_id uuid;
  v_member record;
  v_member_category_id uuid;
begin
  if v_uid is null then
    raise exception '로그인이 필요합니다.';
  end if;

  if p_start_date is null then
    raise exception '일정 시작 날짜를 입력해 주세요.';
  end if;

  if v_end_date < p_start_date then
    raise exception '종료 날짜는 시작 날짜보다 빠를 수 없습니다.';
  end if;

  if nullif(trim(coalesce(p_event_text, '')), '') is null then
    raise exception '일정 제목을 입력해 주세요.';
  end if;

  select t.*
    into v_selected
  from public.event_calendar_todos t
  where t.id = p_todo_id
    and t.user_id = v_uid;

  if not found then
    raise exception '일정을 찾을 수 없습니다.';
  end if;

  select t.*
    into v_root
  from public.event_calendar_todos t
  where t.id = coalesce(v_selected.shared_origin_todo_id, v_selected.id);

  if not found then
    raise exception '원본 일정을 찾을 수 없습니다.';
  end if;

  select c.*
    into v_target
  from public.event_calendar_categories c
  where c.id = p_category_id
    and c.user_id = v_uid;

  if not found then
    raise exception '카테고리를 찾을 수 없습니다.';
  end if;

  v_range_id := coalesce(v_root.event_range_id, gen_random_uuid());
  v_old_group_id := v_root.shared_group_id;
  v_new_group_id := case
    when v_target.is_shared_personal then v_target.shared_group_id
    else null
  end;

  if v_old_group_id is not null
     and not public.is_calendar_group_member(v_old_group_id, v_uid) then
    raise exception '이 우리 일정을 수정할 권한이 없습니다.';
  end if;

  if v_new_group_id is not null then
    if not public.is_calendar_group_member(v_new_group_id, v_uid)
       or not public.is_calendar_group_member(v_new_group_id, v_root.user_id) then
      raise exception '이 그룹에 우리 일정을 저장할 권한이 없습니다.';
    end if;

    select c.*
      into v_root_category
    from public.event_calendar_categories c
    where c.id = coalesce(v_target.shared_origin_category_id, v_target.id);

    if not found or v_root_category.user_id <> v_root.user_id then
      if v_root.user_id = v_uid then
        v_root_category := v_target;
      else
        select c.*
          into v_root_category
        from public.event_calendar_categories c
        where c.id = public.ensure_shared_event_calendar_category(
          v_root.user_id,
          v_target.id
        );
      end if;
    end if;
  end if;

  if v_old_group_id is distinct from v_new_group_id then
    if v_selected.shared_origin_todo_id is not null or v_root.user_id <> v_uid then
      raise exception '우리 일정 그룹 변경은 원본 작성자만 할 수 있습니다.';
    end if;
  end if;

  if v_old_group_id is not null and v_new_group_id is null then
    if v_selected.shared_origin_todo_id is not null or v_root.user_id <> v_uid then
      raise exception '우리 일정을 개인 일정으로 바꾸려면 원본 작성자 계정에서 저장해야 합니다.';
    end if;
  end if;

  select coalesce(array_agg(t.id order by t.event_date, t.created_at), array[]::uuid[])
    into v_root_ids
  from public.event_calendar_todos t
  where t.user_id = v_root.user_id
    and t.is_shared_copy = false
    and (
      (v_root.event_range_id is not null and t.event_range_id = v_root.event_range_id)
      or (v_root.event_range_id is null and t.id = v_root.id)
    );

  if coalesce(array_length(v_root_ids, 1), 0) = 0 then
    v_root_ids := array[v_root.id];
  end if;

  select coalesce(array_agg(t.id::text), array[]::text[])
    into v_related_ids
  from public.event_calendar_todos t
  where t.id = any(v_root_ids)
     or t.shared_origin_todo_id = any(v_root_ids);

  if v_old_group_id is not null then
    delete from public.calendar_group_shared_events e
    where e.group_id = v_old_group_id
      and e.calendar_type = 'event'
      and v_old_group_id is distinct from v_new_group_id
      and (
        e.source_event_id = any(v_related_ids)
        or e.payload->>'shared_origin_todo_id' = any(v_related_ids)
      );
  end if;

  for v_date in
    select gs::date
    from generate_series(p_start_date, v_end_date, interval '1 day') gs
  loop
    v_source_root_id := null;

    select t.id
      into v_source_root_id
    from public.event_calendar_todos t
    where t.id = any(v_root_ids)
      and t.id <> all(v_used_root_ids)
      and t.event_date = v_date
    order by t.created_at
    limit 1;

    if v_source_root_id is null then
      select t.id
        into v_source_root_id
      from public.event_calendar_todos t
      where t.id = any(v_root_ids)
        and t.id <> all(v_used_root_ids)
      order by t.event_date, t.created_at
      limit 1;
    end if;

    if v_source_root_id is null then
      insert into public.event_calendar_todos (
        user_id, event_date, event_type, category_id, event_text, memo,
        event_time, event_end_time, is_done, event_range_id,
        shared_group_id, shared_created_by, is_shared_copy
      )
      values (
        v_root.user_id, v_date,
        case
          when v_new_group_id is not null then coalesce(v_root_category.slug, v_target.slug, 'anniversary')
          else coalesce(v_target.slug, 'anniversary')
        end,
        case
          when v_new_group_id is not null then v_root_category.id
          else v_target.id
        end,
        trim(p_event_text), coalesce(p_memo, ''),
        coalesce(p_event_time, '00:00'::time), p_event_end_time,
        false, v_range_id,
        v_new_group_id,
        case when v_new_group_id is not null then coalesce(v_root.shared_created_by, v_root.user_id) else null end,
        false
      )
      returning * into v_author_row;
    else
      update public.event_calendar_todos t
      set
        event_date = v_date,
        event_type = case
          when v_new_group_id is not null then coalesce(v_root_category.slug, v_target.slug, 'anniversary')
          else coalesce(v_target.slug, 'anniversary')
        end,
        category_id = case
          when v_new_group_id is not null then v_root_category.id
          else v_target.id
        end,
        event_text = trim(p_event_text),
        memo = coalesce(p_memo, ''),
        event_time = coalesce(p_event_time, '00:00'::time),
        event_end_time = p_event_end_time,
        event_range_id = v_range_id,
        shared_origin_todo_id = null,
        shared_origin_user_id = null,
        shared_group_id = v_new_group_id,
        shared_created_by = case
          when v_new_group_id is not null then coalesce(v_root.shared_created_by, v_root.user_id)
          else null
        end,
        is_shared_copy = false
      where t.id = v_source_root_id
      returning * into v_author_row;
    end if;

    v_used_root_ids := array_append(v_used_root_ids, v_author_row.id);

    if v_new_group_id is not null then
      for v_member in
        select gm.member_user_id as user_id
        from public.get_shared_personal_group_member_ids(v_new_group_id) gm
        where gm.member_user_id <> v_root.user_id
      loop
        v_member_category_id := public.ensure_shared_event_calendar_category(
          v_member.user_id,
          v_root_category.id
        );

        select t.id
          into v_existing_copy_id
        from public.event_calendar_todos t
        where t.user_id = v_member.user_id
          and t.shared_origin_todo_id = v_author_row.id
          and t.is_shared_copy = true
        limit 1;

        if v_existing_copy_id is null then
          insert into public.event_calendar_todos (
            user_id, event_date, event_type, category_id, event_text, memo,
            event_time, event_end_time, is_done, event_range_id,
            shared_origin_todo_id, shared_origin_user_id, shared_group_id,
            shared_created_by, is_shared_copy
          )
          values (
            v_member.user_id, v_author_row.event_date,
            coalesce(v_root_category.slug, v_target.slug, 'anniversary'),
            v_member_category_id, trim(p_event_text), coalesce(p_memo, ''),
            coalesce(p_event_time, '00:00'::time), p_event_end_time,
            v_author_row.is_done, v_range_id,
            v_author_row.id, v_root.user_id, v_new_group_id,
            coalesce(v_root.shared_created_by, v_root.user_id), true
          );
        else
          update public.event_calendar_todos t
          set
            event_date = v_author_row.event_date,
            event_type = coalesce(v_root_category.slug, v_target.slug, 'anniversary'),
            category_id = v_member_category_id,
            event_text = trim(p_event_text),
            memo = coalesce(p_memo, ''),
            event_time = coalesce(p_event_time, '00:00'::time),
            event_end_time = p_event_end_time,
            is_done = v_author_row.is_done,
            event_range_id = v_range_id,
            shared_origin_user_id = v_root.user_id,
            shared_group_id = v_new_group_id,
            shared_created_by = coalesce(v_root.shared_created_by, v_root.user_id),
            is_shared_copy = true
          where t.id = v_existing_copy_id;
        end if;

        v_existing_copy_id := null;
      end loop;

      delete from public.event_calendar_todos t
      where t.shared_origin_todo_id = v_author_row.id
        and t.is_shared_copy = true
        and (
          t.shared_group_id is distinct from v_new_group_id
          or not public.is_calendar_group_member(v_new_group_id, t.user_id)
        );
    else
      delete from public.event_calendar_todos t
      where t.shared_origin_todo_id = v_author_row.id
        and t.is_shared_copy = true;
    end if;

    update public.calendar_group_shared_events e
    set
      event_date = t.event_date,
      event_type = t.event_type,
      title = t.event_text,
      memo = coalesce(t.memo, ''),
      color = c.color,
      payload = coalesce(e.payload, '{}'::jsonb) || jsonb_build_object(
        'isDone', t.is_done,
        'eventTime', t.event_time,
        'eventEndTime', t.event_end_time,
        'categoryName', c.name
      ),
      backed_up_at = now()
    from public.event_calendar_todos t
    left join public.event_calendar_categories c on c.id = t.category_id
    where e.calendar_type = 'event'
      and e.source_event_id = t.id::text
      and (
        t.id = v_author_row.id
        or t.shared_origin_todo_id = v_author_row.id
      );
  end loop;

  select coalesce(array_agg(root_id), array[]::uuid[])
    into v_removed_root_ids
  from unnest(v_root_ids) as root_id
  where root_id <> all(v_used_root_ids);

  if coalesce(array_length(v_removed_root_ids, 1), 0) > 0 then
    delete from public.calendar_group_shared_events e
    where e.calendar_type = 'event'
      and (
        e.source_event_id in (
          select removed_id::text from unnest(v_removed_root_ids) as removed_id
        )
        or e.payload->>'shared_origin_todo_id' in (
          select removed_id::text from unnest(v_removed_root_ids) as removed_id
        )
      );

    delete from public.event_calendar_todos t
    where t.shared_origin_todo_id = any(v_removed_root_ids)
      and t.is_shared_copy = true;

    delete from public.event_calendar_todos t
    where t.id = any(v_removed_root_ids);
  end if;
end;
$$;

create or replace function public.delete_event_calendar_todo_range(
  p_todo_id uuid
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_selected public.event_calendar_todos%rowtype;
  v_root public.event_calendar_todos%rowtype;
  v_root_ids uuid[];
  v_related_ids text[];
begin
  if v_uid is null then
    raise exception '로그인이 필요합니다.';
  end if;

  select t.*
    into v_selected
  from public.event_calendar_todos t
  where t.id = p_todo_id
    and t.user_id = v_uid;

  if not found then
    raise exception '삭제할 일정을 찾을 수 없습니다.';
  end if;

  select t.*
    into v_root
  from public.event_calendar_todos t
  where t.id = coalesce(v_selected.shared_origin_todo_id, v_selected.id);

  if not found then
    raise exception '삭제할 원본 일정을 찾을 수 없습니다.';
  end if;

  if v_root.shared_group_id is not null
     and not public.is_calendar_group_member(v_root.shared_group_id, v_uid) then
    raise exception '이 우리 일정을 삭제할 권한이 없습니다.';
  end if;

  select coalesce(array_agg(t.id order by t.event_date), array[]::uuid[])
    into v_root_ids
  from public.event_calendar_todos t
  where t.user_id = v_root.user_id
    and t.is_shared_copy = false
    and (
      (v_root.event_range_id is not null and t.event_range_id = v_root.event_range_id)
      or (v_root.event_range_id is null and t.id = v_root.id)
    );

  if coalesce(array_length(v_root_ids, 1), 0) = 0 then
    v_root_ids := array[v_root.id];
  end if;

  select coalesce(array_agg(t.id::text), array[]::text[])
    into v_related_ids
  from public.event_calendar_todos t
  where t.id = any(v_root_ids)
     or t.shared_origin_todo_id = any(v_root_ids);

  if v_root.shared_group_id is not null then
    delete from public.calendar_group_shared_events e
    where e.group_id = v_root.shared_group_id
      and e.calendar_type = 'event'
      and (
        e.source_event_id = any(v_related_ids)
        or e.payload->>'shared_origin_todo_id' = any(v_related_ids)
      );
  end if;

  delete from public.event_calendar_todos t
  where t.shared_origin_todo_id = any(v_root_ids)
    and t.is_shared_copy = true;

  delete from public.event_calendar_todos t
  where t.id = any(v_root_ids);
end;
$$;

create or replace function public.create_event_calendar_todo_with_shared_personal(
  p_event_date date,
  p_category_id uuid,
  p_event_text text,
  p_memo text default '',
  p_event_time time default '00:00'
)
returns table (
  id uuid,
  user_id uuid,
  event_date date,
  event_type text,
  category_id uuid,
  event_text text,
  memo text,
  event_time time,
  is_done boolean,
  created_at timestamptz
)
language plpgsql
security definer
set search_path = public
as $$
begin
  return query
  select
    created.id,
    created.user_id,
    created.event_date,
    created.event_type,
    created.category_id,
    created.event_text,
    created.memo,
    created.event_time,
    created.is_done,
    created.created_at
  from public.create_event_calendar_todo_range(
    p_event_date,
    p_event_date,
    p_category_id,
    p_event_text,
    p_memo,
    p_event_time,
    null
  ) created;
end;
$$;

create or replace function public.save_event_calendar_todo(
  p_todo_id uuid,
  p_event_text text,
  p_memo text,
  p_event_time time,
  p_event_end_time time,
  p_event_date date,
  p_category_id uuid
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_selected public.event_calendar_todos%rowtype;
  v_root public.event_calendar_todos%rowtype;
  v_saved_root public.event_calendar_todos%rowtype;
  v_target public.event_calendar_categories%rowtype;
  v_root_category public.event_calendar_categories%rowtype;
  v_old_group_id uuid;
  v_new_group_id uuid;
  v_range_id uuid;
  v_copy record;
  v_copy_category_id uuid;
  v_existing_copy_id uuid;
begin
  if v_uid is null then
    raise exception '로그인이 필요합니다.';
  end if;

  if nullif(trim(coalesce(p_event_text, '')), '') is null then
    raise exception '일정 제목을 입력해 주세요.';
  end if;

  if p_event_date is null then
    raise exception '일정 날짜를 입력해 주세요.';
  end if;

  select t.*
    into v_selected
  from public.event_calendar_todos t
  where t.id = p_todo_id
    and t.user_id = v_uid;

  if not found then
    raise exception '일정을 찾을 수 없습니다.';
  end if;

  select t.*
    into v_root
  from public.event_calendar_todos t
  where t.id = coalesce(v_selected.shared_origin_todo_id, v_selected.id);

  if not found then
    raise exception '원본 일정을 찾을 수 없습니다.';
  end if;

  select c.*
    into v_target
  from public.event_calendar_categories c
  where c.id = p_category_id
    and c.user_id = v_uid;

  if not found then
    raise exception '카테고리를 찾을 수 없습니다.';
  end if;

  v_old_group_id := coalesce(v_selected.shared_group_id, v_root.shared_group_id);
  v_new_group_id := case
    when v_target.is_shared_personal then v_target.shared_group_id
    else null
  end;
  v_range_id := coalesce(v_root.event_range_id, gen_random_uuid());

  if v_old_group_id is not null
     and not public.is_calendar_group_member(v_old_group_id, v_uid) then
    raise exception '이 우리 일정을 수정할 권한이 없습니다.';
  end if;

  if v_new_group_id is not null then
    if not public.is_calendar_group_member(v_new_group_id, v_uid)
       or not public.is_calendar_group_member(v_new_group_id, v_root.user_id) then
      raise exception '이 그룹에 우리 일정을 저장할 권한이 없습니다.';
    end if;

    select c.*
      into v_root_category
    from public.event_calendar_categories c
    where c.id = coalesce(v_target.shared_origin_category_id, v_target.id);

    if not found or v_root_category.user_id <> v_root.user_id then
      if v_root.user_id = v_uid then
        v_root_category := v_target;
      else
        select c.*
          into v_root_category
        from public.event_calendar_categories c
        where c.id = public.ensure_shared_event_calendar_category(
          v_root.user_id,
          v_target.id
        );
      end if;
    end if;
  end if;

  if v_old_group_id is distinct from v_new_group_id then
    if v_selected.shared_origin_todo_id is not null or v_root.user_id <> v_uid then
      raise exception '우리 일정 그룹 변경은 원본 작성자만 할 수 있습니다.';
    end if;
  end if;

  if v_old_group_id is not null and v_new_group_id is null then
    if v_selected.shared_origin_todo_id is not null or v_root.user_id <> v_uid then
      raise exception '우리 일정을 개인 일정으로 바꾸려면 원본 작성자 계정에서 저장해야 합니다.';
    end if;
  end if;

  if v_old_group_id is not null and v_old_group_id is distinct from v_new_group_id then
    delete from public.calendar_group_shared_events e
    where e.group_id = v_old_group_id
      and e.calendar_type = 'event'
      and (
        e.source_event_id = v_root.id::text
        or e.source_event_id in (
          select t.id::text
          from public.event_calendar_todos t
          where t.shared_origin_todo_id = v_root.id
        )
        or e.payload->>'shared_origin_todo_id' = v_root.id::text
      );
  end if;

  update public.event_calendar_todos t
  set
    event_text = trim(p_event_text),
    memo = coalesce(p_memo, ''),
    event_time = coalesce(p_event_time, '00:00'::time),
    event_end_time = p_event_end_time,
    event_date = p_event_date,
    event_range_id = v_range_id,
    event_type = case
      when v_new_group_id is not null then coalesce(v_root_category.slug, v_target.slug, 'anniversary')
      else coalesce(v_target.slug, 'anniversary')
    end,
    category_id = case
      when v_new_group_id is not null then v_root_category.id
      else v_target.id
    end,
    shared_origin_todo_id = null,
    shared_origin_user_id = null,
    shared_group_id = v_new_group_id,
    shared_created_by = case
      when v_new_group_id is not null then coalesce(v_root.shared_created_by, v_root.user_id)
      else null
    end,
    is_shared_copy = false
  where t.id = v_root.id
  returning * into v_saved_root;

  if v_new_group_id is not null then
    for v_copy in
      select gm.member_user_id as user_id
      from public.get_shared_personal_group_member_ids(v_new_group_id) gm
      where gm.member_user_id <> v_root.user_id
    loop
      v_copy_category_id := public.ensure_shared_event_calendar_category(
        v_copy.user_id,
        v_root_category.id
      );

      select t.id
        into v_existing_copy_id
      from public.event_calendar_todos t
      where t.user_id = v_copy.user_id
        and t.shared_origin_todo_id = v_saved_root.id
        and t.is_shared_copy = true
      limit 1;

      if v_existing_copy_id is null then
        insert into public.event_calendar_todos (
          user_id, event_date, event_type, category_id, event_text, memo,
          event_time, event_end_time, is_done, event_range_id,
          shared_origin_todo_id, shared_origin_user_id, shared_group_id,
          shared_created_by, is_shared_copy
        )
        values (
          v_copy.user_id, v_saved_root.event_date,
          coalesce(v_root_category.slug, v_target.slug, 'anniversary'),
          v_copy_category_id, trim(p_event_text), coalesce(p_memo, ''),
          coalesce(p_event_time, '00:00'::time), p_event_end_time,
          v_saved_root.is_done, v_range_id,
          v_saved_root.id, v_root.user_id, v_new_group_id,
          coalesce(v_root.shared_created_by, v_root.user_id), true
        );
      else
        update public.event_calendar_todos t
        set
          event_date = v_saved_root.event_date,
          event_type = coalesce(v_root_category.slug, v_target.slug, 'anniversary'),
          category_id = v_copy_category_id,
          event_text = trim(p_event_text),
          memo = coalesce(p_memo, ''),
          event_time = coalesce(p_event_time, '00:00'::time),
          event_end_time = p_event_end_time,
          is_done = v_saved_root.is_done,
          event_range_id = v_range_id,
          shared_origin_user_id = v_root.user_id,
          shared_group_id = v_new_group_id,
          shared_created_by = coalesce(v_root.shared_created_by, v_root.user_id),
          is_shared_copy = true
        where t.id = v_existing_copy_id;
      end if;

      v_existing_copy_id := null;
    end loop;

    delete from public.event_calendar_todos t
    where t.shared_origin_todo_id = v_saved_root.id
      and t.is_shared_copy = true
      and (
        t.shared_group_id is distinct from v_new_group_id
        or not public.is_calendar_group_member(v_new_group_id, t.user_id)
      );
  else
    delete from public.event_calendar_todos t
    where t.shared_origin_todo_id = v_saved_root.id
      and t.is_shared_copy = true;
  end if;

  update public.calendar_group_shared_events e
  set
    event_date = t.event_date,
    event_type = t.event_type,
    title = t.event_text,
    memo = coalesce(t.memo, ''),
    color = c.color,
    payload = coalesce(e.payload, '{}'::jsonb) || jsonb_build_object(
      'isDone', t.is_done,
      'eventTime', t.event_time,
      'eventEndTime', t.event_end_time,
      'categoryName', c.name
    ),
    backed_up_at = now()
  from public.event_calendar_todos t
  left join public.event_calendar_categories c on c.id = t.category_id
  where e.calendar_type = 'event'
    and e.source_event_id = t.id::text
    and (
      t.id = v_saved_root.id
      or t.shared_origin_todo_id = v_saved_root.id
    );
end;
$$;

revoke all on function public.create_event_calendar_todo_range(
  date, date, uuid, text, text, time, time
) from public;
revoke all on function public.create_event_calendar_todo_range(
  date, date, uuid, text, text, time, time
) from anon;
grant execute on function public.create_event_calendar_todo_range(
  date, date, uuid, text, text, time, time
) to authenticated;

revoke all on function public.save_event_calendar_todo_range(
  uuid, text, text, time, time, date, date, uuid
) from public;
revoke all on function public.save_event_calendar_todo_range(
  uuid, text, text, time, time, date, date, uuid
) from anon;
grant execute on function public.save_event_calendar_todo_range(
  uuid, text, text, time, time, date, date, uuid
) to authenticated;

revoke all on function public.delete_event_calendar_todo_range(uuid) from public;
revoke all on function public.delete_event_calendar_todo_range(uuid) from anon;
grant execute on function public.delete_event_calendar_todo_range(uuid) to authenticated;

revoke all on function public.create_event_calendar_todo_with_shared_personal(
  date, uuid, text, text, time
) from public;
revoke all on function public.create_event_calendar_todo_with_shared_personal(
  date, uuid, text, text, time
) from anon;
grant execute on function public.create_event_calendar_todo_with_shared_personal(
  date, uuid, text, text, time
) to authenticated;

revoke all on function public.save_event_calendar_todo(
  uuid, text, text, time, time, date, uuid
) from public;
revoke all on function public.save_event_calendar_todo(
  uuid, text, text, time, time, date, uuid
) from anon;
grant execute on function public.save_event_calendar_todo(
  uuid, text, text, time, time, date, uuid
) to authenticated;


-- =========================================================
-- 2026-07-12 금일 방문자 중복 집계 방지
-- 익명/회원 방문자 일일 1회 집계 및 기존 중복 데이터 정리
-- =========================================================

-- =========================================================
-- 1) 사전 확인
-- =========================================================

select
  'today_raw_rows' as check_name,
  count(*)::integer as row_count
from public.site_daily_visits
where visit_date = (now() at time zone 'Asia/Seoul')::date;

select
  'duplicate_user_visits' as check_name,
  visit_date,
  user_id,
  count(*)::integer as row_count
from public.site_daily_visits
where user_id is not null
group by visit_date, user_id
having count(*) > 1
order by visit_date desc, row_count desc
limit 50;

select
  'duplicate_visitor_keys' as check_name,
  visit_date,
  visitor_key,
  count(*)::integer as row_count
from public.site_daily_visits
where visitor_key is not null
group by visit_date, visitor_key
having count(*) > 1
order by visit_date desc, row_count desc
limit 50;

-- =========================================================
-- 2) 중복 데이터 정리
--    기준: 같은 날짜/같은 식별자는 created_at이 가장 오래된 1건만 유지
-- =========================================================

begin;

alter table public.site_daily_visits
  add column if not exists guest_id uuid;

update public.site_daily_visits
set guest_id = replace(visitor_key, 'guest:', '')::uuid
where guest_id is null
  and visitor_key ~ '^guest:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

update public.site_daily_visits
set guest_id = id
where guest_id is null
  and user_id is null;

with ranked as (
  select
    id,
    row_number() over (
      partition by visit_date, user_id
      order by created_at asc, id asc
    ) as row_number
  from public.site_daily_visits
  where user_id is not null
)
delete from public.site_daily_visits v
using ranked r
where v.id = r.id
  and r.row_number > 1;

with ranked as (
  select
    id,
    row_number() over (
      partition by visit_date, guest_id
      order by created_at asc, id asc
    ) as row_number
  from public.site_daily_visits
  where user_id is null
    and guest_id is not null
)
delete from public.site_daily_visits v
using ranked r
where v.id = r.id
  and r.row_number > 1;

update public.site_daily_visits
set visitor_key = 'user:' || user_id::text
where user_id is not null
  and visitor_key is distinct from 'user:' || user_id::text;

update public.site_daily_visits
set visitor_key = 'guest:' || guest_id::text
where user_id is null
  and guest_id is not null
  and visitor_key is distinct from 'guest:' || guest_id::text;

with ranked as (
  select
    id,
    row_number() over (
      partition by visit_date, visitor_key
      order by created_at asc, id asc
    ) as row_number
  from public.site_daily_visits
  where visitor_key is not null
)
delete from public.site_daily_visits v
using ranked r
where v.id = r.id
  and r.row_number > 1;

-- =========================================================
-- 3) constraint/index 생성
-- =========================================================

alter table public.site_daily_visits
  alter column visitor_key set not null;

do $$
begin
  if not exists (
    select 1
    from pg_constraint
    where conname = 'site_daily_visits_visitor_key_format_check'
      and conrelid = 'public.site_daily_visits'::regclass
  ) then
    alter table public.site_daily_visits
      add constraint site_daily_visits_visitor_key_format_check
      check (visitor_key ~ '^(user|guest):[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$');
  end if;
end;
$$;

do $$
begin
  if not exists (
    select 1
    from pg_constraint
    where conname = 'site_daily_visits_visit_date_visitor_key_key'
      and conrelid = 'public.site_daily_visits'::regclass
  ) then
    alter table public.site_daily_visits
      add constraint site_daily_visits_visit_date_visitor_key_key
      unique (visit_date, visitor_key);
  end if;
end;
$$;

create unique index if not exists site_daily_visits_visit_date_guest_id_anon_uidx
  on public.site_daily_visits (visit_date, guest_id)
  where user_id is null
    and guest_id is not null;

alter table public.site_daily_visits enable row level security;
revoke all on table public.site_daily_visits from public, anon, authenticated;

-- =========================================================
-- 4) RPC 함수 생성 또는 교체
-- =========================================================

drop function if exists public.record_today_site_visit();

create or replace function public.record_today_site_visit(p_guest_id uuid default null)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := auth.uid();
  v_visit_date date := (now() at time zone 'Asia/Seoul')::date;
  v_user_key text;
  v_guest_key text;
  v_user_visit_id uuid;
  v_guest_visit_id uuid;
begin
  if p_guest_id is not null then
    v_guest_key := 'guest:' || p_guest_id::text;
  end if;

  if v_user_id is not null then
    v_user_key := 'user:' || v_user_id::text;
  end if;

  if v_user_id is null and p_guest_id is null then
    return false;
  end if;

  if v_user_key is not null then
    perform pg_advisory_xact_lock(
      hashtextextended(
        'site_daily_visits:' || v_visit_date::text || ':' || v_user_key,
        0
      )
    );
  end if;

  if v_guest_key is not null then
    perform pg_advisory_xact_lock(
      hashtextextended(
        'site_daily_visits:' || v_visit_date::text || ':' || v_guest_key,
        0
      )
    );
  end if;

  if v_user_id is not null then
    select id
      into v_user_visit_id
    from public.site_daily_visits
    where visit_date = v_visit_date
      and user_id = v_user_id
    order by created_at asc, id asc
    limit 1
    for update;

    if v_user_visit_id is not null then
      update public.site_daily_visits
      set
        visitor_key = v_user_key,
        guest_id = coalesce(guest_id, p_guest_id)
      where id = v_user_visit_id;

      if p_guest_id is not null then
        delete from public.site_daily_visits
        where visit_date = v_visit_date
          and user_id is null
          and (
            guest_id = p_guest_id
            or visitor_key = v_guest_key
          );
      end if;

      return true;
    end if;

    if p_guest_id is not null then
      select id
        into v_guest_visit_id
      from public.site_daily_visits
      where visit_date = v_visit_date
        and user_id is null
        and (
          guest_id = p_guest_id
          or visitor_key = v_guest_key
        )
      order by created_at asc, id asc
      limit 1
      for update;

      if v_guest_visit_id is not null then
        update public.site_daily_visits
        set
          user_id = v_user_id,
          guest_id = p_guest_id,
          visitor_key = v_user_key
        where id = v_guest_visit_id;

        return true;
      end if;
    end if;

    insert into public.site_daily_visits (user_id, guest_id, visitor_key, visit_date)
    values (v_user_id, p_guest_id, v_user_key, v_visit_date)
    on conflict on constraint site_daily_visits_visit_date_visitor_key_key
    do update
      set
        user_id = excluded.user_id,
        guest_id = coalesce(public.site_daily_visits.guest_id, excluded.guest_id);

    if p_guest_id is not null then
      delete from public.site_daily_visits
      where visit_date = v_visit_date
        and user_id is null
        and (
          guest_id = p_guest_id
          or visitor_key = v_guest_key
        );
    end if;

    return true;
  end if;

  if exists (
    select 1
    from public.site_daily_visits
    where visit_date = v_visit_date
      and guest_id = p_guest_id
      and user_id is not null
  ) then
    return true;
  end if;

  insert into public.site_daily_visits (user_id, guest_id, visitor_key, visit_date)
  values (null, p_guest_id, v_guest_key, v_visit_date)
  on conflict on constraint site_daily_visits_visit_date_visitor_key_key
  do nothing;

  return true;
end;
$$;

create or replace function public.get_site_stats()
returns table (member_count integer, today_visit_count integer)
language sql
stable
security definer
set search_path = ''
as $$
  select
    (select count(*)::integer from auth.users) as member_count,
    (
      select count(*)::integer
      from (
        select distinct
          coalesce(
            'user:' || user_id::text,
            'guest:' || guest_id::text,
            visitor_key
          ) as daily_visitor_key
        from public.site_daily_visits
        where visit_date = (now() at time zone 'Asia/Seoul')::date
      ) unique_daily_visitors
      where daily_visitor_key is not null
    ) as today_visit_count;
$$;

