-- 구버전 클라이언트가 study/work 공유 RPC를 다시 호출하지 못하게 한다.
do $$
declare
  v_function record;
begin
  for v_function in
    select p.oid::regprocedure as signature
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and (p.proname like '%study%shared_personal%'
        or p.proname like '%work%shared_personal%')
  loop
    execute format('revoke all on function %s from public, anon, authenticated', v_function.signature);
  end loop;
end;
$$;

create or replace function public.save_study_calendar_todo(
  p_todo_id uuid,
  p_todo_text text,
  p_memo text,
  p_todo_date date,
  p_category_id uuid
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_category public.study_calendar_categories%rowtype;
begin
  if v_uid is null then raise exception '로그인이 필요합니다.'; end if;
  if p_todo_date is null then raise exception '날짜를 선택해 주세요.'; end if;
  if nullif(trim(coalesce(p_todo_text, '')), '') is null then raise exception '제목을 입력해 주세요.'; end if;

  select c.* into v_category
  from public.study_calendar_categories c
  where c.id = p_category_id and c.user_id = v_uid;
  if not found then raise exception '사용할 수 없는 카테고리입니다.'; end if;

  update public.study_calendar_todos
  set todo_text = trim(p_todo_text), memo = coalesce(p_memo, ''),
      todo_date = p_todo_date, category_id = v_category.id, todo_type = v_category.slug,
      shared_group_id = null, shared_created_by = null,
      shared_origin_todo_id = null, shared_origin_user_id = null, is_shared_copy = false
  where id = p_todo_id and user_id = v_uid;
  if not found then raise exception '본인 소유의 일정을 찾을 수 없습니다.'; end if;
end;
$$;

create or replace function public.save_work_calendar_todo(
  p_todo_id uuid,
  p_work_text text,
  p_memo text,
  p_work_date date,
  p_category_id uuid,
  p_overwrite boolean default false
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_selected public.work_calendar_todos%rowtype;
  v_category public.work_calendar_categories%rowtype;
  v_conflict_id uuid;
begin
  if v_uid is null then raise exception '로그인이 필요합니다.'; end if;
  if p_work_date is null then raise exception '날짜를 선택해 주세요.'; end if;

  lock table public.work_calendar_todos in share row exclusive mode;

  select t.* into v_selected
  from public.work_calendar_todos t
  where t.id = p_todo_id and t.user_id = v_uid
  for update;
  if not found then raise exception '본인 소유의 일정을 찾을 수 없습니다.'; end if;

  select c.* into v_category
  from public.work_calendar_categories c
  where c.id = p_category_id and c.user_id = v_uid;
  if not found then raise exception '사용할 수 없는 카테고리입니다.'; end if;

  select t.id into v_conflict_id
  from public.work_calendar_todos t
  where t.user_id = v_uid and t.work_date = p_work_date and t.id <> p_todo_id
  for update;

  if v_conflict_id is not null and not p_overwrite then
    raise exception 'WORK_DATE_CONFLICT: 변경하려는 날짜에 이미 일정이 있습니다.';
  end if;
  if v_conflict_id is not null then
    delete from public.work_calendar_todos where id = v_conflict_id and user_id = v_uid;
  end if;

  update public.work_calendar_todos
  set work_text = coalesce(nullif(trim(p_work_text), ''), v_category.name),
      memo = coalesce(p_memo, ''), work_date = p_work_date,
      category_id = v_category.id, work_type = v_category.slug,
      shared_group_id = null, shared_created_by = null,
      shared_origin_todo_id = null, shared_origin_user_id = null, is_shared_copy = false
  where id = p_todo_id and user_id = v_uid;
end;
$$;

revoke all on function public.save_study_calendar_todo(uuid, text, text, date, uuid) from public, anon;
grant execute on function public.save_study_calendar_todo(uuid, text, text, date, uuid) to authenticated;
revoke all on function public.save_work_calendar_todo(uuid, text, text, date, uuid, boolean) from public, anon;
grant execute on function public.save_work_calendar_todo(uuid, text, text, date, uuid, boolean) to authenticated;

do $$
declare
  v_study_group_event_count bigint;
  v_work_group_event_count bigint;
  v_event_group_event_count bigint;
begin
  if exists (select 1 from public.study_calendar_todos where is_shared_copy = true)
    or exists (select 1 from public.work_calendar_todos where is_shared_copy = true)
    or exists (select 1 from public.study_calendar_categories where is_shared_personal = true or shared_group_id is not null)
    or exists (select 1 from public.work_calendar_categories where is_shared_personal = true or shared_group_id is not null) then
    raise exception 'study/work 공유 데이터 정리 검증에 실패했습니다.';
  end if;

  select
    study_group_event_count,
    work_group_event_count,
    event_group_event_count
  into
    v_study_group_event_count,
    v_work_group_event_count,
    v_event_group_event_count
  from public.study_work_shared_cleanup_run_20260718
  where run_key = 'remove-study-work-shared-v1';

  if not found then
    raise exception 'study/work 공유 정리 실행 guard를 찾을 수 없습니다.';
  end if;

  if (select count(*) from public.calendar_group_shared_events where calendar_type = 'study')
     <> v_study_group_event_count then
    raise exception 'study 그룹 백업 데이터 보존 검증에 실패했습니다.';
  end if;

  if (select count(*) from public.calendar_group_shared_events where calendar_type = 'work')
     <> v_work_group_event_count then
    raise exception 'work 그룹 백업 데이터 보존 검증에 실패했습니다.';
  end if;

  if (select count(*) from public.calendar_group_shared_events where calendar_type = 'event')
     <> v_event_group_event_count then
    raise exception 'event 그룹 백업 데이터 보존 검증에 실패했습니다.';
  end if;
end;
$$;

update public.study_work_shared_cleanup_run_20260718
set completed_at = now()
where run_key = 'remove-study-work-shared-v1';

commit;

-- =========================================================
-- 2026-07-21 프로필 대표 BGM 설정 및 공개 조회 기능
-- =========================================================

begin;

alter table public.profiles
add column if not exists profile_featured_bgm_item_id text;

comment on column public.profiles.profile_featured_bgm_item_id
is '프로필 진입 시 재생할 대표 BGM 상점 아이템 ID';

-- 재실행 시에도 소유권 또는 BGM 분류가 맞지 않는 기존 값은 공개하지 않는다.
update public.profiles p
set profile_featured_bgm_item_id = null
where p.profile_featured_bgm_item_id is not null
  and not exists (
    select 1
    from public.user_store_items usi
    where usi.user_id = p.id
      and usi.item_id = p.profile_featured_bgm_item_id
      and usi.item_category = 'bgm'
  );

create or replace function public.enforce_profile_featured_bgm_ownership()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if nullif(trim(coalesce(new.profile_featured_bgm_item_id, '')), '') is null then
    new.profile_featured_bgm_item_id := null;
    return new;
  end if;

  new.profile_featured_bgm_item_id := trim(new.profile_featured_bgm_item_id);

  if not exists (
    select 1
    from public.user_store_items usi
    where usi.user_id = new.id
      and usi.item_id = new.profile_featured_bgm_item_id
      and usi.item_category = 'bgm'
  ) then
    raise exception '보유한 BGM 상품만 프로필 대표 BGM으로 설정할 수 있습니다.';
  end if;

  return new;
end;
$$;

revoke all on function public.enforce_profile_featured_bgm_ownership()
from public, anon, authenticated;

drop trigger if exists trg_enforce_profile_featured_bgm_ownership
on public.profiles;

create trigger trg_enforce_profile_featured_bgm_ownership
before insert or update of profile_featured_bgm_item_id
on public.profiles
for each row
execute function public.enforce_profile_featured_bgm_ownership();

create or replace view public.public_profiles as
select
  id,
  nickname,
  bio,
  profile_image_url,
  equipped_character_image_url,
  equipped_character_effect_item_id,
  equipped_profile_background_item_id,
  equipped_profile_frame_item_id,
  created_at,
  updated_at,
  profile_featured_bgm_item_id
from public.profiles;

grant select on public.public_profiles to anon, authenticated;

create or replace function public.set_my_profile_featured_bgm(p_item_id text)
returns table (
  success boolean,
  message text,
  profile_featured_bgm_item_id text
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := auth.uid();
  v_item_id text := nullif(trim(coalesce(p_item_id, '')), '');
begin
  if v_user_id is null then
    return query
    select false, '로그인이 필요해.', null::text;
    return;
  end if;

  if v_item_id is not null
     and (char_length(v_item_id) > 100 or v_item_id !~ '^[A-Za-z0-9_-]+$') then
    return query
    select false, '대표 BGM 상품 정보가 올바르지 않아.', null::text;
    return;
  end if;

  if v_item_id is not null
     and not exists (
       select 1
       from public.user_store_items usi
       where usi.user_id = v_user_id
         and usi.item_id = v_item_id
         and usi.item_category = 'bgm'
     ) then
    return query
    select false, '보유한 BGM 상품만 대표로 설정할 수 있어.', null::text;
    return;
  end if;

  update public.profiles p
  set profile_featured_bgm_item_id = v_item_id,
      updated_at = now()
  where p.id = v_user_id;

  if not found then
    return query
    select false, '프로필을 찾을 수 없어.', null::text;
    return;
  end if;

  return query
  select
    true,
    case
      when v_item_id is null then '대표 BGM을 해제했어.'
      else '대표 BGM을 설정했어.'
    end,
    v_item_id;
end;
$$;

revoke all on function public.set_my_profile_featured_bgm(text)
from public, anon;
grant execute on function public.set_my_profile_featured_bgm(text)
to authenticated;

commit;

-- =========================================================
-- 2026-07-22 댓글·답글 수정 내용 및 최신 작성자 정보의 알림 반영
-- - 기존 알림의 comment_id / actor_user_id로 원본을 조회한다.
-- - 알림 읽음 상태, 생성 시각, 클릭 대상은 변경하지 않는다.
-- - 호출한 로그인 사용자의 알림만 반환한다.
-- =========================================================

begin;

create or replace function public.get_my_notifications_current(
  p_offset integer default 0,
  p_limit integer default 10,
  p_unread_only boolean default false
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := auth.uid();
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_limit integer := least(greatest(coalesce(p_limit, 10), 1), 100);
  v_unread_only boolean := coalesce(p_unread_only, false);
  v_total_count bigint := 0;
  v_items jsonb := '[]'::jsonb;
begin
  if v_user_id is null then
    return jsonb_build_object('count', 0, 'items', '[]'::jsonb);
  end if;

  select count(*)
    into v_total_count
  from public.user_notifications n
  where n.recipient_user_id = v_user_id
    and (not v_unread_only or n.is_read = false);

  with source_rows as (
    select
      n.id,
      n.post_id,
      n.comment_id,
      n.notification_type,
      n.title as stored_title,
      n.message as stored_message,
      n.action_url,
      n.item_id,
      n.is_read,
      n.created_at,
      c.id as source_comment_id,
      c.body as current_comment_body,
      c.parent_comment_id,
      coalesce(
        nullif(btrim(p.nickname), ''),
        nullif(btrim(c.author_nickname), ''),
        nullif(btrim(n.actor_nickname), ''),
        '익명'
      ) as current_actor_nickname
    from public.user_notifications n
    left join public.post_comments c
      on c.id = n.comment_id
    left join public.profiles p
      on p.id = n.actor_user_id
    where n.recipient_user_id = v_user_id
      and (not v_unread_only or n.is_read = false)
    order by n.created_at desc, n.id desc
    offset v_offset
    limit v_limit
  ),
  current_items as (
    select
      sr.id,
      sr.current_actor_nickname as actor_nickname,
      sr.post_id,
      sr.comment_id,
      sr.notification_type,
      case
        when sr.source_comment_id is not null
             and sr.notification_type = 'post_comment'
          then format(
            '%s님이 네 게시물에 %s을 남겼어.',
            sr.current_actor_nickname,
            case when sr.parent_comment_id is null then '댓글' else '답글' end
          )
        when sr.source_comment_id is not null
             and sr.notification_type = 'post_participant_comment'
          then format(
            '%s님이 네가 참여한 게시물에 %s을 남겼어.',
            sr.current_actor_nickname,
            case when sr.parent_comment_id is null then '댓글' else '답글' end
          )
        else sr.stored_title
      end as title,
      case
        when sr.source_comment_id is not null
             and sr.notification_type in (
               'post_comment',
               'post_participant_comment'
             )
          then left(
            regexp_replace(
              coalesce(sr.current_comment_body, ''),
              '\s+',
              ' ',
              'g'
            ),
            120
          )
        else sr.stored_message
      end as message,
      sr.action_url,
      sr.item_id,
      sr.is_read,
      sr.created_at
    from source_rows sr
  )
  select coalesce(
    jsonb_agg(
      to_jsonb(current_items)
      order by current_items.created_at desc, current_items.id desc
    ),
    '[]'::jsonb
  )
    into v_items
  from current_items;

  return jsonb_build_object(
    'count', v_total_count,
    'items', v_items
  );
end;
$$;

revoke all on function public.get_my_notifications_current(integer, integer, boolean)
from public, anon;

grant execute on function public.get_my_notifications_current(integer, integer, boolean)
to authenticated;

comment on function public.get_my_notifications_current(integer, integer, boolean)
